fn push_kv_line(log: &mut String, label: &str, value: impl AsRef<str>) {
    log.push_str(label);
    log.push_str(": ");
    log.push_str(&escape_log_value(value.as_ref()));
    log.push('\n');
}

fn push_optional_kv_line(log: &mut String, label: &str, value: Option<&str>) {
    if let Some(value) = value.map(str::trim).filter(|value| !value.is_empty()) {
        push_kv_line(log, label, value);
    }
}

fn path_log_value(path: &Path) -> String {
    escape_log_value(&path.display().to_string())
}

fn escape_log_value(value: &str) -> String {
    let mut escaped = String::with_capacity(value.len());
    for ch in value.chars() {
        match ch {
            '\n' => escaped.push_str("\\n"),
            '\r' => escaped.push_str("\\r"),
            '\t' => escaped.push_str("\\t"),
            ch if ch.is_control() => escaped.push_str(&format!("\\u{{{:x}}}", ch as u32)),
            ch => escaped.push(ch),
        }
    }
    escaped
}

fn conversion_log_album_year(metadata: &AlbumMetadata) -> Option<&str> {
    metadata.date.as_deref().and_then(first_four_digit_run)
}

fn first_four_digit_run(value: &str) -> Option<&str> {
    let bytes = value.as_bytes();
    if bytes.len() < 4 {
        return None;
    }
    for start in 0..=bytes.len() - 4 {
        if bytes[start..start + 4]
            .iter()
            .all(|byte| byte.is_ascii_digit())
        {
            return value.get(start..start + 4);
        }
    }
    None
}

fn conversion_log_catalog_number(extra: &BTreeMap<String, String>) -> Option<&str> {
    for (key, value) in extra {
        let normalized = normalize_extra_key(key);
        if matches!(
            normalized.as_str(),
            "catno"
                | "catnumber"
                | "catalog"
                | "catalogid"
                | "catalogno"
                | "catalognumber"
                | "catalogue"
                | "catalogueid"
                | "catalogueno"
                | "cataloguenumber"
                | "sacdalbumcatalognumber"
        ) {
            let trimmed = value.trim();
            if !trimmed.is_empty() {
                return Some(trimmed);
            }
        }
    }
    None
}

fn normalize_extra_key(key: &str) -> String {
    key.chars()
        .filter(|ch| ch.is_ascii_alphanumeric())
        .flat_map(|ch| ch.to_lowercase())
        .collect()
}

fn yes_no(value: bool) -> &'static str {
    if value {
        "Yes"
    } else {
        "No"
    }
}

fn format_bytes(bytes: u64) -> String {
    const UNITS: [&str; 5] = ["B", "KB", "MB", "GB", "TB"];
    if bytes < 1024 {
        return format!("{bytes} B");
    }
    let mut value = bytes as f64;
    let mut unit = 0_usize;
    while value >= 1024.0 && unit < UNITS.len() - 1 {
        value /= 1024.0;
        unit += 1;
    }
    format!("{value:.1} {}", UNITS[unit])
}

fn format_duration(duration: Duration) -> String {
    let seconds = duration.as_secs();
    let millis = duration.subsec_millis();
    if seconds == 0 {
        if millis == 0 {
            return "0s".to_string();
        }
        return format!("0.{millis:03}s");
    }
    if seconds < 60 {
        if millis == 0 {
            return format!("{seconds}s");
        }
        return format!("{seconds}.{millis:03}s");
    }
    let minutes = seconds / 60;
    let remaining_seconds = seconds % 60;
    if minutes < 60 {
        return format!("{minutes}m {remaining_seconds}s");
    }
    let hours = minutes / 60;
    let remaining_minutes = minutes % 60;
    format!("{hours}h {remaining_minutes}m {remaining_seconds}s")
}

fn compression_ratio(bytes_in: u64, bytes_out: u64) -> String {
    if bytes_in == 0 {
        return "n/a".to_string();
    }
    let input = bytes_in as f64;
    let output = bytes_out as f64;
    if bytes_out < bytes_in {
        format!("{:.1}% smaller", (1.0 - output / input) * 100.0)
    } else if bytes_out > bytes_in {
        format!("{:.1}% larger", (output / input - 1.0) * 100.0)
    } else {
        "0.0% change".to_string()
    }
}
fn build_cue_sheet(source: &PreparedSource, artifacts: &ArtifactSet) -> String {
    let mut cue = String::new();
    if let Some(ref album) = source.album_metadata.album {
        cue.push_str(&format!("TITLE \"{}\"\n", album));
    }
    if let Some(ref artist) = source.album_metadata.album_artist {
        cue.push_str(&format!("PERFORMER \"{}\"\n", artist));
    }
    match &artifacts.audio {
        AudioArtifacts::Tracks(tracks) => {
            for (i, t) in tracks.iter().enumerate() {
                let filename = t
                    .staged_path
                    .file_name()
                    .and_then(|f| f.to_str())
                    .unwrap_or("unknown");
                cue.push_str(&format!("FILE \"{}\" WAVE\n", filename));
                cue.push_str(&format!("  TRACK {:02} AUDIO\n", i + 1));
                if let Some(st) = source.tracks.iter().find(|s| s.id == t.track_id) {
                    if let Some(ref title) = st.metadata.title {
                        cue.push_str(&format!("    TITLE \"{}\"\n", title));
                    }
                    if let Some(ref artist) = st.metadata.artist {
                        cue.push_str(&format!("    PERFORMER \"{}\"\n", artist));
                    }
                }
                cue.push_str("    INDEX 01 00:00:00\n");
            }
        }
        AudioArtifacts::Merged(merged) => {
            let filename = merged
                .staged_path
                .file_name()
                .and_then(|f| f.to_str())
                .unwrap_or("merged");
            cue.push_str(&format!("FILE \"{}\" WAVE\n", filename));
            for (i, st) in source.tracks.iter().enumerate() {
                cue.push_str(&format!("  TRACK {:02} AUDIO\n", i + 1));
                if let Some(ref title) = st.metadata.title {
                    cue.push_str(&format!("    TITLE \"{}\"\n", title));
                }
                if let Some(ref artist) = st.metadata.artist {
                    cue.push_str(&format!("    PERFORMER \"{}\"\n", artist));
                }
                cue.push_str("    INDEX 01 00:00:00\n");
            }
        }
    }
    cue
}

// ===========================================================================
// Publish  (PR 4 bodies)
// ===========================================================================

/// Build the staged-to-final publish plan from staged artifacts.
///
/// Production publish callers must pass the authoritative album directory from
/// `AlbumPlan::album_dir` or an equivalent planner/dispatcher-authored value.
/// This function deliberately has no heuristic fallback: a missing or invalid
/// album root is a publish-planning error, not something publish should guess.
pub fn build_publish_plan(
    artifacts: &ArtifactSet,
    req: &PipelineRequest,
    album_dir: &Path,
) -> Result<PublishPlan, PublishError> {
    build_publish_plan_with_album_dir(artifacts, req, album_dir)
}

/// Build a publish plan for terminal/pre-materialization conversion-log
/// fragment publishes, where a full `AlbumPlan` may not exist because the job
/// failed before ordinary output planning completed. This is the only path that
/// may derive an album directory from staged fragment sidecars. Ordinary
/// production publish must use `build_publish_plan` and pass the planned root.
fn build_publish_plan_for_fragment_or_fallback(
    artifacts: &ArtifactSet,
    req: &PipelineRequest,
) -> Result<PublishPlan, PublishError> {
    let output_root = normalize_path(&req.output_root);
    let album_dir = match fragment_dispatcher_album_dir_candidate(artifacts, req, &output_root)? {
        Some(album_dir) => album_dir,
        None => infer_publish_album_dir(artifacts, &output_root, req.naming.per_album_subdir)?,
    };
    build_publish_plan_with_album_dir(artifacts, req, &album_dir)
}

fn build_publish_plan_with_album_dir(
    artifacts: &ArtifactSet,
    req: &PipelineRequest,
    album_dir: &Path,
) -> Result<PublishPlan, PublishError> {
    let output_root = normalize_path(&req.output_root);
    // This is the per-job audio payload count, not the album completion
    // threshold. Zero is meaningful for terminal failed-track publishes that
    // carry only a forensic conversion-log fragment. Fragment-backed completion
    // uses expected_album_track_count, which is read from the fragment's
    // dispatcher-authored AlbumBatchContext.
    let source_audio_track_count = match &artifacts.audio {
        AudioArtifacts::Tracks(tracks) => tracks.len(),
        AudioArtifacts::Merged(merged) => merged.source_tracks.len(),
    };
    let expected_album_track_count = artifact_set_conversion_log_fragment_expected_track_count(artifacts)?
        .unwrap_or(source_audio_track_count);
    let mut entries = Vec::new();
    let mut seen = BTreeSet::new();

    match &artifacts.audio {
        AudioArtifacts::Tracks(tracks) => {
            for artifact in tracks {
                push_publish_entry(
                    &mut entries,
                    &mut seen,
                    &output_root,
                    artifact.staged_path.clone(),
                    artifact.final_path.clone(),
                    PublishRole::Audio,
                )?;
            }
        }
        AudioArtifacts::Merged(merged) => {
            push_publish_entry(
                &mut entries,
                &mut seen,
                &output_root,
                merged.staged_path.clone(),
                merged.final_path.clone(),
                PublishRole::Audio,
            )?;
        }
    }

    for sidecar in &artifacts.sidecars {
        push_publish_entry(
            &mut entries,
            &mut seen,
            &output_root,
            sidecar.staged_path.clone(),
            sidecar.final_path.clone(),
            PublishRole::Sidecar(sidecar.kind.clone()),
        )?;
    }

    if entries.is_empty() {
        return Err(PublishError::StagingMissing);
    }
    let album_dir = validate_publish_album_dir(
        album_dir,
        &output_root,
        &entries,
        req.naming.per_album_subdir,
    )?;

    Ok(PublishPlan {
        album_dir,
        entries,
        source_audio_track_count,
        expected_album_track_count,
        suppress_incremental_conversion_log_append: req.suppress_incremental_conversion_log_append,
        write_conversion_log: req.log.write_conversion_log,
    })
}

/// Publish a whole album atomically by filling a temp directory beside the
/// final album directory, then renaming it into place.

fn planned_album_dirs(plan: &AlbumPlan) -> Vec<PathBuf> {
    if plan.album_dirs.is_empty() {
        vec![plan.album_dir.clone()]
    } else {
        plan.album_dirs.clone()
    }
}

fn publish_album_output_for_plan(
    mut staging: StagingDir,
    artifacts: &ArtifactSet,
    req: &PipelineRequest,
    plan: &AlbumPlan,
    policy: PublishPolicy,
    manifest: Option<&super::manifest::ConversionManifest>,
) -> Result<PublishedAlbum, PublishError> {
    let album_dirs = planned_album_dirs(plan);
    if album_dirs.len() <= 1 {
        let album_dir = album_dirs
            .first()
            .map(PathBuf::as_path)
            .unwrap_or(plan.album_dir.as_path());
        let publish_plan = build_publish_plan(artifacts, req, album_dir)?;
        return publish_album_output(staging, &publish_plan, policy, manifest);
    }

    // Multi-root plans are produced when the user deliberately places
    // track-scoped disc variables in the folder template, for example
    // `%ALBUM% (CD%DISCNUMBER%)`. Treat the roots as one publish transaction:
    // prepare and validate every rendered root first, then expose roots under a
    // durable umbrella rollback marker. A crash or cancellation between roots is
    // repaired before any later publish validates destinations, so retries do not
    // fail on partial output produced by an earlier attempt.
    if !staging.is_scratch_staging() {
        staging.disarm();
    }

    let output_root = normalize_path(&req.output_root);
    fs::create_dir_all(&output_root).map_err(PublishError::io_at("creating output root for multi-root publish", &output_root))?;
    let multi_lock_path = output_root.join(".tonepoet-multi-root-publish.lock");
    let _multi_root_lock = acquire_blocking_file_lock(&multi_lock_path, true).map_err(PublishError::Io)?;
    repair_interrupted_multi_root_publishes(&output_root)?;

    let coordination_fragment_entries = coordination_fragment_entries_from_artifacts(artifacts, req)?;
    let coordination_fragment_identity =
        conversion_log_fragment_batch_identity_from_entries(&coordination_fragment_entries)?;
    let coordination_expected_track_count = if coordination_fragment_entries.is_empty() {
        0
    } else {
        artifact_set_conversion_log_fragment_expected_track_count(artifacts)?
            .unwrap_or_else(|| match &artifacts.audio {
                AudioArtifacts::Tracks(tracks) => tracks.len(),
                AudioArtifacts::Merged(merged) => merged.source_tracks.len(),
            })
    };

    let staging_parent = staging
        .root
        .parent()
        .map(Path::to_path_buf)
        .unwrap_or_else(|| staging.root.clone());
    let staging_job_name = sanitize_component(&staging.job_id);

    let mut groups = Vec::with_capacity(album_dirs.len());
    for (index, album_dir) in album_dirs.iter().enumerate() {
        let group_root = unique_path(
            &staging_parent,
            &format!(".{staging_job_name}-multi-publish-{index:03}"),
        );
        let group_artifacts = match artifact_set_for_album_dir_with_staging_copies(
            artifacts,
            album_dir,
            &group_root,
        ) {
            Ok(group_artifacts) => group_artifacts,
            Err(err) => {
                let _ = fs::remove_dir_all(&group_root);
                cleanup_multi_root_group_roots(&groups);
                return Err(err);
            }
        };
        if artifact_set_is_empty(&group_artifacts) {
            let _ = fs::remove_dir_all(&group_root);
            cleanup_multi_root_group_roots(&groups);
            return Err(PublishError::PathOutsideOutputRoot(format!(
                "planned album directory {} has no staged entries",
                album_dir.display()
            )));
        }
        let publish_plan = match build_publish_plan(&group_artifacts, req, album_dir) {
            Ok(publish_plan) => publish_plan,
            Err(err) => {
                let _ = fs::remove_dir_all(&group_root);
                cleanup_multi_root_group_roots(&groups);
                return Err(err);
            }
        };
        groups.push(MultiRootPublishGroup {
            index,
            group_root,
            publish_plan,
        });
    }

    let mut published_entries = Vec::new();

    let mut coordination_batch_workspace_guard = coordination_fragment_identity.as_ref().map(|identity| {
        activate_conversion_log_batch_publish_attempt_for_identity_best_effort(identity, "multi-root publish")
    });
    if let Some(identity) = coordination_fragment_identity.as_ref() {
        sweep_stale_completed_conversion_log_batch_coordination_for_identity_best_effort(
            identity,
            "multi-root publish preflight",
        );
    }

    if matches!(policy.overwrite, OverwritePolicy::FailIfExists) {
        match existing_multi_root_payload_matches_destinations(&groups)? {
            Some(mut existing_entries) => {
                published_entries.append(&mut existing_entries);
                if !coordination_fragment_entries.is_empty() {
                    publish_coordination_fragment_entries(
                        &coordination_fragment_entries,
                        &mut published_entries,
                    )?;
                    finalize_conversion_log_batch_coordination_if_complete(
                        coordination_expected_track_count,
                        req.log.write_conversion_log,
                        coordination_fragment_identity.as_ref(),
                        &mut published_entries,
                    )?;
                }
                if let Some(guard) = coordination_batch_workspace_guard.as_mut() {
                    guard.disarm_failure_mark();
                }
                cleanup_multi_root_group_roots(&groups);
                cleanup_successful_staging(staging);
                return Ok(PublishedAlbum {
                    album_dir: plan.album_dir.clone(),
                    entries: published_entries,
                    manifest_path: None,
                });
            }
            None => {}
        }
    }

    if let Err(err) = preflight_multi_root_destinations(&groups, policy.overwrite) {
        cleanup_multi_root_group_roots(&groups);
        return Err(err);
    }

    let marker_path = multi_root_publish_marker_path(&output_root, &req.job_id, &req.item_id);
    let mut txn = match MultiRootPublishTransaction::begin(&output_root, marker_path) {
        Ok(txn) => txn,
        Err(err) => {
            cleanup_multi_root_group_roots(&groups);
            return Err(err);
        }
    };
    let leaf_policy = PublishPolicy {
        overwrite: OverwritePolicy::FailIfExists,
        same_filesystem_required: policy.same_filesystem_required,
        write_manifest: policy.write_manifest,
    };

    let mut manifest_path = None;
    let publish_result = (|| -> Result<(), PublishError> {
        for group in &groups {
            txn.prepare_root(&group.publish_plan.album_dir, policy.overwrite)?;
            let group_staging = StagingDir::new(
                group.group_root.clone(),
                format!("{}-multi-publish-{:03}", staging.job_id, group.index),
            );
            let published = publish_album_output(
                group_staging,
                &group.publish_plan,
                leaf_policy.clone(),
                if manifest_path.is_none() { manifest } else { None },
            )?;
            if manifest_path.is_none() {
                manifest_path = published.manifest_path.clone();
            }
            published_entries.extend(published.entries);

            #[cfg(test)]
            if let Some(error) = injected_multi_root_publish_error_after_root_for_test(&group.publish_plan.album_dir, group.index) {
                return Err(PublishError::AtomicRename(error));
            }
        }

        if !coordination_fragment_entries.is_empty() {
            publish_coordination_fragment_entries(
                &coordination_fragment_entries,
                &mut published_entries,
            )?;
        }
        Ok(())
    })();

    if let Err(err) = publish_result {
        let rollback_result = txn.rollback_best_effort();
        cleanup_multi_root_group_roots(&groups);
        if let Err(rollback_err) = rollback_result {
            return Err(PublishError::RollbackFailed(format!(
                "multi-root publish failed with {err:?}; rollback failed with {rollback_err:?}; recovery marker left at {}",
                txn.marker_path.display()
            )));
        }
        return Err(err);
    }

    txn.commit()?;
    #[cfg(test)]
    if let Some(error) = injected_multi_root_publish_error_after_coordination_fragments_for_test(&plan.album_dir) {
        if let Some(identity) = coordination_fragment_identity.as_ref() {
            mark_conversion_log_batch_workspace_failed_for_identity_best_effort(
                identity,
                "multi-root publish failure after coordination fragments",
            );
        }
        return Err(PublishError::Io(io::Error::new(io::ErrorKind::Other, error)));
    }
    if !coordination_fragment_entries.is_empty() {
        finalize_conversion_log_batch_coordination_if_complete(
            coordination_expected_track_count,
            req.log.write_conversion_log,
            coordination_fragment_identity.as_ref(),
            &mut published_entries,
        )?;
    }
    if let Some(guard) = coordination_batch_workspace_guard.as_mut() {
        guard.disarm_failure_mark();
    }
    cleanup_successful_staging(staging);
    Ok(PublishedAlbum {
        album_dir: plan.album_dir.clone(),
        entries: published_entries,
        manifest_path,
    })
}

#[derive(Debug)]
struct MultiRootPublishGroup {
    index: usize,
    group_root: PathBuf,
    publish_plan: PublishPlan,
}

fn cleanup_multi_root_group_roots(groups: &[MultiRootPublishGroup]) {
    for group in groups {
        let _ = fs::remove_dir_all(&group.group_root);
    }
}

#[derive(Debug, serde::Deserialize, serde::Serialize)]
struct MultiRootPublishRecoveryMarker {
    version: u8,
    output_root_name: String,
    actions: Vec<MultiRootRecoveryActionMarker>,
}

#[derive(Debug, Clone, serde::Deserialize, serde::Serialize)]
#[serde(tag = "action", rename_all = "snake_case")]
enum MultiRootRecoveryActionMarker {
    RemoveCreatedRoot { root_rel: PathBuf },
    RestoreReplacedRoot { root_rel: PathBuf, backup_rel: PathBuf },
}

#[derive(Debug)]
enum MultiRootRollbackAction {
    RemoveCreatedRoot(PathBuf),
    RestoreReplacedRoot { root: PathBuf, backup: PathBuf },
}

#[derive(Debug)]
struct MultiRootPublishTransaction {
    output_root: PathBuf,
    marker_path: PathBuf,
    actions: Vec<MultiRootRollbackAction>,
    durable_actions: Vec<MultiRootRecoveryActionMarker>,
    committed: bool,
}

impl MultiRootPublishTransaction {
    fn begin(output_root: &Path, marker_path: PathBuf) -> Result<Self, PublishError> {
        let txn = Self {
            output_root: output_root.to_path_buf(),
            marker_path,
            actions: Vec::new(),
            durable_actions: Vec::new(),
            committed: false,
        };
        txn.persist_marker()?;
        Ok(txn)
    }

    fn prepare_root(
        &mut self,
        root: &Path,
        overwrite: OverwritePolicy,
    ) -> Result<(), PublishError> {
        if !path_is_under_root(root, &self.output_root) {
            return Err(PublishError::PathOutsideOutputRoot(root.display().to_string()));
        }

        if root.exists() {
            match overwrite {
                OverwritePolicy::FailIfExists => {
                    return Err(PublishError::DestinationExists(root.display().to_string()));
                }
                OverwritePolicy::ReplaceWithBackup
                | OverwritePolicy::AlwaysRedo
                | OverwritePolicy::SkipIfManifestMatch
                | OverwritePolicy::VerifyIfManifestMatch => {
                    let backup = unique_path(
                        &self.output_root,
                        &format!(".{}.multi-root-backup", album_dir_marker_name(root)?),
                    );
                    self.record_restore(root, &backup)?;
                    fs::rename(root, &backup).map_err(|err| {
                        PublishError::BackupFailed(format!(
                            "{} -> {}: {err}",
                            root.display(),
                            backup.display()
                        ))
                    })?;
                    sync_parent_dir_best_effort(root);
                    sync_parent_dir_best_effort(&backup);
                }
            }
        } else {
            self.record_created(root)?;
        }
        Ok(())
    }

    fn record_created(&mut self, root: &Path) -> Result<(), PublishError> {
        let root_rel = checked_relative_path(&self.output_root, root)?;
        self.actions
            .push(MultiRootRollbackAction::RemoveCreatedRoot(root.to_path_buf()));
        self.durable_actions
            .push(MultiRootRecoveryActionMarker::RemoveCreatedRoot { root_rel });
        if let Err(err) = self.persist_marker() {
            self.actions.pop();
            self.durable_actions.pop();
            return Err(err);
        }
        Ok(())
    }

    fn record_restore(&mut self, root: &Path, backup: &Path) -> Result<(), PublishError> {
        let root_rel = checked_relative_path(&self.output_root, root)?;
        let backup_rel = checked_relative_path(&self.output_root, backup)?;
        self.actions.push(MultiRootRollbackAction::RestoreReplacedRoot {
            root: root.to_path_buf(),
            backup: backup.to_path_buf(),
        });
        self.durable_actions
            .push(MultiRootRecoveryActionMarker::RestoreReplacedRoot { root_rel, backup_rel });
        if let Err(err) = self.persist_marker() {
            self.actions.pop();
            self.durable_actions.pop();
            return Err(err);
        }
        Ok(())
    }

    fn commit(&mut self) -> Result<(), PublishError> {
        remove_file_if_exists(&self.marker_path).map_err(|err| {
            PublishError::RollbackFailed(format!(
                "could not remove multi-root publish recovery marker {} after successful publish: {err}",
                self.marker_path.display()
            ))
        })?;
        sync_parent_dir_best_effort(&self.marker_path);
        self.committed = true;
        self.actions.clear();
        self.durable_actions.clear();
        Ok(())
    }

    fn rollback_best_effort(&mut self) -> Result<(), PublishError> {
        if self.committed {
            return Ok(());
        }
        let mut failures = Vec::new();
        for action in self.actions.iter().rev() {
            if let Err(err) = apply_multi_root_rollback_action(action) {
                failures.push(err);
            }
        }
        if failures.is_empty() {
            if let Err(err) = remove_file_if_exists(&self.marker_path) {
                failures.push(format!(
                    "remove recovery marker {}: {err}",
                    self.marker_path.display()
                ));
            } else {
                sync_parent_dir_best_effort(&self.marker_path);
            }
        }
        if failures.is_empty() {
            self.actions.clear();
            self.durable_actions.clear();
            Ok(())
        } else {
            Err(PublishError::RollbackFailed(failures.join("; ")))
        }
    }

    fn persist_marker(&self) -> Result<(), PublishError> {
        let marker = MultiRootPublishRecoveryMarker {
            version: 1,
            output_root_name: output_root_marker_name(&self.output_root)?,
            actions: self.durable_actions.clone(),
        };
        let bytes = serde_json::to_vec_pretty(&marker).map_err(|err| {
            PublishError::RollbackFailed(format!(
                "could not serialize multi-root publish recovery marker {}: {err}",
                self.marker_path.display()
            ))
        })?;
        write_bytes_atomically(&self.marker_path, &bytes).map_err(|err| {
            PublishError::RollbackFailed(format!(
                "could not install multi-root publish recovery marker {}: {err}",
                self.marker_path.display()
            ))
        })
    }
}

fn existing_multi_root_payload_matches_destinations(
    groups: &[MultiRootPublishGroup],
) -> Result<Option<Vec<PublishedEntry>>, PublishError> {
    let mut published_entries = Vec::new();
    let mut saw_payload = false;
    for group in groups {
        let Some(mut group_entries) = existing_publish_plan_payload_matches_destinations(&group.publish_plan)? else {
            return Ok(None);
        };
        saw_payload = true;
        published_entries.append(&mut group_entries);
    }
    Ok(saw_payload.then_some(published_entries))
}

fn existing_publish_plan_payload_matches_destinations(
    plan: &PublishPlan,
) -> Result<Option<Vec<PublishedEntry>>, PublishError> {
    if !plan.album_dir.is_dir() {
        return Ok(None);
    }
    let mut published_entries = Vec::new();
    let mut saw_payload = false;
    for entry in &plan.entries {
        if is_out_of_album_conversion_log_fragment_entry(entry, &plan.album_dir) {
            continue;
        }
        let Some(bytes) = staged_file_matches_existing_final(&entry.staged_path, &entry.final_path)? else {
            return Ok(None);
        };
        saw_payload = true;
        published_entries.push(PublishedEntry {
            final_path: entry.final_path.clone(),
            role: entry.role.clone(),
            bytes,
        });
    }
    Ok(saw_payload.then_some(published_entries))
}

fn preflight_multi_root_destinations(
    groups: &[MultiRootPublishGroup],
    overwrite: OverwritePolicy,
) -> Result<(), PublishError> {
    let mut roots = BTreeSet::new();
    for group in groups {
        let root = normalize_path(&group.publish_plan.album_dir);
        if !roots.insert(root.clone()) {
            return Err(PublishError::DestinationExists(root.display().to_string()));
        }
        if root.exists() && matches!(overwrite, OverwritePolicy::FailIfExists) {
            return Err(PublishError::DestinationExists(root.display().to_string()));
        }
    }
    Ok(())
}

fn multi_root_publish_marker_path(output_root: &Path, job_id: &str, item_id: &str) -> PathBuf {
    output_root.join(format!(
        ".tonepoet-multi-root-publish.{}.{}.json",
        sanitize_component(job_id),
        sanitize_component(item_id)
    ))
}

fn is_multi_root_publish_marker_name(name: &str) -> bool {
    name.starts_with(".tonepoet-multi-root-publish.") && name.ends_with(".json")
}

fn output_root_marker_name(output_root: &Path) -> Result<String, PublishError> {
    output_root
        .file_name()
        .and_then(|name| name.to_str())
        .map(sanitize_component)
        .or_else(|| Some("output-root".to_string()))
        .ok_or_else(|| {
            PublishError::RollbackFailed(format!(
                "output root has no valid marker name: {}",
                output_root.display()
            ))
        })
}

fn repair_interrupted_multi_root_publishes(output_root: &Path) -> Result<(), PublishError> {
    let entries = match fs::read_dir(output_root) {
        Ok(entries) => entries,
        Err(err) if err.kind() == io::ErrorKind::NotFound => return Ok(()),
        Err(err) => return Err(PublishError::Io(err)),
    };
    for entry in entries {
        let entry = entry.map_err(PublishError::io_at("listing output root for multi-root recovery", output_root))?;
        let name = entry.file_name();
        let Some(name) = name.to_str() else {
            continue;
        };
        if is_multi_root_publish_marker_name(name) {
            repair_interrupted_multi_root_publish(output_root, &entry.path())?;
        }
    }
    Ok(())
}

fn repair_interrupted_multi_root_publish(
    output_root: &Path,
    marker_path: &Path,
) -> Result<(), PublishError> {
    let marker_text = fs::read_to_string(marker_path)
        .map_err(PublishError::io_at("reading multi-root recovery marker", marker_path))?;
    let marker = serde_json::from_str::<MultiRootPublishRecoveryMarker>(&marker_text).map_err(|err| {
        PublishError::RollbackFailed(format!(
            "could not parse multi-root publish recovery marker {}: {err}",
            marker_path.display()
        ))
    })?;
    if marker.version != 1 {
        return Err(PublishError::RollbackFailed(format!(
            "unsupported multi-root publish recovery marker version {} in {}",
            marker.version,
            marker_path.display()
        )));
    }
    let expected = output_root_marker_name(output_root)?;
    if marker.output_root_name != expected {
        return Err(PublishError::RollbackFailed(format!(
            "multi-root publish recovery marker {} targets output root {}, not {}",
            marker_path.display(),
            marker.output_root_name,
            expected
        )));
    }

    let mut failures = Vec::new();
    for action in marker.actions.iter().rev() {
        let action = match durable_multi_root_action_to_runtime(output_root, marker_path, action) {
            Ok(action) => action,
            Err(err) => {
                failures.push(format!("{err:?}"));
                continue;
            }
        };
        if let Err(err) = apply_multi_root_rollback_action(&action) {
            failures.push(err);
        }
    }
    if failures.is_empty() {
        remove_file_if_exists(marker_path)
            .map_err(PublishError::io_at("removing multi-root recovery marker", marker_path))?;
        sync_parent_dir_best_effort(marker_path);
        Ok(())
    } else {
        Err(PublishError::RollbackFailed(format!(
            "could not repair interrupted multi-root publish {}: {}",
            marker_path.display(),
            failures.join("; ")
        )))
    }
}

fn durable_multi_root_action_to_runtime(
    output_root: &Path,
    marker_path: &Path,
    action: &MultiRootRecoveryActionMarker,
) -> Result<MultiRootRollbackAction, PublishError> {
    match action {
        MultiRootRecoveryActionMarker::RemoveCreatedRoot { root_rel } => {
            let root_rel = marker_relative_path(marker_path, root_rel)?;
            Ok(MultiRootRollbackAction::RemoveCreatedRoot(output_root.join(root_rel)))
        }
        MultiRootRecoveryActionMarker::RestoreReplacedRoot { root_rel, backup_rel } => {
            let root_rel = marker_relative_path(marker_path, root_rel)?;
            let backup_rel = marker_relative_path(marker_path, backup_rel)?;
            Ok(MultiRootRollbackAction::RestoreReplacedRoot {
                root: output_root.join(root_rel),
                backup: output_root.join(backup_rel),
            })
        }
    }
}

fn apply_multi_root_rollback_action(action: &MultiRootRollbackAction) -> Result<(), String> {
    match action {
        MultiRootRollbackAction::RemoveCreatedRoot(root) => {
            remove_path_tree_if_exists(root)
                .map_err(|err| format!("remove partial root {}: {err}", root.display()))?;
            sync_parent_dir_best_effort(root);
            Ok(())
        }
        MultiRootRollbackAction::RestoreReplacedRoot { root, backup } => {
            if backup.exists() {
                if root.exists() {
                    remove_path_tree_if_exists(root)
                        .map_err(|err| format!("remove replacement root {}: {err}", root.display()))?;
                }
                if let Some(parent) = root.parent() {
                    fs::create_dir_all(parent).map_err(|err| {
                        format!("create restore parent {}: {err}", parent.display())
                    })?;
                }
                fs::rename(backup, root).map_err(|err| {
                    format!(
                        "restore original root {} from {}: {err}",
                        root.display(),
                        backup.display()
                    )
                })?;
                sync_parent_dir_best_effort(root);
                Ok(())
            } else if root.exists() {
                // The marker may have been persisted immediately before the
                // original root was moved to backup. If the original root still
                // exists and the backup does not, no rollback mutation happened.
                Ok(())
            } else {
                Err(format!(
                    "backup {} missing for multi-root rollback of {}",
                    backup.display(),
                    root.display()
                ))
            }
        }
    }
}

fn remove_path_tree_if_exists(path: &Path) -> io::Result<()> {
    match fs::symlink_metadata(path) {
        Ok(metadata) if metadata.is_dir() => fs::remove_dir_all(path),
        Ok(_) => fs::remove_file(path),
        Err(err) if err.kind() == io::ErrorKind::NotFound => Ok(()),
        Err(err) => Err(err),
    }
}

// Multi-root fault injection is process-global; two rules keep it safe under
// the parallel test runner (same design as the FLAC-writer test hooks):
// every armed fault is SCOPED to the arming test's fixture directory so a
// bystander test's publish can never trip it, and arming holds one shared
// serialization lock so two fault-arming tests cannot overlap.
#[cfg(test)]
static MULTI_ROOT_PUBLISH_FAULT_AFTER_ROOT: std::sync::OnceLock<Mutex<Option<(PathBuf, usize)>>> =
    std::sync::OnceLock::new();

#[cfg(test)]
static MULTI_ROOT_PUBLISH_FAULT_AFTER_COORDINATION_FRAGMENTS: std::sync::OnceLock<Mutex<Option<PathBuf>>> =
    std::sync::OnceLock::new();

#[cfg(test)]
static MULTI_ROOT_FAULT_SERIALIZATION: std::sync::OnceLock<Mutex<()>> = std::sync::OnceLock::new();

#[cfg(test)]
fn acquire_multi_root_fault_serialization() -> std::sync::MutexGuard<'static, ()> {
    match MULTI_ROOT_FAULT_SERIALIZATION.get_or_init(|| Mutex::new(())).lock() {
        Ok(guard) => guard,
        Err(poisoned) => poisoned.into_inner(),
    }
}

#[cfg(test)]
fn injected_multi_root_publish_error_after_root_for_test(scope_probe: &Path, index: usize) -> Option<String> {
    let lock = MULTI_ROOT_PUBLISH_FAULT_AFTER_ROOT.get_or_init(|| Mutex::new(None));
    let guard = lock.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
    match guard.as_ref() {
        Some((scope, fail_index)) if *fail_index == index && scope_probe.starts_with(scope) => {
            Some(format!(
                "injected multi-root publish failure after committed root index {index}"
            ))
        }
        _ => None,
    }
}

#[cfg(test)]
struct MultiRootPublishFaultGuard {
    _serial: std::sync::MutexGuard<'static, ()>,
}

#[cfg(test)]
impl Drop for MultiRootPublishFaultGuard {
    fn drop(&mut self) {
        let lock = MULTI_ROOT_PUBLISH_FAULT_AFTER_ROOT.get_or_init(|| Mutex::new(None));
        let mut guard = lock.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
        *guard = None;
    }
}

#[cfg(test)]
fn set_multi_root_publish_fault_after_root_for_test(scope: &Path, index: usize) -> MultiRootPublishFaultGuard {
    let serial = acquire_multi_root_fault_serialization();
    let lock = MULTI_ROOT_PUBLISH_FAULT_AFTER_ROOT.get_or_init(|| Mutex::new(None));
    let mut guard = lock.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
    *guard = Some((scope.to_path_buf(), index));
    drop(guard);
    MultiRootPublishFaultGuard { _serial: serial }
}

#[cfg(test)]
struct MultiRootCoordinationFragmentFaultGuard {
    _serial: std::sync::MutexGuard<'static, ()>,
}

#[cfg(test)]
impl Drop for MultiRootCoordinationFragmentFaultGuard {
    fn drop(&mut self) {
        let lock = MULTI_ROOT_PUBLISH_FAULT_AFTER_COORDINATION_FRAGMENTS.get_or_init(|| Mutex::new(None));
        let mut guard = lock.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
        *guard = None;
    }
}

#[cfg(test)]
fn set_multi_root_publish_fault_after_commit_before_finalization_for_test(scope: &Path) -> MultiRootCoordinationFragmentFaultGuard {
    let serial = acquire_multi_root_fault_serialization();
    let lock = MULTI_ROOT_PUBLISH_FAULT_AFTER_COORDINATION_FRAGMENTS.get_or_init(|| Mutex::new(None));
    let mut guard = lock.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
    *guard = Some(scope.to_path_buf());
    drop(guard);
    MultiRootCoordinationFragmentFaultGuard { _serial: serial }
}

#[cfg(test)]
fn injected_multi_root_publish_error_after_coordination_fragments_for_test(scope_probe: &Path) -> Option<String> {
    let lock = MULTI_ROOT_PUBLISH_FAULT_AFTER_COORDINATION_FRAGMENTS.get_or_init(|| Mutex::new(None));
    let guard = lock.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
    guard
        .as_ref()
        .filter(|scope| scope_probe.starts_with(scope))
        .map(|_| "injected multi-root publish failure after multi-root commit before batch finalization".to_string())
}

fn artifact_set_is_empty(artifacts: &ArtifactSet) -> bool {
    let audio_empty = match &artifacts.audio {
        AudioArtifacts::Tracks(tracks) => tracks.is_empty(),
        AudioArtifacts::Merged(_) => false,
    };
    audio_empty && artifacts.sidecars.is_empty()
}

fn artifact_set_for_album_dir_with_staging_copies(
    artifacts: &ArtifactSet,
    album_dir: &Path,
    group_root: &Path,
) -> Result<ArtifactSet, PublishError> {
    let mut copy_index = 0_usize;
    let audio = match &artifacts.audio {
        AudioArtifacts::Tracks(tracks) => {
            let mut grouped = Vec::new();
            for track in tracks {
                if path_is_under_root(&track.final_path, album_dir) {
                    let mut cloned = track.clone();
                    cloned.staged_path = copy_staged_entry_for_multi_root_publish(
                        &track.staged_path,
                        group_root,
                        copy_index,
                    )?;
                    copy_index += 1;
                    grouped.push(cloned);
                }
            }
            AudioArtifacts::Tracks(grouped)
        }
        AudioArtifacts::Merged(merged) => {
            if path_is_under_root(&merged.final_path, album_dir) {
                let mut cloned = merged.clone();
                cloned.staged_path = copy_staged_entry_for_multi_root_publish(
                    &merged.staged_path,
                    group_root,
                    copy_index,
                )?;
                copy_index += 1;
                AudioArtifacts::Merged(cloned)
            } else {
                AudioArtifacts::Tracks(Vec::new())
            }
        }
    };

    let mut sidecars = Vec::new();
    for sidecar in &artifacts.sidecars {
        if path_is_under_root(&sidecar.final_path, album_dir) {
            let mut cloned = sidecar.clone();
            cloned.staged_path = copy_staged_entry_for_multi_root_publish(
                &sidecar.staged_path,
                group_root,
                copy_index,
            )?;
            copy_index += 1;
            sidecars.push(cloned);
        }
    }

    Ok(ArtifactSet { audio, sidecars })
}

fn copy_staged_entry_for_multi_root_publish(
    staged_path: &Path,
    group_root: &Path,
    index: usize,
) -> Result<PathBuf, PublishError> {
    if !staged_path.exists() {
        return Err(PublishError::StagingMissing);
    }
    let dest = group_root.join("entries").join(format!("{index:06}"));
    if let Some(parent) = dest.parent() {
        fs::create_dir_all(parent).map_err(PublishError::io_at("creating multi-root publish staging directory", parent))?;
    }
    match fs::hard_link(staged_path, &dest) {
        Ok(()) => Ok(dest),
        Err(_) => {
            fs::copy(staged_path, &dest).map_err(PublishError::io_at("copying staged entry for multi-root publish", staged_path))?;
            Ok(dest)
        }
    }
}

pub fn publish_album_output(
    mut staging: StagingDir,
    plan: &PublishPlan,
    policy: PublishPolicy,
    manifest: Option<&super::manifest::ConversionManifest>,
) -> Result<PublishedAlbum, PublishError> {
    // A failed publish preserves disk staging for diagnostics/retry: every
    // error return below drops `staging`, and an armed drop would delete the
    // staged tree. Success does not rely on the armed drop either — it removes
    // staging explicitly via cleanup_successful_staging. Scratch (tmpfs)
    // staging stays armed: leftovers there hold memory the scratch budget no
    // longer accounts for once the reservation is released.
    if !staging.is_scratch_staging() {
        staging.disarm();
    }
    if plan.entries.is_empty() {
        return Err(PublishError::StagingMissing);
    }
    if !staging.root.exists() {
        return Err(PublishError::StagingMissing);
    }

    #[cfg(test)]
    if let Some(error) = injected_publish_error_for_test(&staging, plan) {
        return Err(PublishError::Io(io::Error::new(io::ErrorKind::Other, error)));
    }

    let fragment_batch_identity = plan_conversion_log_fragment_batch_identity(plan)?;
    let mut batch_workspace_guard = fragment_batch_identity.as_ref().map(|identity| {
        activate_conversion_log_batch_publish_attempt_for_identity_best_effort(identity, "publish")
    });
    if let Some(identity) = fragment_batch_identity.as_ref() {
        sweep_stale_completed_conversion_log_batch_coordination_for_identity_best_effort(
            identity,
            "publish preflight",
        );
    }
    let coordination_fragment_entries: Vec<PublishEntry> = plan
        .entries
        .iter()
        .filter(|entry| is_out_of_album_conversion_log_fragment_entry(entry, &plan.album_dir))
        .cloned()
        .collect();

    let final_parent = parent_dir_or_current(&plan.album_dir);
    fs::create_dir_all(final_parent).map_err(PublishError::io_at("creating publish parent dir", final_parent))?;

    let album_name = plan
        .album_dir
        .file_name()
        .and_then(|s| s.to_str())
        .map(sanitize_component)
        .unwrap_or_else(|| "album".to_string());
    cleanup_stale_publish_lock_artifacts(final_parent, &album_name);
    let _publish_lock = acquire_publish_lock(&plan.album_dir)?;
    let marker_path = final_parent.join(format!(".{album_name}.publish-in-progress"));
    let incremental_marker_path = final_parent.join(format!(
        ".{album_name}.incremental-publish-in-progress"
    ));
    repair_interrupted_publish(&plan.album_dir, &marker_path)?;
    repair_interrupted_incremental_publish(&plan.album_dir, &incremental_marker_path)?;
    cleanup_orphan_publish_temps(final_parent, &album_name)?;

    let temp_dir = unique_path(final_parent, &format!(".{album_name}.tmp"));
    let backup_dir = unique_path(final_parent, &format!(".{album_name}.backup"));

    if let Err(err) = fs::create_dir_all(&temp_dir) {
        let _ = fs::remove_dir_all(&temp_dir);
        return Err(PublishError::Io(err));
    }

    let mut published_entries = Vec::with_capacity(plan.entries.len());
    let mut album_payload_entry_count = 0_usize;
    for entry in &plan.entries {
        if !entry.staged_path.exists() {
            let _ = fs::remove_dir_all(&temp_dir);
            return Err(PublishError::StagingMissing);
        }
        if is_out_of_album_conversion_log_fragment_entry(entry, &plan.album_dir) {
            // Stable batch-coordination fragments are installed only after the
            // rendered audio payload is visible. They are deliberately not placed
            // in the album temp tree, because per-disc album-folder templates make
            // that tree one rendered root, not the batch-completion namespace.
            continue;
        }
        album_payload_entry_count += 1;
        let rel = match entry.final_path.strip_prefix(&plan.album_dir) {
            Ok(rel) => rel.to_path_buf(),
            Err(_) => {
                return cleanup_publish_temp(
                    &temp_dir,
                    PublishError::PathOutsideOutputRoot(entry.final_path.display().to_string()),
                );
            }
        };
        if let Err(err) = reject_escaping_path(&rel) {
            return cleanup_publish_temp(&temp_dir, PublishError::PathOutsideOutputRoot(err));
        }
        let staged_final = temp_dir.join(rel);
        if let Some(parent) = staged_final.parent() {
            if let Err(err) = fs::create_dir_all(parent) {
                return cleanup_publish_temp(&temp_dir, PublishError::Io(err));
            }
        }
        if let Err(err) = copy_or_rename_into_publish_temp(
            &entry.staged_path,
            &staged_final,
            policy.same_filesystem_required,
        ) {
            return cleanup_publish_temp(&temp_dir, err);
        }
        let bytes = match fs::metadata(&staged_final) {
            Ok(metadata) => metadata.len(),
            Err(err) => return cleanup_publish_temp(&temp_dir, PublishError::Io(err)),
        };
        published_entries.push(PublishedEntry {
            final_path: entry.final_path.clone(),
            role: entry.role.clone(),
            bytes,
        });
    }

    if album_payload_entry_count == 0 && !coordination_fragment_entries.is_empty() {
        publish_coordination_fragment_entries(&coordination_fragment_entries, &mut published_entries)?;
        finalize_conversion_log_batch_coordination_if_complete(
            plan.expected_album_track_count,
            plan.write_conversion_log,
            fragment_batch_identity.as_ref(),
            &mut published_entries,
        )?;
        if let Some(guard) = batch_workspace_guard.as_mut() {
            guard.disarm_failure_mark();
        }
        let _ = fs::remove_dir_all(&temp_dir);
        cleanup_successful_staging(staging);
        return Ok(PublishedAlbum {
            album_dir: plan.album_dir.clone(),
            entries: published_entries,
            manifest_path: None,
        });
    }

    let mut backup_made = false;
    if plan.album_dir.exists() {
        match policy.overwrite {
            OverwritePolicy::FailIfExists => {
                if is_incremental_single_audio_publish(plan) {
                    let manifest_path = publish_incremental_album_output(
                        &temp_dir,
                        plan,
                        manifest,
                        &incremental_marker_path,
                        fragment_batch_identity.as_ref(),
                        &mut published_entries,
                    )?;
                    if let Some(guard) = batch_workspace_guard.as_mut() {
                        guard.disarm_failure_mark();
                    }
                    cleanup_successful_staging(staging);
                    return Ok(PublishedAlbum {
                        album_dir: plan.album_dir.clone(),
                        entries: published_entries,
                        manifest_path,
                    });
                }
                let _ = fs::remove_dir_all(&temp_dir);
                return Err(PublishError::DestinationExists(
                    plan.album_dir.display().to_string(),
                ));
            }
            OverwritePolicy::ReplaceWithBackup | OverwritePolicy::AlwaysRedo => {
                if let Err(err) = write_publish_marker(&marker_path, &backup_dir) {
                    let _ = fs::remove_dir_all(&temp_dir);
                    return Err(err);
                }
                fs::rename(&plan.album_dir, &backup_dir).map_err(|err| {
                    let _ = fs::remove_dir_all(&temp_dir);
                    let _ = fs::remove_file(&marker_path);
                    PublishError::BackupFailed(format!(
                        "{} -> {}: {err}",
                        plan.album_dir.display(),
                        backup_dir.display()
                    ))
                })?;
                backup_made = true;
            }
            // Manifest-based policies are handled by the orchestrator rerun gate
            // before reaching publish. If we get here, proceed with publish.
            OverwritePolicy::SkipIfManifestMatch
            | OverwritePolicy::VerifyIfManifestMatch => {
                // The rerun gate already decided to proceed (not skip).
                // Treat as replace-with-backup for the publish step.
                if let Err(err) = write_publish_marker(&marker_path, &backup_dir) {
                    let _ = fs::remove_dir_all(&temp_dir);
                    return Err(err);
                }
                fs::rename(&plan.album_dir, &backup_dir).map_err(|err| {
                    let _ = fs::remove_dir_all(&temp_dir);
                    let _ = fs::remove_file(&marker_path);
                    PublishError::BackupFailed(format!(
                        "{} -> {}: {err}",
                        plan.album_dir.display(),
                        backup_dir.display()
                    ))
                })?;
                backup_made = true;
            }
        }
    }

    let assembled_conversion_log = finalize_staged_conversion_log_for_publish(
        &temp_dir,
        &plan.album_dir,
        plan.expected_album_track_count,
        plan_has_conversion_log_fragment(plan),
        plan.write_conversion_log,
        fragment_batch_identity.as_ref(),
        &mut published_entries,
    )?;

    // Write manifest into the temp dir before atomic rename; expose the final
    // post-publish path in PublishedAlbum so PipelineReport cannot contain a
    // stale temp-directory manifest path.
    let manifest_path = if let Some(manifest) = manifest {
        match super::manifest::write_manifest_for_publish(&temp_dir, &plan.album_dir, manifest) {
            Ok(_written_manifest_path) => Some(super::manifest::manifest_path(&plan.album_dir)),
            Err(err) => {
                log::warn!("manifest write failed (non-fatal): {err}");
                None
            }
        }
    } else {
        None
    };

    if let Err(err) = fs::rename(&temp_dir, &plan.album_dir) {
        let _ = fs::remove_dir_all(&temp_dir);
        if backup_made {
            if let Err(rollback_err) = fs::rename(&backup_dir, &plan.album_dir) {
                return Err(PublishError::RollbackFailed(format!(
                    "publish failed with {err}; rollback failed with {rollback_err}; recovery marker left at {}",
                    marker_path.display()
                )));
            }
            let _ = fs::remove_file(&marker_path);
            sync_parent_dir_best_effort(&marker_path);
        }
        return Err(PublishError::AtomicRename(format!(
            "{} -> {}: {err}",
            temp_dir.display(),
            plan.album_dir.display()
        )));
    }
    if backup_made {
        let _ = fs::remove_file(&marker_path);
    }
    sync_parent_dir_best_effort(&plan.album_dir);
    if !coordination_fragment_entries.is_empty() {
        publish_coordination_fragment_entries(&coordination_fragment_entries, &mut published_entries)?;
        finalize_conversion_log_batch_coordination_if_complete(
            plan.expected_album_track_count,
            plan.write_conversion_log,
            fragment_batch_identity.as_ref(),
            &mut published_entries,
        )?;
    } else if assembled_conversion_log {
        cleanup_complete_conversion_log_fragments(
            &plan.album_dir,
            plan.expected_album_track_count,
            plan.write_conversion_log,
            fragment_batch_identity.as_ref(),
        );
    }

    if let Some(guard) = batch_workspace_guard.as_mut() {
        guard.disarm_failure_mark();
    }
    cleanup_successful_staging(staging);
    cleanup_stale_publish_lock_artifacts(final_parent, &album_name);

    Ok(PublishedAlbum {
        album_dir: plan.album_dir.clone(),
        entries: published_entries,
        manifest_path,
    })
}

fn is_incremental_single_audio_publish(plan: &PublishPlan) -> bool {
    if plan.suppress_incremental_conversion_log_append {
        return false;
    }

    let audio_entry_count = plan
        .entries
        .iter()
        .filter(|entry| matches!(&entry.role, PublishRole::Audio))
        .count();
    if audio_entry_count > 1 {
        return false;
    }

    // Incremental publish is deliberately limited to one source track per job.
    // A merged multi-track source can have only one output audio file, but it
    // is still an album-level payload and must keep the normal destination
    // directory collision protection.
    if plan.source_audio_track_count > 1 {
        return false;
    }

    let has_fragment = plan_has_conversion_log_fragment(plan);
    let has_standalone_conversion_log = plan.entries.iter().any(|entry| {
        matches!(
            &entry.role,
            PublishRole::Sidecar(SidecarKind::ConversionLog)
        )
    });

    // Successful independent track jobs may publish one audio payload plus
    // either the legacy standalone conversion.log append or the newer hidden
    // ordered fragment. Failed independent track jobs may publish only the
    // hidden fragment. All of those cases must append into an existing album
    // directory instead of treating the directory itself as a collision.
    has_fragment || (audio_entry_count == 1 && has_standalone_conversion_log)
}

fn publish_incremental_album_output(
    temp_dir: &Path,
    plan: &PublishPlan,
    manifest: Option<&super::manifest::ConversionManifest>,
    marker_path: &Path,
    fragment_batch_identity: Option<&ConversionLogBatchIdentity>,
    published_entries: &mut Vec<PublishedEntry>,
) -> Result<Option<PathBuf>, PublishError> {
    let mut incremental_entries = Vec::with_capacity(plan.entries.len());
    let coordination_fragment_entries: Vec<PublishEntry> = plan
        .entries
        .iter()
        .filter(|entry| is_out_of_album_conversion_log_fragment_entry(entry, &plan.album_dir))
        .cloned()
        .collect();
    let mut already_published_audio_entries = Vec::new();
    let mut repaired_existing_audio_payload = false;
    let mut has_audio = false;
    let mut has_conversion_log_fragment = !coordination_fragment_entries.is_empty();

    for entry in &plan.entries {
        if is_out_of_album_conversion_log_fragment_entry(entry, &plan.album_dir) {
            continue;
        }
        let rel = match entry.final_path.strip_prefix(&plan.album_dir) {
            Ok(rel) => rel.to_path_buf(),
            Err(_) => {
                return cleanup_publish_temp(
                    temp_dir,
                    PublishError::PathOutsideOutputRoot(entry.final_path.display().to_string()),
                );
            }
        };
        if let Err(err) = reject_escaping_path(&rel) {
            return cleanup_publish_temp(temp_dir, PublishError::PathOutsideOutputRoot(err));
        }

        let temp_entry_path = temp_dir.join(&rel);
        if !temp_entry_path.exists() {
            return cleanup_publish_temp(temp_dir, PublishError::StagingMissing);
        }

        match &entry.role {
            PublishRole::Audio => {
                has_audio = true;
                if entry.final_path.exists() {
                    if !coordination_fragment_entries.is_empty() {
                        if let Some(bytes) = staged_file_matches_existing_final(&temp_entry_path, &entry.final_path)? {
                            repaired_existing_audio_payload = true;
                            already_published_audio_entries.push(PublishedEntry {
                                final_path: entry.final_path.clone(),
                                role: PublishRole::Audio,
                                bytes,
                            });
                            continue;
                        }
                    }
                    return cleanup_publish_temp(
                        temp_dir,
                        PublishError::DestinationExists(entry.final_path.display().to_string()),
                    );
                }
            }
            PublishRole::Sidecar(_) => {
                if is_conversion_log_fragment_role(&entry.role) {
                    has_conversion_log_fragment = true;
                }
                if entry.final_path.is_dir() {
                    return cleanup_publish_temp(
                        temp_dir,
                        PublishError::DestinationExists(entry.final_path.display().to_string()),
                    );
                }
            }
        }

        incremental_entries.push(IncrementalPublishEntry {
            temp_path: temp_entry_path,
            final_path: entry.final_path.clone(),
            role: entry.role.clone(),
        });
    }

    if !has_audio && !has_conversion_log_fragment {
        return cleanup_publish_temp(temp_dir, PublishError::StagingMissing);
    }

    let mut rollback = match IncrementalPublishRollback::new(marker_path, &plan.album_dir, temp_dir) {
        Ok(rollback) => rollback,
        Err(err) => return cleanup_publish_temp(temp_dir, err),
    };
    let mut assembled_conversion_log = false;
    let publish_result = (|| -> Result<(), PublishError> {
        // Publish the track audio before the hidden conversion-log fragment can
        // trigger final album log assembly. This prevents a visible forensic
        // conversion.log from claiming completion while the final successful
        // track's audio file is not yet installed. Failed-track publishes have
        // no audio payload, so they naturally skip this phase and publish their
        // failure fragment below. The durable recovery marker is updated before
        // every destination mutation across all phases.
        for entry in incremental_entries.iter().filter(|entry| {
            incremental_publish_phase(&entry.role) == IncrementalPublishPhase::AudioPayload
        }) {
            publish_incremental_audio_entry(
                &entry.temp_path,
                &entry.final_path,
                &mut rollback,
            )?;
        }

        for entry in incremental_entries.iter().filter(|entry| {
            incremental_publish_phase(&entry.role) == IncrementalPublishPhase::NonFragmentSidecar
        }) {
            match &entry.role {
                PublishRole::Sidecar(SidecarKind::ConversionLog) if has_conversion_log_fragment => {
                    // Fragment-backed publishes no longer use a staged one-track
                    // conversion.log as an assembly trigger. If an older caller
                    // still staged one, discard it and let the fragment-count
                    // path below decide whether the unified log is ready.
                    remove_file_if_exists(&entry.temp_path).map_err(PublishError::io_at("removing incremental temp entry", &entry.temp_path))?;
                }
                PublishRole::Sidecar(SidecarKind::ConversionLog) => {
                    publish_incremental_conversion_log(
                        &entry.temp_path,
                        &entry.final_path,
                        &mut rollback,
                    )?;
                }
                PublishRole::Sidecar(_) => {
                    replace_incremental_sidecar_entry(
                        &entry.temp_path,
                        &entry.final_path,
                        &mut rollback,
                    )?;
                }
                PublishRole::Audio => unreachable!("audio entries are filtered out above"),
            }
        }

        for entry in incremental_entries.iter().filter(|entry| {
            incremental_publish_phase(&entry.role) == IncrementalPublishPhase::ConversionLogFragment
        }) {
            replace_incremental_sidecar_entry(
                &entry.temp_path,
                &entry.final_path,
                &mut rollback,
            )?;
        }

        if coordination_fragment_entries.is_empty() && has_conversion_log_fragment {
            // The hidden fragment, not a staged one-track conversion.log, is the
            // trigger for the last-track check. This runs under the album publish
            // lock after the current job's audio payload and sidecars have been
            // published, so incomplete batches do no visible log work and
            // complete batches assemble only after the last successful track's
            // audio file is visible. Failed-track fragments, which have no audio
            // payload, also assemble only after their fragment is published.
            assembled_conversion_log |= publish_incremental_assembled_conversion_log_from_fragments(
                &plan.album_dir,
                plan.expected_album_track_count,
                plan.write_conversion_log,
                fragment_batch_identity,
                &mut rollback,
            )?;
        }

        Ok(())
    })();

    if let Err(err) = publish_result {
        if let Err(rollback_err) = rollback.rollback_best_effort() {
            let _ = fs::remove_dir_all(temp_dir);
            return Err(PublishError::RollbackFailed(format!(
                "incremental publish failed with {err:?}; rollback failed with {rollback_err:?}; recovery marker left at {}",
                marker_path.display()
            )));
        }
        return cleanup_publish_temp(temp_dir, err);
    }

    if let Err(err) = rollback.commit() {
        if let Err(rollback_err) = rollback.rollback_best_effort() {
            let _ = fs::remove_dir_all(temp_dir);
            return Err(PublishError::RollbackFailed(format!(
                "incremental publish completed but recovery marker cleanup failed with {err:?}; rollback failed with {rollback_err:?}; recovery marker left at {}",
                marker_path.display()
            )));
        }
        return cleanup_publish_temp(temp_dir, err);
    }
    if let Err(err) = fs::remove_dir_all(temp_dir) {
        log::warn!(
            "incremental publish temp cleanup failed after successful publish: {}: {err}",
            temp_dir.display()
        );
    }
    sync_parent_dir_best_effort(&plan.album_dir);
    if repaired_existing_audio_payload {
        published_entries.extend(already_published_audio_entries);
    }
    if !coordination_fragment_entries.is_empty() {
        publish_coordination_fragment_entries(&coordination_fragment_entries, published_entries)?;
        assembled_conversion_log |= finalize_conversion_log_batch_coordination_if_complete(
            plan.expected_album_track_count,
            plan.write_conversion_log,
            fragment_batch_identity,
            published_entries,
        )?;
    }
    if assembled_conversion_log && coordination_fragment_entries.is_empty() {
        let log_path = plan.album_dir.join("conversion.log");
        if let Ok(metadata) = fs::metadata(&log_path) {
            record_assembled_conversion_log_entry(
                published_entries,
                &log_path,
                metadata.len(),
            );
        }
        cleanup_complete_conversion_log_fragments(
            &plan.album_dir,
            plan.expected_album_track_count,
            plan.write_conversion_log,
            fragment_batch_identity,
        );
    }

    Ok(write_incremental_manifest_nonfatal(plan, manifest))
}

#[derive(Debug)]
struct IncrementalPublishEntry {
    temp_path: PathBuf,
    final_path: PathBuf,
    role: PublishRole,
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum IncrementalPublishPhase {
    AudioPayload,
    NonFragmentSidecar,
    ConversionLogFragment,
}

fn incremental_publish_phase(role: &PublishRole) -> IncrementalPublishPhase {
    if is_conversion_log_fragment_role(role) {
        return IncrementalPublishPhase::ConversionLogFragment;
    }

    match role {
        PublishRole::Audio => IncrementalPublishPhase::AudioPayload,
        PublishRole::Sidecar(_) => IncrementalPublishPhase::NonFragmentSidecar,
    }
}


#[derive(Debug, Clone, serde::Deserialize, serde::Serialize)]
struct IncrementalPublishRecoveryMarker {
    version: u8,
    album_dir_name: String,
    temp_dir_name: String,
    actions: Vec<IncrementalRecoveryActionMarker>,
}

#[derive(Debug, Clone, serde::Deserialize, serde::Serialize)]
#[serde(tag = "action", rename_all = "snake_case")]
enum IncrementalRecoveryActionMarker {
    RemoveCreatedFile { final_rel: PathBuf },
    RestoreOriginalFile { final_rel: PathBuf, backup_rel: PathBuf },
}

#[derive(Debug)]
enum IncrementalRollbackAction {
    RemoveCreatedFile(PathBuf),
    RestoreOriginalFile {
        backup_path: PathBuf,
        final_path: PathBuf,
    },
}

#[derive(Debug)]
struct IncrementalPublishRollback {
    actions: Vec<IncrementalRollbackAction>,
    durable_actions: Vec<IncrementalRecoveryActionMarker>,
    marker_path: PathBuf,
    album_dir: PathBuf,
    temp_dir: PathBuf,
    committed: bool,
}

impl IncrementalPublishRollback {
    fn new(marker_path: &Path, album_dir: &Path, temp_dir: &Path) -> Result<Self, PublishError> {
        let rollback = Self {
            actions: Vec::new(),
            durable_actions: Vec::new(),
            marker_path: marker_path.to_path_buf(),
            album_dir: album_dir.to_path_buf(),
            temp_dir: temp_dir.to_path_buf(),
            committed: false,
        };
        rollback.persist_marker()?;
        Ok(rollback)
    }

    fn commit(&mut self) -> Result<(), PublishError> {
        remove_file_if_exists(&self.marker_path).map_err(|err| {
            PublishError::RollbackFailed(format!(
                "could not remove incremental publish recovery marker {} after successful publish: {err}",
                self.marker_path.display()
            ))
        })?;
        sync_parent_dir_best_effort(&self.marker_path);
        self.committed = true;
        self.actions.clear();
        self.durable_actions.clear();
        Ok(())
    }

    fn record_created_file(&mut self, final_path: &Path) -> Result<(), PublishError> {
        let final_rel = checked_relative_path(&self.album_dir, final_path)?;
        self.actions
            .push(IncrementalRollbackAction::RemoveCreatedFile(final_path.to_path_buf()));
        self.durable_actions
            .push(IncrementalRecoveryActionMarker::RemoveCreatedFile { final_rel });
        if let Err(err) = self.persist_marker() {
            self.actions.pop();
            self.durable_actions.pop();
            return Err(err);
        }
        Ok(())
    }

    fn snapshot_destination(&mut self, final_path: &Path) -> Result<(), PublishError> {
        if final_path.exists() {
            let backup_path = unique_path(&self.temp_dir, ".incremental-rollback");
            // The exists() check above is advisory: another actor (companion
            // copying, fragment cleanup, the user) can remove the destination
            // between the check and the snapshot copy. A vanished destination
            // is the not-exists case, not a publish failure.
            match copy_incremental_backup_snapshot(final_path, &backup_path) {
                Ok(()) => {}
                Err(_) if !final_path.exists() => {
                    let _ = remove_file_if_exists(&backup_path);
                    return self.record_created_file(final_path);
                }
                Err(err) => return Err(err),
            }
            let final_rel = checked_relative_path(&self.album_dir, final_path)?;
            let backup_rel = checked_relative_path(&self.temp_dir, &backup_path)?;
            self.actions.push(IncrementalRollbackAction::RestoreOriginalFile {
                backup_path,
                final_path: final_path.to_path_buf(),
            });
            self.durable_actions
                .push(IncrementalRecoveryActionMarker::RestoreOriginalFile {
                    final_rel,
                    backup_rel,
                });
            if let Err(err) = self.persist_marker() {
                if let Some(IncrementalRollbackAction::RestoreOriginalFile { backup_path, .. }) = self.actions.pop() {
                    let _ = remove_file_if_exists(&backup_path);
                    sync_parent_dir_best_effort(&backup_path);
                }
                self.durable_actions.pop();
                return Err(err);
            }
        } else {
            self.record_created_file(final_path)?;
        }
        Ok(())
    }

    fn rollback_best_effort(&mut self) -> Result<(), PublishError> {
        if self.committed {
            return Ok(());
        }

        let mut failures = Vec::new();
        for action in self.actions.iter().rev() {
            match action {
                IncrementalRollbackAction::RemoveCreatedFile(path) => {
                    if let Err(err) = remove_file_if_exists(path) {
                        failures.push(format!("remove {}: {err}", path.display()));
                    } else {
                        sync_parent_dir_best_effort(path);
                    }
                }
                IncrementalRollbackAction::RestoreOriginalFile {
                    backup_path,
                    final_path,
                } => {
                    if let Err(err) = restore_incremental_backup(backup_path, final_path) {
                        failures.push(format!(
                            "restore {} from {}: {err}",
                            final_path.display(),
                            backup_path.display()
                        ));
                    } else {
                        sync_parent_dir_best_effort(final_path);
                    }
                }
            }
        }

        if failures.is_empty() {
            if let Err(err) = remove_file_if_exists(&self.marker_path) {
                failures.push(format!(
                    "remove recovery marker {}: {err}",
                    self.marker_path.display()
                ));
            } else {
                sync_parent_dir_best_effort(&self.marker_path);
            }
        }
        if failures.is_empty() {
            self.actions.clear();
            self.durable_actions.clear();
            Ok(())
        } else {
            Err(PublishError::RollbackFailed(failures.join("; ")))
        }
    }

    fn persist_marker(&self) -> Result<(), PublishError> {
        let temp_dir_name = self
            .temp_dir
            .file_name()
            .and_then(|name| name.to_str())
            .ok_or_else(|| {
                PublishError::RollbackFailed(format!(
                    "incremental publish temp directory has no valid file name: {}",
                    self.temp_dir.display()
                ))
            })?
            .to_string();
        let marker = IncrementalPublishRecoveryMarker {
            version: 1,
            album_dir_name: album_dir_marker_name(&self.album_dir)?,
            temp_dir_name,
            actions: self.durable_actions.clone(),
        };
        let bytes = serde_json::to_vec_pretty(&marker).map_err(|err| {
            PublishError::RollbackFailed(format!(
                "could not serialize incremental publish recovery marker {}: {err}",
                self.marker_path.display()
            ))
        })?;
        write_bytes_atomically(&self.marker_path, &bytes).map_err(|err| {
            PublishError::RollbackFailed(format!(
                "could not install incremental publish recovery marker {}: {err}",
                self.marker_path.display()
            ))
        })
    }
}

fn checked_relative_path(root: &Path, path: &Path) -> Result<PathBuf, PublishError> {
    let rel = path.strip_prefix(root).map_err(|_| {
        PublishError::PathOutsideOutputRoot(path.display().to_string())
    })?;
    reject_escaping_path(rel).map_err(PublishError::PathOutsideOutputRoot)?;
    if rel.components().next().is_none() {
        return Err(PublishError::PathOutsideOutputRoot(path.display().to_string()));
    }
    Ok(rel.to_path_buf())
}

fn marker_relative_path(marker_path: &Path, rel: &Path) -> Result<PathBuf, PublishError> {
    reject_escaping_path(rel).map_err(|err| {
        PublishError::RollbackFailed(format!(
            "incremental publish recovery marker {} contains invalid relative path {}: {err}",
            marker_path.display(),
            rel.display()
        ))
    })?;
    if rel.components().next().is_none() {
        return Err(PublishError::RollbackFailed(format!(
            "incremental publish recovery marker {} contains an empty relative path",
            marker_path.display()
        )));
    }
    Ok(rel.to_path_buf())
}

fn remove_file_if_exists(path: &Path) -> io::Result<()> {
    match fs::remove_file(path) {
        Ok(()) => Ok(()),
        Err(err) if err.kind() == io::ErrorKind::NotFound => Ok(()),
        Err(err) => Err(err),
    }
}

fn restore_incremental_backup(backup_path: &Path, final_path: &Path) -> io::Result<()> {
    if let Some(parent) = final_path.parent() {
        fs::create_dir_all(parent)?;
    }
    let restore_path = unique_path(
        parent_dir_or_current(final_path),
        ".incremental-restore",
    );
    copy_file_create_new_synced_io(backup_path, &restore_path)?;
    remove_file_if_exists(final_path)?;
    fs::rename(&restore_path, final_path).or_else(|err| {
        let _ = fs::remove_file(&restore_path);
        Err(err)
    })?;
    sync_parent_dir(final_path)
}

fn publish_incremental_audio_entry(
    src: &Path,
    dst: &Path,
    rollback: &mut IncrementalPublishRollback,
) -> Result<(), PublishError> {
    if dst.exists() {
        return Err(PublishError::DestinationExists(dst.display().to_string()));
    }
    if let Some(parent) = dst.parent() {
        fs::create_dir_all(parent).map_err(PublishError::io_at("creating destination parent dir", parent))?;
    }
    rollback.record_created_file(dst)?;

    match fs::hard_link(src, dst) {
        Ok(()) => {
            fs::remove_file(src).map_err(PublishError::io_at("removing source after copy", src))?;
            sync_parent_dir_best_effort(dst);
            Ok(())
        }
        Err(err) if err.kind() == io::ErrorKind::AlreadyExists => {
            Err(PublishError::DestinationExists(dst.display().to_string()))
        }
        Err(_) => copy_incremental_audio_create_new(src, dst),
    }
}

fn copy_incremental_audio_create_new(src: &Path, dst: &Path) -> Result<(), PublishError> {
    copy_file_create_new_synced(src, dst)?;
    fs::remove_file(src).map_err(PublishError::io_at("removing source after copy", src))?;
    Ok(())
}

fn copy_incremental_backup_snapshot(src: &Path, dst: &Path) -> Result<(), PublishError> {
    copy_file_create_new_synced_io(src, dst).map_err(|err| {
        PublishError::RollbackFailed(format!(
            "could not create durable incremental rollback snapshot {} from {}: {err}",
            dst.display(),
            src.display()
        ))
    })
}

fn copy_file_create_new_synced(src: &Path, dst: &Path) -> Result<(), PublishError> {
    copy_file_create_new_synced_io(src, dst).map_err(|err| {
        if err.kind() == io::ErrorKind::AlreadyExists {
            PublishError::DestinationExists(dst.display().to_string())
        } else {
            PublishError::Io(err)
        }
    })
}

fn copy_file_create_new_synced_io(src: &Path, dst: &Path) -> io::Result<()> {
    let mut input = fs::File::open(src)?;
    let mut output = match fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(dst)
    {
        Ok(output) => output,
        Err(err) => return Err(err),
    };

    let result = (|| -> io::Result<()> {
        io::copy(&mut input, &mut output)?;
        output.sync_all()?;
        sync_parent_dir(dst)?;
        Ok(())
    })();

    if result.is_err() {
        drop(output);
        let _ = remove_file_if_exists(dst);
        sync_parent_dir_best_effort(dst);
    }

    result
}


fn publish_incremental_conversion_log(
    src: &Path,
    dst: &Path,
    rollback: &mut IncrementalPublishRollback,
) -> Result<(), PublishError> {
    if dst.is_dir() {
        return Err(PublishError::DestinationExists(dst.display().to_string()));
    }

    // Legacy/non-fragment incremental jobs still append their staged standalone
    // logs. Fragment-backed jobs never reach this path for assembly: their
    // hidden fragment sidecar triggers count-and-maybe-assemble directly after
    // fragment publication.
    append_incremental_conversion_log(src, dst, rollback)
}

fn append_incremental_conversion_log(
    src: &Path,
    dst: &Path,
    rollback: &mut IncrementalPublishRollback,
) -> Result<(), PublishError> {
    if dst.is_dir() {
        return Err(PublishError::DestinationExists(dst.display().to_string()));
    }
    if let Some(parent) = dst.parent() {
        fs::create_dir_all(parent).map_err(PublishError::io_at("creating copy destination parent dir", parent))?;
    }
    rollback.snapshot_destination(dst)?;

    let src_len = fs::metadata(src).map_err(PublishError::io_at("reading copy source metadata", src))?.len();
    let dst_len = match fs::metadata(dst) {
        Ok(metadata) => metadata.len(),
        Err(err) if err.kind() == io::ErrorKind::NotFound => 0,
        Err(err) => return Err(PublishError::Io(err)),
    };
    let needs_separator = dst_len > 0 && src_len > 0 && !file_ends_with_newline(dst)?;

    let mut input = fs::File::open(src).map_err(PublishError::io_at("opening copy source", src))?;
    let mut output = fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(dst)
        .map_err(PublishError::io_at("creating copy destination", dst))?;
    if needs_separator {
        use std::io::Write;
        output.write_all(b"\n").map_err(PublishError::io_at("writing copy destination", dst))?;
    }
    io::copy(&mut input, &mut output).map_err(PublishError::io_at("copying file contents to", dst))?;
    output.sync_all().map_err(PublishError::io_at("syncing copy destination", dst))?;
    fs::remove_file(src).map_err(PublishError::io_at("removing source after copy", src))?;
    sync_parent_dir_best_effort(dst);
    Ok(())
}

fn file_ends_with_newline(path: &Path) -> Result<bool, PublishError> {
    use std::io::{Read, Seek, SeekFrom};

    let mut file = fs::File::open(path).map_err(PublishError::io_at("opening file for newline check", path))?;
    let len = file.metadata().map_err(PublishError::io_at("reading metadata for newline check", path))?.len();
    if len == 0 {
        return Ok(true);
    }
    file.seek(SeekFrom::End(-1)).map_err(PublishError::io_at("seeking for newline check", path))?;
    let mut byte = [0_u8; 1];
    file.read_exact(&mut byte).map_err(PublishError::io_at("reading for newline check", path))?;
    Ok(byte[0] == b'\n')
}

fn replace_incremental_sidecar_entry(
    src: &Path,
    dst: &Path,
    rollback: &mut IncrementalPublishRollback,
) -> Result<(), PublishError> {
    if dst.is_dir() {
        return Err(PublishError::DestinationExists(dst.display().to_string()));
    }
    let parent = parent_dir_or_current(dst);
    fs::create_dir_all(parent).map_err(PublishError::io_at("creating sidecar destination parent dir", parent))?;

    // Stage the replacement in the destination directory and record it in the
    // durable rollback marker before creating it. That gives recovery a concrete
    // cleanup action if the process crashes before the final install step.
    let replacement_path = unique_path(parent, ".incremental-sidecar-replace");
    rollback.record_created_file(&replacement_path)?;
    copy_file_create_new_synced(src, &replacement_path)?;

    // Snapshot the old destination after the new bytes are safely staged but
    // before the destination name is changed. On Unix, rename over an existing
    // file is atomic, so readers never observe a missing sidecar. Platforms
    // without overwrite-rename fall back to remove+rename, guarded by the same
    // durable backup/restore marker used for crash recovery.
    rollback.snapshot_destination(dst)?;
    install_incremental_sidecar_replacement(&replacement_path, dst)?;
    fs::remove_file(src).map_err(PublishError::io_at("removing staged sidecar after replace", src))?;
    Ok(())
}

fn install_incremental_sidecar_replacement(
    replacement_path: &Path,
    dst: &Path,
) -> Result<(), PublishError> {
    match fs::rename(replacement_path, dst) {
        Ok(()) => {
            sync_parent_dir_best_effort(dst);
            Ok(())
        }
        Err(err) if should_fallback_to_remove_then_rename_for_replace(&err, dst) => {
            remove_file_if_exists(dst).map_err(PublishError::io_at("removing existing sidecar destination", dst))?;
            fs::rename(replacement_path, dst).map_err(PublishError::io_at("renaming replacement sidecar into place", dst))?;
            sync_parent_dir_best_effort(dst);
            Ok(())
        }
        Err(err) => Err(PublishError::Io(err)),
    }
}

fn should_fallback_to_remove_then_rename_for_replace(err: &io::Error, dst: &Path) -> bool {
    #[cfg(windows)]
    {
        dst.exists()
            && matches!(
                err.kind(),
                io::ErrorKind::AlreadyExists | io::ErrorKind::PermissionDenied
            )
    }
    #[cfg(not(windows))]
    {
        let _ = (err, dst);
        false
    }
}

fn write_incremental_manifest_nonfatal(
    plan: &PublishPlan,
    manifest: Option<&super::manifest::ConversionManifest>,
) -> Option<PathBuf> {
    let manifest = manifest?;
    match super::manifest::write_manifest_for_publish(&plan.album_dir, &plan.album_dir, manifest) {
        Ok(_written_manifest_path) => Some(super::manifest::manifest_path(&plan.album_dir)),
        Err(err) => {
            log::warn!("manifest write failed during incremental publish (non-fatal): {err}");
            None
        }
    }
}

// ===========================================================================
// Durable log  (PR 6 body; PR 4 ships a minimal interim body)
// ===========================================================================

/// Write the interim durable JSON report used by PR 4.
pub fn write_durable_log(report: &PipelineReport, log: &LogPolicy) -> Result<PathBuf, LogError> {
    fs::create_dir_all(&log.root).map_err(LogError::Io)?;
    let job = sanitize_component(&report.request.job_id);
    let item = sanitize_component(&report.request.item_id);
    let path = log.root.join(format!("{job}-{item}.json"));
    let mut report_to_write = report.clone();
    report_to_write.durable_log = Some(path.clone());
    let bytes = serde_json::to_vec_pretty(&report_to_write)
        .map_err(|err| LogError::Serialization(err.to_string()))?;
    write_bytes_atomically(&path, &bytes).map_err(LogError::Io)?;
    Ok(path)
}

// ===========================================================================
// Orchestrator  (PR 4 body, final shape)
// ===========================================================================

fn enrich_source_with_label_info(source: &mut PreparedSource, container: &Path, req: &PipelineRequest) {
    super::source_heuristics::maybe_enrich(
        source,
        container,
        req.source.archive_password.as_ref().map(|s| s.expose()),
        req.naming.folder_template.as_deref(),
    );
    super::label_resolver::enrich_with_label_info(
        &mut source.album_metadata,
        container,
        super::label_resolver::dictionary_label_resolver(),
    );
}

fn request_batch_resolved_identity(req: &PipelineRequest) -> Option<&BatchResolvedAlbumIdentity> {
    req.batch_resolved_identity
        .as_ref()
        .or_else(|| req.album_batch.as_ref().and_then(|batch| batch.resolved_identity()))
}

fn remove_preserved_source_album_artist_tag(album: &mut AlbumMetadata) {
    album
        .extra
        .remove(PRESERVED_SOURCE_ALBUM_ARTIST_TAG_EXTRA_KEY);
    album
        .extra
        .remove(LEGACY_ALBUM_ARTIST_TAG_OVERRIDE_EXTRA_KEY);
}

fn apply_batch_identity_and_request_metadata(source: &mut PreparedSource, req: &PipelineRequest) {
    if let Some(identity) = request_batch_resolved_identity(req) {
        preserve_source_tags_for_organizational_identity(&mut source.album_metadata);
        if let Some(album) = identity.album.as_ref() {
            source.album_metadata.album = Some(album.clone());
        }
        if let Some(album_artist) = identity.album_artist.as_ref() {
            source.album_metadata.album_artist = Some(album_artist.clone());
        }
        if let Some(date) = identity.date.as_ref() {
            source.album_metadata.date = Some(date.clone());
        }
        if let Some(total_discs) = identity.total_discs {
            source.album_metadata.total_discs = Some(total_discs);
        }
        for track in &mut source.tracks {
            let disc = identity
                .disc_number_for_path(&source.container)
                .or_else(|| identity.disc_number_for_path(track_source_identity_path(track)));
            if let Some(disc) = disc {
                if track.id.disc_number.is_none() {
                    track.id.disc_number = Some(disc);
                }
                if track.metadata.disc_number.is_none() {
                    track.metadata.disc_number = Some(disc);
                }
            }
        }
    }

    match &req.metadata_overrides.album_artist {
        MetadataTextOverride::Keep => {}
        MetadataTextOverride::Clear => {
            source.album_metadata.album_artist = None;
            remove_preserved_source_album_artist_tag(&mut source.album_metadata);
            for track in &mut source.tracks {
                track.metadata.album_artist = None;
            }
        }
        MetadataTextOverride::Set(value) => {
            let value = value.trim();
            if !value.is_empty() {
                source.album_metadata.album_artist = Some(value.to_string());
                remove_preserved_source_album_artist_tag(&mut source.album_metadata);
                for track in &mut source.tracks {
                    track.metadata.album_artist = Some(value.to_string());
                }
            }
        }
    }
}

fn preserve_source_tags_for_organizational_identity(album: &mut AlbumMetadata) {
    if !album.extra.contains_key(PRESERVED_SOURCE_ALBUM_TAG_EXTRA_KEY) {
        if let Some(original) = album
            .extra
            .get("album")
            .cloned()
            .or_else(|| album.album.clone())
            .map(|value| value.trim().to_string())
            .filter(|value| !value.is_empty())
        {
            album
                .extra
                .insert(PRESERVED_SOURCE_ALBUM_TAG_EXTRA_KEY.to_string(), original);
        }
    }
    if !album
        .extra
        .contains_key(PRESERVED_SOURCE_ALBUM_ARTIST_TAG_EXTRA_KEY)
    {
        if let Some(original) = album
            .album_artist
            .as_ref()
            .map(|value| value.trim().to_string())
            .filter(|value| !value.is_empty())
        {
            album.extra.insert(
                PRESERVED_SOURCE_ALBUM_ARTIST_TAG_EXTRA_KEY.to_string(),
                original,
            );
        }
    }
}

fn track_source_identity_path(track: &PreparedTrack) -> &Path {
    match &track.source_ref {
        TrackSourceRef::StagedFile(path) => path.as_path(),
        TrackSourceRef::CueSegmentCarrier { source_image, .. } => source_image.as_path(),
        TrackSourceRef::ImageSegment { image, .. } => image.as_path(),
        TrackSourceRef::SacdTrack { iso, .. } => iso.as_path(),
        TrackSourceRef::DvdaTrack { volume_source, .. } => volume_source.root_or_image().as_path(),
        TrackSourceRef::DvdVideoTrack { source, .. } => source.as_path(),
        TrackSourceRef::BluRayTrack { source, .. } => source.as_path(),
    }
}


// ===========================================================================
// Scheduler split points
// ===========================================================================

/// Materialization result used by the processor-level shared scheduler.
pub enum ScheduledMaterialization {
    Ready(ScheduledAlbum),
    Finished(PipelineReport),
}

/// Album state held by the global scheduler between materialization, track
/// encoding, and album-level post-processing. The run lock stays alive for the
/// whole album so two workers cannot mutate the same staging root.
pub struct ScheduledAlbum {
    pub req: PipelineRequest,
    pub item_id: String,
    pub staging: StagingDir,
    pub source: PreparedSource,
    pub plan: AlbumPlan,
    pub stages: Vec<StageRecord>,
    _run_lock: FileLock,
}

impl ScheduledAlbum {
    pub fn track_count(&self) -> usize {
        self.source.tracks.len()
    }

    pub fn allow_partial(&self) -> bool {
        self.req.failure_policy == FailurePolicy::AllowPartialAlbum
    }

    pub fn convert_root(&self) -> PathBuf {
        self.staging.root.join("converted")
    }

    pub fn planned_final_path(&self, track_id: &TrackId) -> Option<PathBuf> {
        self.plan
            .entries
            .iter()
            .find(|entry| &entry.track_id == track_id)
            .map(|entry| entry.final_path.clone())
    }
}

#[cfg(test)]
pub(crate) fn scheduled_album_for_test(
    req: PipelineRequest,
    item_id: String,
    staging: StagingDir,
    source: PreparedSource,
    plan: AlbumPlan,
    stages: Vec<StageRecord>,
    run_lock_parent: &Path,
) -> ScheduledAlbum {
    let run_lock = acquire_run_lock(run_lock_parent, &req.job_id, &req.item_id)
        .expect("scheduled album test run lock");
    ScheduledAlbum {
        req,
        item_id,
        staging,
        source,
        plan,
        stages,
        _run_lock: run_lock,
    }
}

/// Run validation, staging setup, source materialization, and output planning.
/// Track conversion is intentionally not performed here; the caller submits
/// each ready track as an independent shared-pool work unit.
pub async fn prepare_pipeline_item_for_scheduler(
    req: PipelineRequest,
    runner: &dyn ToolRunner,
    reporter: &dyn PipelineReporter,
    cancel: &CancellationToken,
    tool_paths: &HashMap<String, PathBuf>,
) -> ScheduledMaterialization {
    let item_id = req.item_id.clone();
    let mut stages = Vec::new();
    let source: Option<PreparedSource> = None;
    let plan: Option<AlbumPlan> = None;

    if cancel.is_cancelled() {
        let published = finalize_cancelled_conversion_log_batch_if_needed(&req);
        let outcome = AlbumOutcome::Blocked {
            successful: Vec::new(),
            failed: Vec::new(),
            stages,
            reason: BlockReason::Cancelled,
        };
        return ScheduledMaterialization::Finished(
            finalize_report(&req, reporter, source, plan, None, published, outcome).await,
        );
    }

    if let Err(err) = validate_request(&req) {
        let record = stage_record(PipelineStage::Materialize, StageOutcome::Failed(err.to_string()));
        emit_stage_finished(reporter, &item_id, record.clone()).await;
        stages.push(record);
        let outcome = AlbumOutcome::Blocked {
            successful: Vec::new(),
            failed: Vec::new(),
            stages,
            reason: BlockReason::MaterializeFailed,
        };
        let published = publish_pre_materialization_conversion_log_fragment_without_existing_staging(
            &req,
            &outcome,
        );
        return ScheduledMaterialization::Finished(
            finalize_report(&req, reporter, source, plan, None, published, outcome).await,
        );
    }

    conservative_output_capacity_preflight(&req);

    emit_stage_started(reporter, &item_id, PipelineStage::Materialize).await;
    let materialization = materialize_with_optional_disk_retry(
        &req,
        select_staging_parent_for(&req),
        runner,
        Some(reporter),
        tool_paths,
        cancel,
    )
    .await;
    let (attempt, materialized) = match materialization {
        MaterializationRun::Attempted { attempt, result } => (attempt, result),
        MaterializationRun::FailedBeforeAttempt { error, context } => {
            let record = stage_record(PipelineStage::Materialize, StageOutcome::Failed(error.to_string()));
            emit_stage_finished(reporter, &item_id, record.clone()).await;
            stages.push(record);
            let outcome = AlbumOutcome::Blocked {
                successful: Vec::new(),
                failed: Vec::new(),
                stages,
                reason: BlockReason::MaterializeFailed,
            };
            let published = publish_pre_materialization_terminal_batch_failure_or_finalize(
                &req,
                &outcome,
                context,
            );
            return ScheduledMaterialization::Finished(
                finalize_report(&req, reporter, source, plan, None, published, outcome).await,
            );
        }
    };
    let (_run_lock, staging) = attempt.into_parts();

    let mut prepared = match materialized {
        Ok(prepared) => {
            let record = stage_record(PipelineStage::Materialize, StageOutcome::Ok);
            emit_stage_finished(reporter, &item_id, record.clone()).await;
            stages.push(record);
            prepared
        }
        Err(MaterializeError::BlockedSource { message, blocked }) => {
            let blocked = *blocked;
            let record = stage_record(PipelineStage::Materialize, StageOutcome::Failed(message.clone()));
            emit_stage_finished(reporter, &item_id, record.clone()).await;
            stages.push(record);
            let failed = blocked_track_records(&blocked.source, &message);
            let outcome = AlbumOutcome::Blocked {
                successful: Vec::new(),
                failed,
                stages,
                reason: BlockReason::EncryptedSource,
            };
            let source = Some(blocked.source);
            let published = publish_terminal_conversion_log_fragment_if_needed(
                &req,
                source.as_ref(),
                None,
                &outcome,
                staging,
                Some(runner),
            );
            return ScheduledMaterialization::Finished(
                finalize_report(
                    &req,
                    reporter,
                    source,
                    None,
                    None,
                    published,
                    outcome,
                )
                .await,
            );
        }
        Err(err) => {
            let reason = if matches!(err, MaterializeError::Cancelled) {
                BlockReason::Cancelled
            } else {
                BlockReason::MaterializeFailed
            };
            let record = stage_record(PipelineStage::Materialize, StageOutcome::Failed(err.to_string()));
            emit_stage_finished(reporter, &item_id, record.clone()).await;
            stages.push(record);
            let outcome = AlbumOutcome::Blocked {
                successful: Vec::new(),
                failed: Vec::new(),
                stages,
                reason,
            };
            let published = if matches!(outcome, AlbumOutcome::Blocked { reason: BlockReason::Cancelled, .. }) {
                finalize_cancelled_conversion_log_batch_if_needed(&req)
            } else {
                publish_terminal_conversion_log_fragment_if_needed(
                    &req,
                    None,
                    None,
                    &outcome,
                    staging,
                    Some(runner),
                )
            };
            return ScheduledMaterialization::Finished(
                finalize_report(&req, reporter, None, None, None, published, outcome).await,
            );
        }
    };

    if cancel.is_cancelled() {
        let published = finalize_cancelled_conversion_log_batch_if_needed(&req);
        let outcome = AlbumOutcome::Blocked {
            successful: Vec::new(),
            failed: Vec::new(),
            stages,
            reason: BlockReason::Cancelled,
        };
        return ScheduledMaterialization::Finished(
            finalize_report(&req, reporter, Some(prepared), None, None, published, outcome).await,
        );
    }

    enrich_source_with_label_info(&mut prepared, &req.container, &req);
    apply_batch_identity_and_request_metadata(&mut prepared, &req);

    emit_stage_started(reporter, &item_id, PipelineStage::PlanOutputs).await;
    let album_plan = match plan_outputs(&prepared, &req) {
        Ok(album_plan) => {
            let record = stage_record(PipelineStage::PlanOutputs, StageOutcome::Ok);
            emit_stage_finished(reporter, &item_id, record.clone()).await;
            stages.push(record);
            album_plan
        }
        Err(err) => {
            let plan_error = err.to_string();
            let record = stage_record(PipelineStage::PlanOutputs, StageOutcome::Failed(plan_error.clone()));
            emit_stage_finished(reporter, &item_id, record.clone()).await;
            stages.push(record);
            let failed = failed_track_records(
                &prepared,
                &format!("output planning failed: {plan_error}"),
            );
            let outcome = AlbumOutcome::Blocked {
                successful: Vec::new(),
                failed,
                stages,
                reason: BlockReason::PlanFailed,
            };
            let published = publish_terminal_conversion_log_fragment_if_needed(
                &req,
                Some(&prepared),
                None,
                &outcome,
                staging,
                Some(runner),
            );
            return ScheduledMaterialization::Finished(
                finalize_report(&req, reporter, Some(prepared), None, None, published, outcome).await,
            );
        }
    };

    ScheduledMaterialization::Ready(ScheduledAlbum {
        item_id,
        req,
        staging,
        source: prepared,
        plan: album_plan,
        stages,
        _run_lock,
    })
}

/// Encode one planned track. The caller controls scheduling; this function only
/// realizes the selected track, runs the planner-selected command chain, and
/// returns a deterministic record/artifact pair.
