fn pipeline_report_manifest_path(published: &Option<PublishedAlbum>) -> Option<std::path::PathBuf> {
    published
        .as_ref()
        .and_then(|album| album.manifest_path.clone())
}

async fn finalize_report(
    req: &PipelineRequest,
    reporter: &dyn PipelineReporter,
    source: Option<PreparedSource>,
    plan: Option<AlbumPlan>,
    artifacts: Option<ArtifactSet>,
    published: Option<PublishedAlbum>,
    mut outcome: AlbumOutcome,
) -> PipelineReport {
    let item_id = req.item_id.clone();
    let mut durable_log = None;
    let mut terminal_error_override: Option<String> = None;
    let settings_fingerprint = tonepoet_pipeline::fingerprint::settings_fingerprint(&req.settings);
    let should_write = req.log.write_json_log
        && match &outcome {
            AlbumOutcome::Complete { .. } | AlbumOutcome::Partial { .. } => true,
            AlbumOutcome::Blocked { .. } => req.log.write_for_blocked,
        };

    if should_write {
        emit_stage_started(reporter, &item_id, PipelineStage::DurableLog).await;
        let ok_record = stage_record(PipelineStage::DurableLog, StageOutcome::Ok);
        let mut logged_outcome = outcome.clone();
        push_stage(&mut logged_outcome, ok_record.clone());
        let report_to_write = PipelineReport {
            request: RedactedPipelineRequest::from(req),
            source: source.clone(),
            plan: plan.clone(),
            artifacts: artifacts.clone(),
            published: published.clone(),
            outcome: logged_outcome.clone(),
            durable_log: None,
            scratch_retry_intent: None,
            settings_fingerprint: Some(settings_fingerprint),
            manifest_path: pipeline_report_manifest_path(&published),
        };
        // Write the log alongside the album artifacts when possible,
        // fall back to the configured log root for blocked/failed jobs.
        let effective_log = match &published {
            Some(album) => LogPolicy {
                root: album.album_dir.clone(),
                ..req.log.clone()
            },
            None => req.log.clone(),
        };
        match write_durable_log(&report_to_write, &effective_log) {
            Ok(path) => {
                durable_log = Some(path);
                outcome = logged_outcome;
                emit_stage_finished(reporter, &item_id, ok_record).await;
            }
            Err(err) => {
                let error_text = err.to_string();
                let terminal_error =
                    durable_log_failure_terminal_error(&outcome, published.as_ref(), &error_text);
                let record =
                    stage_record(PipelineStage::DurableLog, StageOutcome::Failed(error_text));
                push_stage(&mut outcome, record.clone());
                emit_stage_finished(reporter, &item_id, record).await;
                terminal_error_override = Some(terminal_error);
                if !matches!(outcome, AlbumOutcome::Blocked { .. }) {
                    outcome = AlbumOutcome::Blocked {
                        successful: successful_tracks_from(&outcome),
                        failed: failed_tracks_from(&outcome),
                        stages: stages_from(&outcome),
                        reason: BlockReason::DurableLogFailed,
                    };
                }
            }
        }
    } else {
        let record = stage_record(PipelineStage::DurableLog, StageOutcome::Skipped);
        push_stage(&mut outcome, record.clone());
        emit_stage_finished(reporter, &item_id, record).await;
    }

    let status = terminal_status(
        &outcome,
        published.as_ref(),
        durable_log.as_deref(),
        terminal_error_override,
    );
    reporter
        .emit(PipelineEvent::Terminal { item_id, status })
        .await;

    PipelineReport {
        request: RedactedPipelineRequest::from(req),
        source,
        plan,
        artifacts,
        manifest_path: pipeline_report_manifest_path(&published),
        published,
        outcome,
        durable_log,
        scratch_retry_intent: None,
        settings_fingerprint: Some(settings_fingerprint),
    }
}

// ===========================================================================
// Real PR 1 logic — outcome aggregation + queue-status mapping
// ===========================================================================

/// Aggregate per-track records + stage records into an `AlbumOutcome`.
///
/// Rules:
/// - A `StageRecord` with `StageOutcome::Failed` always blocks ->
///   `Blocked` with `RequiredStageFailure`. Disabled stages reach
///   aggregation as `StageOutcome::Skipped` and never block.
/// - Otherwise, with no failed tracks -> `Complete`.
/// - With failed tracks: `FailAlbumOnAnyTrackFailure` -> `Blocked`
///   (`TrackFailures`); `AllowPartialAlbum` -> `Partial`.
pub fn aggregate_album_outcome(
    tracks: Vec<TrackRecord>,
    stages: Vec<StageRecord>,
    policy: FailurePolicy,
) -> AlbumOutcome {
    let (successful, failed): (Vec<TrackRecord>, Vec<TrackRecord>) = tracks
        .into_iter()
        .partition(|t| matches!(t.outcome, TrackOutcome::Ok));

    if let Some(failed_stage) = stages
        .iter()
        .find(|s| matches!(s.outcome, StageOutcome::Failed(_)))
        .map(|s| s.stage)
    {
        return AlbumOutcome::Blocked {
            successful,
            failed,
            stages,
            reason: BlockReason::RequiredStageFailure(failed_stage),
        };
    }

    if failed.is_empty() {
        return AlbumOutcome::Complete {
            tracks: successful,
            stages,
        };
    }

    match policy {
        FailurePolicy::FailAlbumOnAnyTrackFailure => AlbumOutcome::Blocked {
            successful,
            failed,
            stages,
            reason: BlockReason::TrackFailures,
        },
        FailurePolicy::AllowPartialAlbum => AlbumOutcome::Partial {
            successful,
            failed,
            stages,
        },
    }
}

/// Map a finished `AlbumOutcome` to a terminal `ConversionStatus`.
/// `Complete` -> `Completed`, `Partial` -> `Partial`, `Blocked` ->
/// `Failed`.
pub fn map_album_outcome(
    outcome: &AlbumOutcome,
    published: Option<&PublishedAlbum>,
    durable_log: Option<&Path>,
) -> ConversionStatus {
    let output_path = published.map(|p| p.album_dir.clone()).unwrap_or_default();
    let log_path = durable_log.map(|p| p.to_path_buf());

    match outcome {
        AlbumOutcome::Complete { .. } => ConversionStatus::Completed {
            output_path,
            log_path,
        },
        AlbumOutcome::Partial {
            successful, failed, ..
        } => ConversionStatus::Partial {
            output_path,
            successful: successful.len() as u32,
            failed: failed.len() as u32,
            log_path: log_path.unwrap_or_default(),
        },
        AlbumOutcome::Blocked { reason, stages, .. } => {
            let stage_error = stages.iter().rev().find_map(|r| match &r.outcome {
                StageOutcome::Failed(err) => Some(format!("{:?}: {}", r.stage, err)),
                _ => None,
            });
            let error = match stage_error {
                Some(detail) => detail,
                None => format!("album blocked: {:?}", reason),
            };
            ConversionStatus::Failed { error, log_path }
        }
    }
}

// ===========================================================================
// Private helpers
// ===========================================================================

fn durable_log_failure_terminal_error(
    outcome: &AlbumOutcome,
    published: Option<&PublishedAlbum>,
    error_text: &str,
) -> String {
    if let Some(album) = published {
        return format!(
            "durable log failed after publish; final artifacts may already exist at {}: {error_text}",
            album.album_dir.display()
        );
    }

    if let AlbumOutcome::Blocked { reason, .. } = outcome {
        return format!(
            "album blocked: {:?}; durable log failed: {error_text}",
            reason
        );
    }

    format!("durable log failed: {error_text}")
}

fn terminal_status(
    outcome: &AlbumOutcome,
    published: Option<&PublishedAlbum>,
    durable_log: Option<&Path>,
    error_override: Option<String>,
) -> ConversionStatus {
    if let Some(error) = error_override {
        return ConversionStatus::Failed {
            error,
            log_path: durable_log.map(Path::to_path_buf),
        };
    }
    map_album_outcome(outcome, published, durable_log)
}

fn validate_root_dir(path: &Path, label: &str) -> Result<(), RequestValidationError> {
    if path.as_os_str().is_empty() {
        return Err(RequestValidationError::InvalidOutputRoot(format!(
            "{label} must not be empty"
        )));
    }
    if path.exists() && !path.is_dir() {
        return Err(RequestValidationError::InvalidOutputRoot(format!(
            "{label} is not a directory: {}",
            path.display()
        )));
    }
    Ok(())
}

fn stage_record(stage: PipelineStage, outcome: StageOutcome) -> StageRecord {
    StageRecord {
        stage,
        outcome,
        dsd_dst_stats: None,
    }
}

fn convert_stage_record_for_tracks(tracks: &[TrackRecord], outcome: StageOutcome) -> StageRecord {
    StageRecord {
        stage: PipelineStage::Convert,
        outcome,
        dsd_dst_stats: aggregate_track_dsd_dst_stats(tracks),
    }
}

fn aggregate_track_dsd_dst_stats(tracks: &[TrackRecord]) -> Option<DsdDstPipelineStats> {
    let mut aggregate = DsdDstPipelineStats::default();
    for stats in tracks.iter().filter_map(|record| record.dsd_dst_stats.as_ref()) {
        aggregate.merge(stats);
    }
    if aggregate.is_empty() {
        None
    } else {
        Some(aggregate)
    }
}

fn merge_optional_dsd_dst_stats(
    base: &mut Option<DsdDstPipelineStats>,
    incoming: Option<DsdDstPipelineStats>,
) {
    let Some(incoming) = incoming else {
        return;
    };
    if incoming.is_empty() {
        return;
    }
    match base {
        Some(base) => base.merge(&incoming),
        None => *base = Some(incoming),
    }
}

fn apply_byte_totals_to_stats(
    stats: &mut Option<DsdDstPipelineStats>,
    bytes_in: Option<u64>,
    bytes_out: Option<u64>,
) {
    let Some(stats) = stats.as_mut() else {
        return;
    };
    if let Some(bytes_in) = bytes_in {
        stats.bytes_read = bytes_in;
    }
    if let Some(bytes_out) = bytes_out {
        stats.bytes_written = bytes_out;
    }
}

fn append_dsd_dst_stats_to_command_descriptions(
    commands: &mut [CommandRecord],
    stats: Option<&DsdDstPipelineStats>,
) {
    let Some(stats) = stats.filter(|stats| !stats.is_empty()) else {
        return;
    };
    let Some(command) = commands.first_mut() else {
        return;
    };
    let summary = format_dsd_dst_stats_inline(stats);
    command.description = Some(match command.description.take() {
        Some(existing) if !existing.trim().is_empty() => format!("{}; {}", existing.trim(), summary),
        _ => summary,
    });
}

fn dsd_dst_stats_from_file(
    path: &Path,
    bytes_read: Option<u64>,
    bytes_written: Option<u64>,
) -> Option<DsdDstPipelineStats> {
    if !is_dsd_container_path(path) {
        return None;
    }
    let file = fs::File::open(path).ok()?;
    let report = validate_dsd_stream(
        file,
        DsdValidationOptions {
            mode: DsdValidationMode::DecodeDst,
            max_frames: None,
        },
    );
    let mut stats = dsd_dst_stats_from_validation_report(&report);
    let output_role = bytes_written.is_some() && bytes_read.is_none();
    let input_role = bytes_read.is_some() && bytes_written.is_none();
    if output_role {
        stats.frames_read = 0;
        stats.frames_decoded = 0;
        stats.dst_decoded_frames = 0;
    }
    if input_role {
        stats.frames_emitted = 0;
    }
    stats.bytes_read = bytes_read.or_else(|| file_len(path)).unwrap_or(0);
    stats.bytes_written = bytes_written.unwrap_or(0);
    if stats.is_empty() {
        None
    } else {
        Some(stats)
    }
}

fn is_dsd_container_path(path: &Path) -> bool {
    path.extension()
        .and_then(|value| value.to_str())
        .map(|ext| matches!(ext.to_ascii_lowercase().as_str(), "dsf" | "dff"))
        .unwrap_or(false)
}

fn dsd_dst_stats_from_validation_report(report: &DsdValidationReport) -> DsdDstPipelineStats {
    let mut stats = DsdDstPipelineStats {
        frames_read: report.frames_seen(),
        frames_decoded: report.dst_frames_seen,
        frames_emitted: report.dsd_frames_seen.saturating_add(report.dst_frames_seen),
        crc_checked: report.dstc_passed_frames.saturating_add(report.dstc_failed_frames),
        crc_passed: report.dstc_passed_frames,
        crc_failed: report.dstc_failed_frames.saturating_add(report.dstc_malformed_frames),
        crc_missing: report.dstc_no_crc_frames,
        dst_decoded_frames: report.dst_frames_seen,
        ..DsdDstPipelineStats::default()
    };
    if let Some(failure) = report.failures.first() {
        stats.first_error_frame = failure.frame_index;
        stats.first_error_offset = failure.offset;
    }
    stats
}

fn dsd_dst_stats_from_extract_report(
    report: &ExtractReport,
    bytes_written: Option<u64>,
) -> Option<DsdDstPipelineStats> {
    let mut stats = DsdDstPipelineStats {
        frames_read: report.stats.frames_read,
        frames_emitted: report.stats.frames_read,
        bytes_written: bytes_written.unwrap_or(report.stats.audio_bytes),
        ..DsdDstPipelineStats::default()
    };

    if let Some(writer) = report.dff_dst_stats() {
        stats.frames_emitted = writer.frames_written;
        stats.dst_passthrough_frames = writer.passthrough_frames_written;
        stats.dst_reencoded_frames = writer.predictive_frames_written;
        stats.dst_raw_fallback_frames = writer.raw_frames_written;
        stats.bytes_read = writer.total_raw_bytes;
        stats.bytes_written = writer.total_encoded_bytes;
    }

    if stats.is_empty() {
        None
    } else {
        Some(stats)
    }
}

fn format_dsd_dst_stats_inline(stats: &DsdDstPipelineStats) -> String {
    format!(
        "DSD/DST stats: frames read {}, decoded {}, emitted {}; CRC checked {} (passed {}, failed {}, missing {}); DST passthrough {}, decoded {}, reencoded {}, raw {}; bytes read {}, written {}{}",
        stats.frames_read,
        stats.frames_decoded,
        stats.frames_emitted,
        stats.crc_checked,
        stats.crc_passed,
        stats.crc_failed,
        stats.crc_missing,
        stats.dst_passthrough_frames,
        stats.dst_decoded_frames,
        stats.dst_reencoded_frames,
        stats.dst_raw_fallback_frames,
        stats.bytes_read,
        stats.bytes_written,
        first_dsd_dst_error_suffix(stats),
    )
}

fn first_dsd_dst_error_suffix(stats: &DsdDstPipelineStats) -> String {
    match (stats.first_error_frame, stats.first_error_offset) {
        (None, None) => String::new(),
        (frame, offset) => format!(
            "; first error frame {}, offset {}",
            frame.map(|value| value.to_string()).unwrap_or_else(|| "unknown".to_string()),
            offset.map(|value| value.to_string()).unwrap_or_else(|| "unknown".to_string()),
        ),
    }
}

async fn emit_stage_started(reporter: &dyn PipelineReporter, item_id: &str, stage: PipelineStage) {
    reporter
        .emit(PipelineEvent::StageStarted {
            item_id: item_id.to_string(),
            stage,
        })
        .await;
}

async fn emit_stage_finished(reporter: &dyn PipelineReporter, item_id: &str, record: StageRecord) {
    reporter
        .emit(PipelineEvent::StageFinished {
            item_id: item_id.to_string(),
            record,
        })
        .await;
}

fn validate_template(template: &str) -> Result<(), String> {
    // Only validate structure. Unknown tokens are resolved from extra maps at render time.
    let mut rest = template;
    while let Some(start) = rest.find('%') {
        rest = &rest[start + 1..];
        let Some(end) = rest.find('%') else {
            return Err("unclosed % token".to_string());
        };
        let token = &rest[..end];
        if token.is_empty() {
            return Err("empty token %%".to_string());
        }
        rest = &rest[end + 1..];
    }
    Ok(())
}

trait TemplateRenderTarget {
    fn template_format(&self) -> &PlannerAudioFormat;
    fn template_sample_rate_hz(&self, source: &PreparedSource, track: Option<&PreparedTrack>) -> Option<u32>;
    fn template_bit_depth(&self, _source: &PreparedSource, track: Option<&PreparedTrack>) -> Option<u32>;
}

impl TemplateRenderTarget for PlannerAudioFormat {
    fn template_format(&self) -> &PlannerAudioFormat {
        self
    }

    fn template_sample_rate_hz(&self, source: &PreparedSource, track: Option<&PreparedTrack>) -> Option<u32> {
        track
            .and_then(|track| track.scalar_sample_rate())
            .or_else(|| source.tracks.first().and_then(|track| track.scalar_sample_rate()))
    }

    fn template_bit_depth(&self, _source: &PreparedSource, track: Option<&PreparedTrack>) -> Option<u32> {
        track.and_then(|track| track.bit_depth)
    }
}

impl TemplateRenderTarget for tonepoet_pipeline::PipelineSettings {
    fn template_format(&self) -> &PlannerAudioFormat {
        &self.target_format
    }

    fn template_sample_rate_hz(&self, source: &PreparedSource, track: Option<&PreparedTrack>) -> Option<u32> {
        if let Some(track) = track {
            return resolved_target_rate_hz(track, self);
        }
        source
            .tracks
            .first()
            .and_then(|track| resolved_target_rate_hz(track, self))
    }

    fn template_bit_depth(&self, _source: &PreparedSource, track: Option<&PreparedTrack>) -> Option<u32> {
        track.and_then(|track| resolved_target_bit_depth(track, self.target_bit_depth))
    }
}

fn render_track_template<T: TemplateRenderTarget + ?Sized>(
    template: &str,
    source: &PreparedSource,
    track: &PreparedTrack,
    target: &T,
) -> Result<PathBuf, PlanError> {
    let raw_album = source.album_metadata.album.as_deref().unwrap_or("Album");
    let (album, title_extra) = album_and_title_extra_for_template(template, raw_album, source);
    let title = track
        .metadata
        .title
        .as_deref()
        .map(sanitize_component)
        .unwrap_or_else(|| format!("Track {:02}", track.id.track_number));
    let artist = track
        .metadata
        .artist
        .as_deref()
        .or(source.album_metadata.album_artist.as_deref())
        .map(|artist| sanitize_component(&super::label_resolver::canonicalize_artist(artist)))
        .unwrap_or_else(|| "Unknown Artist".to_string());
    let album_artist = source
        .album_metadata
        .album_artist
        .as_deref()
        .map(|artist| sanitize_component(&super::label_resolver::canonicalize_artist(artist)))
        .unwrap_or_else(|| artist.clone());
    let disc = template_disc_number(source, track);
    let n = template_track_number(source, track);
    let year = source
        .album_metadata
        .date
        .as_deref()
        .and_then(extract_year_from_date)
        .unwrap_or_default();
    let genre = track
        .metadata
        .genre
        .as_deref()
        .or(source.album_metadata.genre.as_deref())
        .map(sanitize_component)
        .unwrap_or_default();
    let composer = track
        .metadata
        .composer
        .as_deref()
        .map(sanitize_component)
        .unwrap_or_default();
    let catalog = catalog_value(&source.album_metadata.extra)
        .map(sanitize_component)
        .unwrap_or_default();
    let sample_rate = target
        .template_sample_rate_hz(source, Some(track))
        .map(format_sample_rate)
        .map(|value| sanitize_component(&value))
        .unwrap_or_default();
    let bit_depth = target
        .template_bit_depth(source, Some(track))
        .map(|depth| depth.to_string())
        .map(|value| sanitize_component(&value))
        .unwrap_or_default();
    let isrc = track
        .metadata
        .isrc
        .as_deref()
        .map(sanitize_component)
        .unwrap_or_default();

    let mut tokens = BTreeMap::new();
    let nn = format!("{n:02}");
    tokens.insert("NN".to_string(), nn.clone());
    tokens.insert("TRACKNN".to_string(), nn);
    let n_str = n.to_string();
    tokens.insert("N".to_string(), n_str.clone());
    tokens.insert("TRACKN".to_string(), n_str.clone());
    tokens.insert("TRACK".to_string(), n_str);
    tokens.insert("TITLE".to_string(), title);
    tokens.insert("ARTIST".to_string(), artist);
    tokens.insert("ALBUM_ARTIST".to_string(), album_artist);
    tokens.insert("ALBUM".to_string(), album);
    tokens.insert("TITLE_EXTRA".to_string(), title_extra);
    // `%DISC%` intentionally remains raw/back-compatible: it renders the best
    // available disc hint, defaulting to `1` for single-disc albums. The newer
    // `%DISCNUMBER%` family below is evidence-gated and renders empty unless a
    // multi-disc layout is proven, so conditional blocks can drop cleanly.
    tokens.insert("DISC".to_string(), disc.to_string());
    insert_disc_template_tokens(&mut tokens, source, Some(track));
    tokens.insert("FORMAT".to_string(), target.template_format().display_name().to_string());
    tokens.insert("YEAR".to_string(), year);
    tokens.insert("GENRE".to_string(), genre);
    tokens.insert("COMPOSER".to_string(), composer);
    tokens.insert("CATALOG".to_string(), catalog);
    tokens.insert("SAMPLERATE".to_string(), sample_rate);
    tokens.insert("BITDEPTH".to_string(), bit_depth);
    tokens.insert("ISRC".to_string(), isrc);
    tokens.insert("EXT".to_string(), String::new());

    let rendered = render_template_with_tokens(
        template,
        &tokens,
        Some(&track.metadata.extra),
        &source.album_metadata.extra,
    );

    let rel = path_from_template_components(&rendered);
    if rel.as_os_str().is_empty() {
        return Err(PlanError::InvalidTemplate(
            "template rendered empty".to_string(),
        ));
    }
    Ok(rel)
}

fn render_folder_template<T: TemplateRenderTarget + ?Sized>(
    template: &str,
    source: &PreparedSource,
    target: &T,
) -> PathBuf {
    render_folder_template_with_track(template, source, None, target)
}

fn render_folder_template_for_track<T: TemplateRenderTarget + ?Sized>(
    template: &str,
    source: &PreparedSource,
    track: &PreparedTrack,
    target: &T,
) -> PathBuf {
    render_folder_template_with_track(template, source, Some(track), target)
}

fn render_folder_template_with_track<T: TemplateRenderTarget + ?Sized>(
    template: &str,
    source: &PreparedSource,
    track: Option<&PreparedTrack>,
    target: &T,
) -> PathBuf {
    let artist = source
        .album_metadata
        .album_artist
        .as_deref()
        .or_else(|| {
            source
                .tracks
                .iter()
                .find_map(|track| track.metadata.artist.as_deref())
        })
        .map(|artist| sanitize_component(&super::label_resolver::canonicalize_artist(artist)))
        .unwrap_or_else(|| "Unknown Artist".to_string());
    let raw_album = source
        .album_metadata
        .album
        .as_deref()
        .or_else(|| source.container.file_stem().and_then(|s| s.to_str()))
        .unwrap_or("Album");
    let (album, title_extra) = album_and_title_extra_for_template(template, raw_album, source);
    let year = source
        .album_metadata
        .date
        .as_deref()
        .and_then(extract_year_from_date)
        .unwrap_or_default();
    let genre = source
        .album_metadata
        .genre
        .as_deref()
        .map(sanitize_component)
        .unwrap_or_default();
    let catalog = catalog_value(&source.album_metadata.extra)
        .map(sanitize_component)
        .unwrap_or_default();
    let sample_rate = target
        .template_sample_rate_hz(source, None)
        .map(format_sample_rate)
        .map(|value| sanitize_component(&value))
        .unwrap_or_default();
    let bit_depth = target
        .template_bit_depth(source, source.tracks.first())
        .map(|depth| depth.to_string())
        .map(|value| sanitize_component(&value))
        .unwrap_or_default();

    let mut tokens = BTreeMap::new();
    tokens.insert("ARTIST".to_string(), artist.clone());
    tokens.insert("ALBUM_ARTIST".to_string(), artist);
    tokens.insert("ALBUM".to_string(), album);
    tokens.insert("TITLE_EXTRA".to_string(), title_extra);
    tokens.insert("YEAR".to_string(), year);
    tokens.insert("GENRE".to_string(), genre);
    tokens.insert("CATALOG".to_string(), catalog);
    tokens.insert("FORMAT".to_string(), target.template_format().display_name().to_string());
    tokens.insert("SAMPLERATE".to_string(), sample_rate);
    tokens.insert("BITDEPTH".to_string(), bit_depth);
    tokens.insert("EXT".to_string(), String::new());
    insert_disc_template_tokens(&mut tokens, source, track);

    let rendered = render_template_with_tokens(template, &tokens, None, &source.album_metadata.extra);
    path_from_template_components(&rendered)
}

fn album_and_title_extra_for_template(
    template: &str,
    raw_album: &str,
    source: &PreparedSource,
) -> (String, String) {
    if !template.contains("%TITLE_EXTRA%") {
        return (sanitize_component(raw_album), String::new());
    }
    match extract_title_extra(raw_album) {
        Some((clean, extra)) => {
            let strip_resolution = template.contains("%BITDEPTH%") || template.contains("%SAMPLERATE%");
            let normalized = normalize_title_extra_for_template(&extra, source, strip_resolution);
            (sanitize_component(&clean), sanitize_component(&normalized))
        }
        None => (sanitize_component(raw_album), String::new()),
    }
}


#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct DiscTemplateData {
    disc: u32,
    total: Option<u32>,
}

fn insert_disc_template_tokens(
    tokens: &mut BTreeMap<String, String>,
    source: &PreparedSource,
    track: Option<&PreparedTrack>,
) {
    let data = track.and_then(|track| disc_template_data(source, track));
    let disc = data.map(|data| data.disc);
    let total = data
        .and_then(|data| data.total)
        .or_else(|| source_has_proven_multi_disc_layout(source).then(|| source_disc_total_for_template(source)).flatten());
    tokens.insert(
        "DISCNUMBER".to_string(),
        disc.map(|value| value.to_string()).unwrap_or_default(),
    );
    tokens.insert(
        "NNDISCNUMBER".to_string(),
        disc.map(|value| format!("{value:02}")).unwrap_or_default(),
    );
    tokens.insert(
        "NNNDISCNUMBER".to_string(),
        disc.map(|value| format!("{value:03}")).unwrap_or_default(),
    );
    tokens.insert(
        "DISCTOTAL".to_string(),
        total.map(|value| value.to_string()).unwrap_or_default(),
    );
    tokens.insert(
        "DISC_FOLDER".to_string(),
        data.map(|data| sanitize_component(&format!("disc {:02}", data.disc)))
            .unwrap_or_default(),
    );
}

fn disc_template_data(source: &PreparedSource, track: &PreparedTrack) -> Option<DiscTemplateData> {
    if !source_has_proven_multi_disc_layout(source) {
        return None;
    }
    let disc = track_disc_number_hint(source, track).filter(|disc| *disc > 0)?;
    Some(DiscTemplateData {
        disc,
        total: source_disc_total_for_template(source),
    })
}


fn source_disc_total_for_template(source: &PreparedSource) -> Option<u32> {
    let mut total = source
        .album_metadata
        .total_discs
        .filter(|value| *value > 1)
        .or_else(|| source_disc_total_extra_hint(source).filter(|value| *value > 1));
    let mut disc_numbers = BTreeSet::new();
    let mut max_track_total = 0_u32;
    for track in &source.tracks {
        if let Some(disc) = track_disc_number_hint(source, track).filter(|value| *value > 0) {
            disc_numbers.insert(disc);
        }
        if let Some(track_total) = track_disc_total_hint(track).filter(|value| *value > 1) {
            max_track_total = max_track_total.max(track_total);
        }
    }
    total = total.or_else(|| (max_track_total > 1).then_some(max_track_total));
    total.or_else(|| {
        (disc_numbers.len() > 1)
            .then(|| disc_numbers.iter().copied().max())
            .flatten()
            .filter(|value| *value > 1)
    })
}

fn source_has_proven_multi_disc_layout(source: &PreparedSource) -> bool {
    if source.album_metadata.total_discs.unwrap_or(0) > 1 {
        return true;
    }
    if source_disc_total_extra_hint(source).unwrap_or(0) > 1 {
        return true;
    }
    if source_disc_number_hint(source).unwrap_or(0) > 1 {
        return true;
    }

    let mut disc_numbers = BTreeSet::new();
    let mut max_disc_total = 0_u32;
    for track in &source.tracks {
        if let Some(disc) = track_disc_number_hint(source, track).filter(|disc| *disc > 0) {
            disc_numbers.insert(disc);
        }
        max_disc_total = max_disc_total.max(track_disc_total_hint(track).unwrap_or(0));
    }
    disc_numbers.len() > 1 || max_disc_total > 1
}

fn template_disc_number(source: &PreparedSource, track: &PreparedTrack) -> u32 {
    track_disc_number_hint(source, track)
        .filter(|disc| *disc > 0)
        .unwrap_or(1)
}

fn template_track_number(source: &PreparedSource, track: &PreparedTrack) -> u32 {
    let metadata_number = track.metadata.track_number.filter(|value| *value > 0);
    let path_number = track_number_from_source_ref_path(track).filter(|value| *value > 0);

    // Archive materialization can preserve source filenames even when tags are
    // absent, stale, or normalized to a flat sequence. When one-file-per-track
    // paths prove a multi-disc layout or duplicate filename prefixes, prefer
    // those filename prefixes for `%NN%`/`%TRACK%`. Disc folder assignment
    // remains driven by explicit disc metadata or source path disc directories.
    if source_has_multiple_path_disc_numbers(source) || source_has_duplicate_source_path_track_numbers(source) {
        path_number
            .or(metadata_number)
            .unwrap_or(track.id.track_number)
    } else {
        metadata_number
            .or(path_number)
            .unwrap_or(track.id.track_number)
    }
}

fn track_disc_number_hint(source: &PreparedSource, track: &PreparedTrack) -> Option<u32> {
    let explicit = track
        .id
        .disc_number
        .or(track.metadata.disc_number)
        .or_else(|| track_disc_number_extra_hint(track));
    let path = track_disc_number_from_source_ref_path(track);
    let source_scope = source_disc_number_hint(source);

    // If multiple disc directories are present in the materialized source tree,
    // they are stronger evidence than tags that may have been missing, flattened,
    // or duplicated during archive extraction. Source-scope album metadata is a
    // final fallback for carrier/image materializers that know the disc at
    // album/source scope but do not repeat it into every logical track.
    if source_has_multiple_path_disc_numbers(source) {
        path.or(explicit).or(source_scope)
    } else {
        explicit.or(path).or(source_scope)
    }
}

fn track_disc_total_hint(track: &PreparedTrack) -> Option<u32> {
    track_disc_total_extra_hint(track)
}

fn source_disc_number_hint(source: &PreparedSource) -> Option<u32> {
    source
        .album_metadata
        .disc_number
        .filter(|disc| *disc > 0)
        .or_else(|| source_disc_number_extra_hint(source))
}

fn source_disc_number_extra_hint(source: &PreparedSource) -> Option<u32> {
    for key in ["discnumber", "disc_number", "disc"] {
        let Some(raw) = extra_value_case_insensitive(&source.album_metadata.extra, key) else {
            continue;
        };
        if let Some((disc, _)) = parse_disc_number_hint_for_key(key, raw) {
            if disc.is_some() {
                return disc;
            }
        }
    }
    None
}

fn source_disc_total_extra_hint(source: &PreparedSource) -> Option<u32> {
    for key in ["disctotal", "disc_total", "discnumber", "disc_number", "disc"] {
        let Some(raw) = extra_value_case_insensitive(&source.album_metadata.extra, key) else {
            continue;
        };
        if let Some((_, total)) = parse_disc_number_hint_for_key(key, raw) {
            if total.is_some() {
                return total;
            }
        }
    }
    None
}

fn track_disc_number_extra_hint(track: &PreparedTrack) -> Option<u32> {
    for key in ["discnumber", "disc_number", "disc"] {
        let Some(raw) = extra_value_case_insensitive(&track.metadata.extra, key) else {
            continue;
        };
        if let Some((disc, _)) = parse_disc_number_hint_for_key(key, raw) {
            if disc.is_some() {
                return disc;
            }
        }
    }
    None
}

fn track_disc_total_extra_hint(track: &PreparedTrack) -> Option<u32> {
    for key in ["disctotal", "disc_total", "discnumber", "disc_number", "disc"] {
        let Some(raw) = extra_value_case_insensitive(&track.metadata.extra, key) else {
            continue;
        };
        if let Some((_, total)) = parse_disc_number_hint_for_key(key, raw) {
            if total.is_some() {
                return total;
            }
        }
    }
    None
}

fn source_has_multiple_path_disc_numbers(source: &PreparedSource) -> bool {
    let mut disc_numbers = BTreeSet::new();
    for track in &source.tracks {
        if let Some(disc) = track_disc_number_from_source_ref_path(track).filter(|disc| *disc > 0) {
            disc_numbers.insert(disc);
            if disc_numbers.len() > 1 {
                return true;
            }
        }
    }
    false
}

fn source_has_duplicate_source_path_track_numbers(source: &PreparedSource) -> bool {
    let mut seen = BTreeSet::new();
    for track in &source.tracks {
        let Some(n) = track_number_from_source_ref_path(track).filter(|value| *value > 0) else {
            continue;
        };
        if !seen.insert(n) {
            return true;
        }
    }
    false
}

fn track_number_from_source_ref_path(track: &PreparedTrack) -> Option<u32> {
    // Only one-file-per-track staged sources are allowed to contribute a
    // filename-prefix track number to template rendering. Carrier/container
    // source refs (CUE images, SACD ISOs, DVD-A/DVD-Video/Blu-ray roots) can
    // back many logical tracks with one shared path; using that shared path's
    // prefix would collapse `%NN%`/`%TRACK%` for every logical track in the
    // carrier.
    let path = track_specific_template_source_file_path(&track.source_ref)?;
    strict_track_number_from_path_stem(path)
}

fn track_disc_number_from_source_ref_path(track: &PreparedTrack) -> Option<u32> {
    let path = template_source_file_path(&track.source_ref)?;
    disc_number_from_path_ancestors(path)
}

fn track_specific_template_source_file_path(source_ref: &TrackSourceRef) -> Option<&Path> {
    match source_ref {
        TrackSourceRef::StagedFile(path) => Some(path.as_path()),
        TrackSourceRef::CueSegmentCarrier { .. }
        | TrackSourceRef::ImageSegment { .. }
        | TrackSourceRef::SacdTrack { .. }
        | TrackSourceRef::DvdaTrack { .. }
        | TrackSourceRef::DvdVideoTrack { .. }
        | TrackSourceRef::BluRayTrack { .. } => None,
    }
}

fn template_source_file_path(source_ref: &TrackSourceRef) -> Option<&Path> {
    match source_ref {
        TrackSourceRef::StagedFile(path) => Some(path.as_path()),
        TrackSourceRef::CueSegmentCarrier { source_image, .. } => Some(source_image.as_path()),
        TrackSourceRef::ImageSegment { image, .. } => Some(image.as_path()),
        TrackSourceRef::SacdTrack { iso, .. } => Some(iso.as_path()),
        TrackSourceRef::DvdaTrack { volume_source, .. } => match volume_source {
            DvdaVolumeSourceRef::Directory { root }
            | DvdaVolumeSourceRef::Iso { path: root, .. }
            | DvdaVolumeSourceRef::StagedAudioTs { root, .. } => Some(root.as_path()),
        },
        TrackSourceRef::DvdVideoTrack { source, .. }
        | TrackSourceRef::BluRayTrack { source, .. } => Some(source.as_path()),
    }
}

fn strict_track_number_from_path_stem(path: &Path) -> Option<u32> {
    let stem = path.file_stem()?.to_str()?.trim();
    let mut digits = String::new();
    for ch in stem.chars() {
        if ch.is_ascii_digit() {
            digits.push(ch);
        } else {
            break;
        }
    }
    if digits.is_empty() || digits.len() > 3 {
        return None;
    }
    let rest = &stem[digits.len()..];
    if !has_strict_track_prefix_separator_for_template(rest) {
        return None;
    }
    digits.parse::<u32>().ok().filter(|value| *value > 0)
}

fn has_strict_track_prefix_separator_for_template(rest: &str) -> bool {
    if rest.is_empty() {
        return true;
    }
    let trimmed = rest.trim_start();
    matches!(trimmed.chars().next(), Some('-' | '_' | '.' | ')' | ']'))
}

fn disc_number_from_path_ancestors(path: &Path) -> Option<u32> {
    for ancestor in path.ancestors().skip(1) {
        let Some(name) = ancestor.file_name().and_then(|value| value.to_str()) else {
            continue;
        };
        if let Some(number) = disc_number_from_template_component_name(name) {
            return Some(number);
        }
    }
    None
}

fn disc_number_from_template_component_name(name: &str) -> Option<u32> {
    let lower = name.trim().to_ascii_lowercase();
    for prefix in ["disc", "disk", "cd"] {
        let Some(rest) = lower.strip_prefix(prefix) else {
            continue;
        };
        let rest = rest.trim_start();
        let rest = rest
            .strip_prefix('-')
            .or_else(|| rest.strip_prefix('_'))
            .or_else(|| rest.strip_prefix('.'))
            .or_else(|| rest.strip_prefix(' '))
            .unwrap_or(rest)
            .trim_start();
        let digits: String = rest.chars().take_while(|ch| ch.is_ascii_digit()).collect();
        if digits.is_empty() {
            continue;
        }
        if let Ok(number) = digits.parse::<u32>() {
            if number > 0 {
                return Some(number);
            }
        }
    }
    None
}

fn extra_value_case_insensitive<'a>(extra: &'a BTreeMap<String, String>, key: &str) -> Option<&'a str> {
    extra
        .get(key)
        .map(String::as_str)
        .or_else(|| {
            extra
                .iter()
                .find(|(candidate, _)| candidate.eq_ignore_ascii_case(key))
                .map(|(_, value)| value.as_str())
        })
}

fn parse_disc_number_hint_for_key(key: &str, value: &str) -> Option<(Option<u32>, Option<u32>)> {
    let mut nums = value
        .split(|ch: char| !ch.is_ascii_digit())
        .filter(|part| !part.is_empty())
        .filter_map(|part| part.parse::<u32>().ok());
    let first = nums.next();
    let second = nums.next();
    match (first, second) {
        (None, _) => None,
        (Some(total), None) if key.contains("total") => Some((None, Some(total))),
        (Some(disc), None) => Some((Some(disc), None)),
        (disc, total) => Some((disc, total)),
    }
}

fn render_template_with_tokens(
    template: &str,
    tokens: &BTreeMap<String, String>,
    track_extra: Option<&BTreeMap<String, String>>,
    album_extra: &BTreeMap<String, String>,
) -> String {
    let conditional = render_conditional_template_blocks(template, tokens, track_extra, album_extra);
    render_template_segment(&conditional, tokens, track_extra, album_extra)
}

fn render_conditional_template_blocks(
    template: &str,
    tokens: &BTreeMap<String, String>,
    track_extra: Option<&BTreeMap<String, String>>,
    album_extra: &BTreeMap<String, String>,
) -> String {
    let mut output = String::with_capacity(template.len());
    let mut rest = template;
    let mut suppress_leading_whitespace_after_dropped_block = false;

    while let Some(open) = rest.find('{') {
        let prefix = &rest[..open];
        if suppress_leading_whitespace_after_dropped_block && output.ends_with(char::is_whitespace) {
            output.push_str(prefix.trim_start_matches(char::is_whitespace));
        } else {
            output.push_str(prefix);
        }
        suppress_leading_whitespace_after_dropped_block = false;

        let after_open = &rest[open + 1..];
        let Some(close) = after_open.find('}') else {
            output.push('{');
            output.push_str(after_open);
            return output;
        };
        let block = &after_open[..close];
        let variables = template_tokens_in(block);
        let block_resolves = !variables.is_empty()
            && variables.iter().all(|token| {
                !resolve_template_token(token, tokens, track_extra, album_extra)
                    .trim()
                    .is_empty()
            });

        if block_resolves {
            if conditional_block_unwraps_when_resolved(block) {
                output.push_str(block);
            } else {
                // Historical templates used `{%TITLE_EXTRA%}` as both the
                // conditional guard and the literal brace punctuation around
                // release qualifiers. Keep that compatibility for ordinary
                // metadata blocks, but treat disc-routing conditionals as real
                // conditional path/layout delimiters so documented templates
                // like `{disc %NNDISCNUMBER%/}%TRACKNN% - %TITLE%` do not
                // publish brace-polluted directories.
                output.push('{');
                output.push_str(block);
                output.push('}');
            }
        } else {
            // The whole block is omitted. If the template had a space before
            // and after the conditional, e.g. `Album {%EXTRA%} (%YEAR%)`,
            // omitting the middle block should leave exactly one separator:
            // `Album (%YEAR%)`, not `Album  (%YEAR%)`.
            suppress_leading_whitespace_after_dropped_block = true;
        }
        rest = &after_open[close + 1..];
    }

    if suppress_leading_whitespace_after_dropped_block && output.ends_with(char::is_whitespace) {
        output.push_str(rest.trim_start_matches(char::is_whitespace));
    } else {
        output.push_str(rest);
    }
    output
}


fn conditional_block_unwraps_when_resolved(block: &str) -> bool {
    template_tokens_in(block).iter().any(|token| {
        matches!(
            token.as_str(),
            "DISC_FOLDER" | "DISCNUMBER" | "NNDISCNUMBER" | "NNNDISCNUMBER"
        )
    })
}

fn render_template_segment(
    segment: &str,
    tokens: &BTreeMap<String, String>,
    track_extra: Option<&BTreeMap<String, String>>,
    album_extra: &BTreeMap<String, String>,
) -> String {
    let mut output = String::with_capacity(segment.len());
    let mut rest = segment;
    while let Some(start) = rest.find('%') {
        output.push_str(&rest[..start]);
        rest = &rest[start + 1..];
        let Some(end) = rest.find('%') else {
            output.push('%');
            output.push_str(rest);
            return output;
        };
        let token = &rest[..end];
        output.push_str(&resolve_template_token(token, tokens, track_extra, album_extra));
        rest = &rest[end + 1..];
    }
    output.push_str(rest);
    output
}

fn template_tokens_in(segment: &str) -> Vec<String> {
    let mut tokens = Vec::new();
    let mut rest = segment;
    while let Some(start) = rest.find('%') {
        rest = &rest[start + 1..];
        let Some(end) = rest.find('%') else {
            break;
        };
        let token = rest[..end].to_string();
        if !tokens.iter().any(|existing| existing == &token) {
            tokens.push(token);
        }
        rest = &rest[end + 1..];
    }
    tokens
}

fn resolve_template_token(
    token: &str,
    tokens: &BTreeMap<String, String>,
    track_extra: Option<&BTreeMap<String, String>>,
    album_extra: &BTreeMap<String, String>,
) -> String {
    if let Some(value) = tokens.get(token) {
        return value.clone();
    }
    let key = token.to_ascii_lowercase();
    track_extra
        .and_then(|extra| extra.get(&key))
        .or_else(|| album_extra.get(&key))
        .map(|value| sanitize_component(value))
        .unwrap_or_default()
}

fn path_from_template_components(rendered: &str) -> PathBuf {
    let mut path = PathBuf::new();
    for component in rendered
        .split('/')
        .map(|component| component.trim().trim_matches('.').trim())
        .filter(|component| !component.is_empty())
    {
        path.push(component);
    }
    path
}

/// Extract metadata from a trailing parenthetical in an album name.
///
/// Scans for the last `(content)` optionally followed by `[bracket]` at the
/// end of the string. If the parenthetical content looks like release metadata
/// (catalog, format, region, or resolution), returns `Some((clean_album,
/// extra_content))`. Otherwise returns `None` so title subtitles are preserved.
///
/// Only called when `%TITLE_EXTRA%` appears in the template.
fn extract_title_extra(album: &str) -> Option<(String, String)> {
    // Find the last '(' that has a matching ')'
    let mut depth = 0_i32;
    let mut last_open = None;
    let mut last_close = None;
    for (i, ch) in album.char_indices().rev() {
        match ch {
            ')' => {
                depth += 1;
                if last_close.is_none() {
                    last_close = Some(i);
                }
            }
            '(' => {
                depth -= 1;
                if depth == 0 {
                    last_open = Some(i);
                    break;
                }
            }
            _ => {}
        }
    }

    let open = last_open?;
    let close = last_close?;
    if close <= open || open == 0 {
        return None;
    }

    let content = &album[open + 1..close];
    if content.trim().is_empty() {
        return None;
    }

    if !super::label_resolver::contains_metadata_identifier(content)
        && !looks_like_title_extra_metadata(content)
    {
        return None;
    }

    let before = album[..open].trim_end();
    let after = album[close + 1..].trim_start();
    let clean = if after.starts_with('[') {
        if let Some(bracket_end) = after.find(']') {
            let remainder = after[bracket_end + 1..].trim();
            if remainder.is_empty() {
                before.to_string()
            } else {
                format!("{} {}", before, remainder)
            }
        } else {
            before.to_string()
        }
    } else if after.is_empty() {
        before.to_string()
    } else {
        format!("{} {}", before, after)
    };

    Some((clean, content.trim().to_string()))
}

fn normalize_title_extra_for_template(
    extra: &str,
    source: &PreparedSource,
    strip_resolution: bool,
) -> String {
    let mut normalized = extra.trim().to_string();
    if title_extra_should_strip_iso_for_source(source) {
        normalized = strip_iso_marker_from_title_extra(&normalized);
    }
    if strip_resolution {
        normalized = strip_resolution_from_title_extra(&normalized);
    }
    normalized
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .trim_matches(|ch: char| ch == '/' || ch == '-' || ch.is_whitespace())
        .to_string()
}

fn title_extra_should_strip_iso_for_source(source: &PreparedSource) -> bool {
    matches!(source.kind, SourceKind::SacdIso | SourceKind::DvdAudio | SourceKind::DvdVideo)
        || source
            .container
            .extension()
            .and_then(|ext| ext.to_str())
            .is_some_and(|ext| ext.eq_ignore_ascii_case("iso"))
}

fn strip_iso_marker_from_title_extra(extra: &str) -> String {
    let mut kept = Vec::new();
    for part in extra.split('/') {
        let words = part
            .split_whitespace()
            .filter(|word| {
                !word
                    .trim_matches(|ch: char| !ch.is_ascii_alphanumeric() && ch != '-')
                    .eq_ignore_ascii_case("iso")
            })
            .collect::<Vec<_>>()
            .join(" ");
        if !words.trim().is_empty() {
            kept.push(words);
        }
    }
    kept.join(" / ")
}

fn strip_resolution_from_title_extra(extra: &str) -> String {
    let mut parts = Vec::new();
    for part in extra.split('/') {
        let trimmed = part.trim();
        if !looks_like_resolution_fragment(trimmed) {
            parts.push(trimmed);
        }
    }
    let joined = parts.join(" / ");
    joined
        .split_whitespace()
        .filter(|token| !looks_like_resolution_fragment(token.trim_matches(|ch| ch == '(' || ch == ')' || ch == ',')))
        .collect::<Vec<_>>()
        .join(" ")
}

fn looks_like_title_extra_metadata(content: &str) -> bool {
    let lower = content.to_ascii_lowercase();
    // Region words ("US", "UK", "Japan", ...) are deliberately NOT evidence:
    // a country-only parenthetical is album identity ("Aftermath (US)" and
    // "Aftermath (UK)" are different albums) and must stay in the title.
    // Region-bearing pressing designators still extract because they carry
    // format/resolution/catalog evidence of their own ("Japan / SHM SACD ISO").
    let has_format_or_region = [
        "blu-ray", "bluray", "dvd-a", "dvda", "dvd-v", "dvdv", "sacd", "shm", "shm-cd",
        "iso", "lp", "cd", "mfsl", "mofi",
        "mobile", "fidelity", "first-press", "pressing",
    ]
    .iter()
    .any(|needle| lower.split(|ch: char| !ch.is_ascii_alphanumeric() && ch != '-').any(|word| word == *needle));
    let has_resolution = content
        .split(|ch: char| ch.is_whitespace() || ch == '/' || ch == ',' || ch == ';')
        .any(looks_like_resolution_fragment);
    let has_catalog = content.split_whitespace().any(looks_like_catalog_fragment);
    has_format_or_region || has_resolution || has_catalog
}

fn looks_like_catalog_fragment(fragment: &str) -> bool {
    let cleaned = fragment.trim_matches(|ch: char| !ch.is_ascii_alphanumeric() && ch != '-');
    if cleaned.len() < 4 {
        return false;
    }
    let has_alpha = cleaned.chars().any(|ch| ch.is_ascii_alphabetic());
    let has_digit = cleaned.chars().any(|ch| ch.is_ascii_digit());
    let has_separator = cleaned.contains('-');
    has_alpha && has_digit && (has_separator || cleaned.chars().filter(|ch| ch.is_ascii_digit()).count() >= 3)
}

fn looks_like_resolution_fragment(fragment: &str) -> bool {
    let cleaned = fragment
        .trim()
        .trim_matches(|ch: char| ch == '(' || ch == ')' || ch == '[' || ch == ']' || ch == ',')
        .to_ascii_lowercase();
    if cleaned.is_empty() {
        return false;
    }
    if cleaned.ends_with("khz") || cleaned.ends_with("kbps") || cleaned.ends_with("hz") {
        return cleaned.chars().any(|ch| ch.is_ascii_digit());
    }
    let compact = cleaned.replace("/", "-");
    let mut pieces = compact.split('-');
    let first = pieces.next().unwrap_or_default();
    let second = pieces.next().unwrap_or_default();
    pieces.next().is_none()
        && matches!(first, "16" | "20" | "24" | "32")
        && second.parse::<u32>().is_ok_and(|rate| matches!(rate, 44 | 48 | 88 | 96 | 176 | 192 | 352 | 384 | 705 | 768))
}

fn catalog_value(extra: &BTreeMap<String, String>) -> Option<&str> {
    extra
        .get("catalog")
        .or_else(|| extra.get("catalognumber"))
        .or_else(|| extra.get("sacd_album_catalog_number"))
        .map(String::as_str)
}

fn extract_year_from_date(date: &str) -> Option<String> {
    let mut run = String::new();
    for ch in date.chars() {
        if ch.is_ascii_digit() {
            run.push(ch);
            if run.len() == 4 {
                return Some(run);
            }
        } else {
            run.clear();
        }
    }
    None
}

fn format_sample_rate(hz: u32) -> String {
    const DSD64_HZ: u32 = 2_822_400;
    if hz >= DSD64_HZ && hz % DSD64_HZ == 0 {
        return format!("DSD{}", 64 * (hz / DSD64_HZ));
    }
    if hz % 1_000 == 0 {
        return format!("{}kHz", hz / 1_000);
    }
    if hz % 100 == 0 {
        return format!("{:.1}kHz", hz as f64 / 1_000.0);
    }
    let mut khz = format!("{:.3}", hz as f64 / 1_000.0);
    while khz.contains('.') && khz.ends_with('0') {
        khz.pop();
    }
    if khz.ends_with('.') {
        khz.pop();
    }
    format!("{khz}kHz")
}

fn sanitize_component(value: &str) -> String {
    let sanitized: String = value
        .chars()
        .map(|ch| match ch {
            '/' | '\\' | ':' | '*' | '?' | '"' | '<' | '>' | '|' => ' ',
            ch if ch.is_control() => ' ',
            ch => ch,
        })
        .collect();
    let trimmed = sanitized.trim().trim_matches('.').to_string();
    if trimmed.is_empty() {
        "untitled".to_string()
    } else {
        trimmed
    }
}

fn reject_escaping_path(path: &Path) -> Result<(), String> {
    if path.is_absolute() {
        return Err(format!("absolute path not allowed: {}", path.display()));
    }
    for component in path.components() {
        match component {
            Component::ParentDir | Component::Prefix(_) | Component::RootDir => {
                return Err(format!("path escapes destination: {}", path.display()));
            }
            Component::CurDir | Component::Normal(_) => {}
        }
    }
    Ok(())
}

fn normalize_path(path: &Path) -> PathBuf {
    let mut normalized = PathBuf::new();
    for component in path.components() {
        match component {
            Component::CurDir => {}
            Component::ParentDir => {
                normalized.pop();
            }
            _ => normalized.push(component.as_os_str()),
        }
    }
    normalized
}

fn path_is_under_root(path: &Path, root: &Path) -> bool {
    let path = normalize_path(path);
    let root = normalize_path(root);
    path == root || path.starts_with(root)
}

fn parent_dir_or_current(path: &Path) -> &Path {
    match path.parent() {
        Some(parent) if !parent.as_os_str().is_empty() => parent,
        _ => Path::new("."),
    }
}

fn normalized_collision_key(path: &Path) -> String {
    path.to_string_lossy().to_ascii_lowercase()
}

fn default_audio_container_extension<'a>(
    format: &'a PlannerAudioFormat,
    container_extension: Option<&'a str>,
) -> &'a str {
    match format {
        PlannerAudioFormat::Aac | PlannerAudioFormat::Alac => match container_extension {
            Some(extension) if matches!(extension.trim().to_ascii_lowercase().as_str(), "m4a" | "mp4") => {
                extension
            }
            _ => "m4a",
        },
        _ => match container_extension {
            Some(extension) if !extension.trim().is_empty() => extension,
            _ => format.extension(),
        },
    }
}

fn validate_final_container_extension(
    format: &PlannerAudioFormat,
    container_extension: Option<&str>,
) -> Result<(), String> {
    let Some(extension) = container_extension
        .map(str::trim)
        .filter(|extension| !extension.is_empty())
        .map(|extension| extension.to_ascii_lowercase())
    else {
        return Ok(());
    };

    match format {
        PlannerAudioFormat::Aac => match extension.as_str() {
            "m4a" | "mp4" => Ok(()),
            "aac" => Err(
                "AAC output is muxed as MP4/M4A by this pipeline; raw .aac output is not implemented, so use .m4a/.mp4 or add an explicit raw-AAC mode".to_string(),
            ),
            _ => Err(
                "AAC output must use an .m4a or .mp4 container extension unless an explicit raw-AAC mode is implemented".to_string(),
            ),
        },
        PlannerAudioFormat::Alac => match extension.as_str() {
            "m4a" | "mp4" => Ok(()),
            _ => Err("ALAC output must use an .m4a or .mp4 container extension".to_string()),
        },
        _ => Ok(()),
    }
}

fn append_default_extension(
    path: &mut PathBuf,
    format: &PlannerAudioFormat,
    container_extension: Option<&str>,
) {
    let ext = default_audio_container_extension(format, container_extension);
    if path
        .extension()
        .and_then(|e| e.to_str())
        .map(|e| e.eq_ignore_ascii_case(ext))
        .unwrap_or(false)
    {
        return;
    }
    path.set_extension(ext);
}

fn append_collision_suffix(path: &Path, suffix: &str) -> PathBuf {
    let parent = path.parent().map(Path::to_path_buf).unwrap_or_default();
    let stem = path.file_stem().and_then(|s| s.to_str()).unwrap_or("track");
    let ext = path.extension().and_then(|s| s.to_str());
    let mut file_name = format!("{stem}-{suffix}");
    if let Some(ext) = ext {
        file_name.push('.');
        file_name.push_str(ext);
    }
    parent.join(file_name)
}

fn staged_audio_path(
    convert_root: &Path,
    final_path: &Path,
    id: &TrackId,
    format: &PlannerAudioFormat,
) -> PathBuf {
    let file_stem = final_path
        .file_stem()
        .and_then(|s| s.to_str())
        .map(sanitize_component)
        .unwrap_or_else(|| format!("track-{:03}", id.source_ordinal));
    let extension = final_path
        .extension()
        .and_then(|value| value.to_str())
        .filter(|value| !value.trim().is_empty())
        .map(|value| value.to_ascii_lowercase())
        .filter(|extension| match format {
            PlannerAudioFormat::Aac | PlannerAudioFormat::Alac => {
                matches!(extension.as_str(), "m4a" | "mp4")
            }
            _ => true,
        })
        .unwrap_or_else(|| default_audio_container_extension(format, None).to_string());

    convert_root.join(format!(
        "{:03}-{}.{}",
        id.source_ordinal,
        file_stem,
        extension
    ))
}

#[cfg(test)]
mod cue_container_extension_tests {
    use super::*;

    #[test]
    fn aac_and_alac_default_to_m4a_container() {
        let mut aac = PathBuf::from("03 - Track");
        append_default_extension(&mut aac, &PlannerAudioFormat::Aac, None);
        assert_eq!(aac.extension().and_then(|value| value.to_str()), Some("m4a"));

        let mut alac = PathBuf::from("03 - Track");
        append_default_extension(&mut alac, &PlannerAudioFormat::Alac, None);
        assert_eq!(alac.extension().and_then(|value| value.to_str()), Some("m4a"));
    }

    #[test]
    fn staged_aac_and_alac_paths_use_m4a_so_ffmpeg_selects_mp4_muxer() {
        let id = TrackId {
            source_ordinal: 3,
            disc_number: None,
            track_number: 3,
        };
        let convert_root = Path::new("convert");

        let aac = staged_audio_path(
            convert_root,
            Path::new("03 - Track.m4a"),
            &id,
            &PlannerAudioFormat::Aac,
        );
        assert_eq!(aac.extension().and_then(|value| value.to_str()), Some("m4a"));

        let alac = staged_audio_path(
            convert_root,
            Path::new("03 - Track.m4a"),
            &id,
            &PlannerAudioFormat::Alac,
        );
        assert_eq!(alac.extension().and_then(|value| value.to_str()), Some("m4a"));
    }

    #[test]
    fn explicit_container_extension_override_is_honored() {
        let mut wav = PathBuf::from("track");
        append_default_extension(&mut wav, &PlannerAudioFormat::Wav, Some("rf64"));
        assert_eq!(wav.extension().and_then(|value| value.to_str()), Some("rf64"));
    }

    #[test]
    fn explicit_raw_aac_container_extension_is_rejected() {
        let err = validate_final_container_extension(&PlannerAudioFormat::Aac, Some("aac"))
            .expect_err("raw AAC is not an implemented AAC container mode");
        assert!(err.contains("raw .aac output is not implemented"), "{err}");
        assert_eq!(default_audio_container_extension(&PlannerAudioFormat::Aac, Some("aac")), "m4a");
    }

    #[test]
    fn explicit_aac_mp4_containers_are_accepted() {
        validate_final_container_extension(&PlannerAudioFormat::Aac, Some("m4a")).unwrap();
        validate_final_container_extension(&PlannerAudioFormat::Aac, Some("mp4")).unwrap();
        validate_final_container_extension(&PlannerAudioFormat::Alac, Some("m4a")).unwrap();
        validate_final_container_extension(&PlannerAudioFormat::Alac, Some("mp4")).unwrap();
    }

    #[test]
    fn template_raw_aac_suffix_is_normalized_to_m4a_default() {
        let mut aac = PathBuf::from("03 - Track.aac");
        append_default_extension(&mut aac, &PlannerAudioFormat::Aac, None);
        assert_eq!(aac.extension().and_then(|value| value.to_str()), Some("m4a"));
    }

    #[test]
    fn staged_path_respects_final_path_extension_override() {
        let id = TrackId {
            source_ordinal: 4,
            disc_number: None,
            track_number: 4,
        };
        let staged = staged_audio_path(
            Path::new("convert"),
            Path::new("04 - Track.rf64"),
            &id,
            &PlannerAudioFormat::Wav,
        );
        assert_eq!(staged.extension().and_then(|value| value.to_str()), Some("rf64"));
    }


    #[test]
    fn staged_aac_path_does_not_inherit_raw_aac_suffix() {
        let id = TrackId {
            source_ordinal: 5,
            disc_number: None,
            track_number: 5,
        };
        let staged = staged_audio_path(
            Path::new("convert"),
            Path::new("05 - Track.aac"),
            &id,
            &PlannerAudioFormat::Aac,
        );
        assert_eq!(staged.extension().and_then(|value| value.to_str()), Some("m4a"));
    }
}

fn command_from_convert_error(err: &ConvertError) -> Vec<CommandRecord> {
    match err {
        ConvertError::Tool(tool_err) => command_from_tool_error(tool_err).into_iter().collect(),
        _ => Vec::new(),
    }
}

fn file_len(path: &Path) -> Option<u64> {
    fs::metadata(path).ok().map(|m| m.len())
}

fn failed_track_record(
    track: &PreparedTrack,
    realized_input: Option<PathBuf>,
    output_file: Option<PathBuf>,
    commands: Vec<CommandRecord>,
    error: String,
) -> TrackRecord {
    TrackRecord {
        track_id: track.id.clone(),
        outcome: TrackOutcome::Err(non_empty_error(error)),
        source_ref: track.source_ref.clone(),
        realized_input,
        output_file,
        commands,
        bytes_in: None,
        bytes_out: None,
        duration: None,
        dsd_dst_stats: None,
    }
}

fn non_empty_error(error: String) -> String {
    if error.trim().is_empty() {
        "unknown error".to_string()
    } else {
        error
    }
}

fn command_from_tool_error(err: &super::errors::ToolRunnerError) -> Option<CommandRecord> {
    match err {
        super::errors::ToolRunnerError::Spawn { command }
        | super::errors::ToolRunnerError::Timeout { command, .. }
        | super::errors::ToolRunnerError::Cancelled { command }
        | super::errors::ToolRunnerError::NonZeroExit { command, .. } => Some(command.clone()),
        super::errors::ToolRunnerError::Io(_) => None,
    }
}

fn push_publish_entry(
    entries: &mut Vec<PublishEntry>,
    seen: &mut BTreeSet<String>,
    output_root: &Path,
    staged_path: PathBuf,
    final_path: PathBuf,
    role: PublishRole,
) -> Result<(), PublishError> {
    let final_path = normalize_path(&final_path);
    if !path_is_under_root(&final_path, output_root) {
        return Err(PublishError::PathOutsideOutputRoot(
            final_path.display().to_string(),
        ));
    }
    let key = normalized_collision_key(&final_path);
    if !seen.insert(key) {
        return Err(PublishError::DestinationExists(
            final_path.display().to_string(),
        ));
    }
    entries.push(PublishEntry {
        staged_path,
        final_path,
        role,
    });
    Ok(())
}

fn validate_publish_album_dir(
    album_dir: &Path,
    output_root: &Path,
    entries: &[PublishEntry],
    per_album_subdir: bool,
) -> Result<PathBuf, PublishError> {
    if album_dir.as_os_str().is_empty() {
        return Err(PublishError::PathOutsideOutputRoot(
            "planned album_dir must not be empty".to_string(),
        ));
    }

    let album_dir = normalize_path(album_dir);
    if !path_is_under_root(&album_dir, output_root) {
        return Err(PublishError::PathOutsideOutputRoot(
            album_dir.display().to_string(),
        ));
    }
    if per_album_subdir && album_dir == output_root {
        return Err(PublishError::PathOutsideOutputRoot(format!(
            "planned album_dir must name an album directory below output_root: {}",
            album_dir.display()
        )));
    }
    if !per_album_subdir && album_dir != output_root {
        return Err(PublishError::PathOutsideOutputRoot(format!(
            "flat output publish must use output_root as album_dir: {}",
            album_dir.display()
        )));
    }

    for entry in entries {
        if is_conversion_log_fragment_role(&entry.role) && path_is_under_root(&entry.final_path, output_root) {
            // Album-batch conversion-log fragments are coordination records, not
            // rendered album payload. They may live in the stable batch workspace
            // under output_root so per-disc album-folder templates do not split
            // completion by rendered root. Ordinary album payload remains bounded
            // by album_dir below.
            continue;
        }
        if !path_is_under_root(&entry.final_path, &album_dir) {
            return Err(PublishError::PathOutsideOutputRoot(format!(
                "publish entry {} is outside album directory {}",
                entry.final_path.display(),
                album_dir.display()
            )));
        }
    }

    Ok(album_dir)
}

fn fragment_dispatcher_album_dir_candidate(
    artifacts: &ArtifactSet,
    req: &PipelineRequest,
    output_root: &Path,
) -> Result<Option<PathBuf>, PublishError> {
    let Some(album_batch) = req.album_batch.as_ref() else {
        return Ok(None);
    };

    let candidate = normalize_path(&album_batch.album_output_dir);
    if candidate.as_os_str().is_empty() || !path_is_under_root(&candidate, output_root) {
        return Err(PublishError::PathOutsideOutputRoot(
            candidate.display().to_string(),
        ));
    }

    if artifact_final_paths_are_under_album_dir(artifacts, &candidate, output_root)? {
        return Ok(Some(candidate));
    }

    if album_batch.album_output_dir_is_planner_resolved() {
        return Err(PublishError::PathOutsideOutputRoot(format!(
            "planner-resolved album_batch.album_output_dir {} does not contain all staged publish entries",
            candidate.display()
        )));
    }

    // A dispatcher-authored provisional directory is useful for
    // pre-materialization fragments, but metadata planning can later move the
    // real album root for folder templates such as `%ARTIST%/%ALBUM%`. When the
    // provisional value no longer contains the staged fragment entries, fall
    // through to the fragment sidecar path instead of guessing from audio paths.
    Ok(None)
}

fn artifact_final_paths_are_under_album_dir(
    artifacts: &ArtifactSet,
    album_dir: &Path,
    output_root: &Path,
) -> Result<bool, PublishError> {
    match &artifacts.audio {
        AudioArtifacts::Tracks(tracks) => {
            for track in tracks {
                if !artifact_final_path_is_under_album_dir(
                    &track.final_path,
                    album_dir,
                    output_root,
                )? {
                    return Ok(false);
                }
            }
        }
        AudioArtifacts::Merged(merged) => {
            if !artifact_final_path_is_under_album_dir(
                &merged.final_path,
                album_dir,
                output_root,
            )? {
                return Ok(false);
            }
        }
    }

    for sidecar in &artifacts.sidecars {
        // Batch coordination fragments deliberately live OUTSIDE the rendered
        // album dir, in <output_root>/.tonepoet-batch/<batch-id>/. They must
        // not fail (or skip) album containment for planner-resolved batches;
        // root-safety for them is enforced where the fragment path is built
        // and again at publish preflight.
        if is_conversion_log_fragment_role(&PublishRole::Sidecar(sidecar.kind.clone())) {
            let normalized = normalize_path(&sidecar.final_path);
            if !path_is_under_root(&normalized, &normalize_path(output_root)) {
                return Err(PublishError::PathOutsideOutputRoot(
                    sidecar.final_path.display().to_string(),
                ));
            }
            continue;
        }
        if !artifact_final_path_is_under_album_dir(&sidecar.final_path, album_dir, output_root)? {
            return Ok(false);
        }
    }

    Ok(true)
}

fn artifact_final_path_is_under_album_dir(
    final_path: &Path,
    album_dir: &Path,
    output_root: &Path,
) -> Result<bool, PublishError> {
    let final_path = normalize_path(final_path);
    if !path_is_under_root(&final_path, output_root) {
        return Err(PublishError::PathOutsideOutputRoot(
            final_path.display().to_string(),
        ));
    }
    Ok(path_is_under_root(&final_path, album_dir))
}

fn path_has_normal_component(path: &Path, needle: &str) -> bool {
    path.components().any(|component| {
        matches!(component, Component::Normal(name) if name == std::ffi::OsStr::new(needle))
    })
}

fn infer_publish_album_dir(
    artifacts: &ArtifactSet,
    output_root: &Path,
    per_album_subdir: bool,
) -> Result<PathBuf, PublishError> {
    let mut common_parent: Option<PathBuf> = None;
    let mut saw_artifact = false;
    let mut saw_fragment = false;

    match &artifacts.audio {
        AudioArtifacts::Tracks(tracks) => {
            for track in tracks {
                saw_artifact = true;
                let mut ignored_fragment_component = false;
                let candidate = publish_album_dir_candidate_from_final_path(
                    &track.final_path,
                    output_root,
                    &mut ignored_fragment_component,
                )?;
                common_parent = Some(match common_parent {
                    Some(existing) => deepest_common_path(&existing, &candidate),
                    None => candidate,
                });
            }
        }
        AudioArtifacts::Merged(merged) => {
            saw_artifact = true;
            let mut ignored_fragment_component = false;
            let candidate = publish_album_dir_candidate_from_final_path(
                &merged.final_path,
                output_root,
                &mut ignored_fragment_component,
            )?;
            common_parent = Some(match common_parent {
                Some(existing) => deepest_common_path(&existing, &candidate),
                None => candidate,
            });
        }
    }

    for sidecar in &artifacts.sidecars {
        saw_artifact = true;
        let mut sidecar_fragment_component = false;
        let candidate = publish_album_dir_candidate_from_final_path(
            &sidecar.final_path,
            output_root,
            &mut sidecar_fragment_component,
        )?;
        if is_conversion_log_fragment_role(&PublishRole::Sidecar(sidecar.kind.clone())) {
            if !sidecar_fragment_component {
                return Err(PublishError::PathOutsideOutputRoot(format!(
                    "conversion-log fragment sidecar is not under {}: {}",
                    CONVERSION_LOG_FRAGMENT_DIR,
                    sidecar.final_path.display()
                )));
            }
            saw_fragment = true;
            if path_has_normal_component(&candidate, CONVERSION_LOG_BATCH_COORDINATION_DIR)
                && common_parent.is_some()
            {
                // Stable batch-coordination fragments are not rendered album
                // payload and must not pull an audio publish plan's album_dir up
                // to output_root. Fragment-only plans still use the coordination
                // root as their publish directory.
                continue;
            }
        }
        common_parent = Some(match common_parent {
            Some(existing) => deepest_common_path(&existing, &candidate),
            None => candidate,
        });
    }

    if !saw_artifact {
        return Err(PublishError::StagingMissing);
    }
    if !saw_fragment {
        return Err(PublishError::PathOutsideOutputRoot(
            "fragment publish album_dir inference requires a conversion-log fragment sidecar"
                .to_string(),
        ));
    }

    let Some(album_dir) = common_parent else {
        return Err(PublishError::StagingMissing);
    };
    if !path_is_under_root(&album_dir, output_root) {
        return Err(PublishError::PathOutsideOutputRoot(format!(
            "fragment publish entries do not share an album directory under output_root: {}",
            output_root.display()
        )));
    }
    if per_album_subdir && album_dir == output_root {
        return Err(PublishError::PathOutsideOutputRoot(format!(
            "fragment publish entries do not identify an album directory below output_root: {}",
            output_root.display()
        )));
    }
    if !per_album_subdir && album_dir != output_root {
        return Err(PublishError::PathOutsideOutputRoot(format!(
            "flat fragment publish must resolve to output_root: {}",
            album_dir.display()
        )));
    }

    Ok(album_dir)
}

fn publish_album_dir_candidate_from_final_path(
    final_path: &Path,
    output_root: &Path,
    saw_fragment: &mut bool,
) -> Result<PathBuf, PublishError> {
    let final_path = normalize_path(final_path);
    if !path_is_under_root(&final_path, output_root) {
        return Err(PublishError::PathOutsideOutputRoot(
            final_path.display().to_string(),
        ));
    }

    let mut before_fragment_dir = PathBuf::new();
    for component in final_path.components() {
        if matches!(
            component,
            Component::Normal(name)
                if name == std::ffi::OsStr::new(CONVERSION_LOG_FRAGMENT_DIR)
        ) {
            *saw_fragment = true;
            if before_fragment_dir.as_os_str().is_empty() {
                return Err(PublishError::PathOutsideOutputRoot(format!(
                    "conversion-log fragment path has no album directory: {}",
                    final_path.display()
                )));
            }
            return Ok(before_fragment_dir);
        }
        before_fragment_dir.push(component.as_os_str());
    }

    final_path.parent().map(normalize_path).ok_or_else(|| {
        PublishError::PathOutsideOutputRoot(format!(
            "publish artifact has no parent directory below output_root: {}",
            final_path.display()
        ))
    })
}

fn deepest_common_path(left: &Path, right: &Path) -> PathBuf {
    let mut common = PathBuf::new();
    for (left_component, right_component) in left.components().zip(right.components()) {
        if left_component == right_component {
            match left_component {
                Component::Prefix(prefix) => common.push(prefix.as_os_str()),
                Component::RootDir => common.push(left_component.as_os_str()),
                Component::CurDir => {}
                Component::ParentDir | Component::Normal(_) => {
                    common.push(left_component.as_os_str())
                }
            }
        } else {
            break;
        }
    }
    common
}

#[derive(Debug, serde::Deserialize, serde::Serialize)]
struct PublishRecoveryMarker {
    version: u8,
    album_dir_name: String,
    backup_dir_name: String,
}

fn write_publish_marker(marker_path: &Path, backup_dir: &Path) -> Result<(), PublishError> {
    let album_dir = marker_path
        .file_name()
        .and_then(|name| name.to_str())
        .and_then(|name| name.strip_prefix('.'))
        .and_then(|name| name.strip_suffix(".publish-in-progress"))
        .ok_or_else(|| {
            PublishError::BackupFailed(format!(
                "could not derive album name from publish marker {}",
                marker_path.display()
            ))
        })?;
    let backup_dir_name = backup_dir
        .file_name()
        .and_then(|name| name.to_str())
        .ok_or_else(|| {
            PublishError::BackupFailed(format!(
                "backup directory has no valid file name: {}",
                backup_dir.display()
            ))
        })?
        .to_string();
    let marker = PublishRecoveryMarker {
        version: 1,
        album_dir_name: album_dir.to_string(),
        backup_dir_name,
    };
    let bytes = serde_json::to_vec_pretty(&marker).map_err(|err| {
        PublishError::BackupFailed(format!(
            "could not serialize publish recovery marker {}: {err}",
            marker_path.display()
        ))
    })?;
    write_bytes_atomically(marker_path, &bytes).map_err(|err| {
        PublishError::BackupFailed(format!(
            "could not install publish recovery marker {}: {err}",
            marker_path.display()
        ))
    })?;
    Ok(())
}

fn repair_interrupted_publish(album_dir: &Path, marker_path: &Path) -> Result<(), PublishError> {
    if !marker_path.exists() {
        return Ok(());
    }

    if album_dir.exists() {
        // A final album already exists. Either the previous publish succeeded before
        // marker cleanup, or it failed before the backup move. In both cases, keep
        // any backup directory in place and clear the stale marker.
        let _ = fs::remove_file(marker_path);
        sync_parent_dir_best_effort(marker_path);
        return Ok(());
    }

    let marker_text = fs::read_to_string(marker_path).map_err(PublishError::io_at("reading recovery marker", marker_path))?;
    let backup_dir = backup_dir_from_marker(album_dir, marker_path, &marker_text)?;

    if backup_dir.exists() {
        fs::rename(&backup_dir, album_dir).map_err(|err| {
            PublishError::RollbackFailed(format!(
                "could not repair interrupted publish by restoring {} -> {}: {err}",
                backup_dir.display(),
                album_dir.display()
            ))
        })?;
        let _ = fs::remove_file(marker_path);
        sync_parent_dir_best_effort(album_dir);
        return Ok(());
    }

    Err(PublishError::RollbackFailed(format!(
        "publish recovery marker {} was present but validated backup {} was missing",
        marker_path.display(),
        backup_dir.display()
    )))
}

fn repair_interrupted_incremental_publish(
    album_dir: &Path,
    marker_path: &Path,
) -> Result<(), PublishError> {
    if !marker_path.exists() {
        return Ok(());
    }

    let marker_text = fs::read_to_string(marker_path).map_err(PublishError::io_at("reading recovery marker", marker_path))?;
    let marker = serde_json::from_str::<IncrementalPublishRecoveryMarker>(&marker_text).map_err(|err| {
        PublishError::RollbackFailed(format!(
            "could not parse incremental publish recovery marker {}: {err}",
            marker_path.display()
        ))
    })?;
    let temp_dir = validate_incremental_marker(album_dir, marker_path, &marker)?;

    for action in marker.actions.iter().rev() {
        match action {
            IncrementalRecoveryActionMarker::RemoveCreatedFile { final_rel } => {
                let final_rel = marker_relative_path(marker_path, final_rel)?;
                let final_path = album_dir.join(final_rel);
                remove_file_if_exists(&final_path).map_err(|err| {
                    PublishError::RollbackFailed(format!(
                        "could not remove incomplete incremental publish output {}: {err}",
                        final_path.display()
                    ))
                })?;
                sync_parent_dir_best_effort(&final_path);
            }
            IncrementalRecoveryActionMarker::RestoreOriginalFile {
                final_rel,
                backup_rel,
            } => {
                let final_rel = marker_relative_path(marker_path, final_rel)?;
                let backup_rel = marker_relative_path(marker_path, backup_rel)?;
                let final_path = album_dir.join(final_rel);
                let backup_path = temp_dir.join(backup_rel);
                if !backup_path.exists() {
                    return Err(PublishError::RollbackFailed(format!(
                        "incremental publish recovery marker {} requires missing backup {}",
                        marker_path.display(),
                        backup_path.display()
                    )));
                }
                restore_incremental_backup(&backup_path, &final_path).map_err(|err| {
                    PublishError::RollbackFailed(format!(
                        "could not restore {} from incremental backup {}: {err}",
                        final_path.display(),
                        backup_path.display()
                    ))
                })?;
                sync_parent_dir_best_effort(&final_path);
            }
        }
    }

    if temp_dir.exists() {
        if temp_dir.is_dir() {
            fs::remove_dir_all(&temp_dir).map_err(PublishError::io_at("removing recovery temp dir", &temp_dir))?;
        } else {
            fs::remove_file(&temp_dir).map_err(PublishError::io_at("removing recovery temp file", &temp_dir))?;
        }
    }
    remove_file_if_exists(marker_path).map_err(PublishError::io_at("removing recovery marker", marker_path))?;
    sync_parent_dir_best_effort(marker_path);
    Ok(())
}

fn validate_incremental_marker(
    album_dir: &Path,
    marker_path: &Path,
    marker: &IncrementalPublishRecoveryMarker,
) -> Result<PathBuf, PublishError> {
    if marker.version != 1 {
        return Err(PublishError::RollbackFailed(format!(
            "unsupported incremental publish recovery marker version {} in {}",
            marker.version,
            marker_path.display()
        )));
    }

    let expected_album = album_dir_marker_name(album_dir)?;
    if marker.album_dir_name != expected_album {
        return Err(PublishError::RollbackFailed(format!(
            "incremental publish recovery marker {} targets album {}, not {}",
            marker_path.display(),
            marker.album_dir_name,
            expected_album
        )));
    }

    let temp_name = PathBuf::from(&marker.temp_dir_name);
    reject_escaping_path(&temp_name).map_err(|err| {
        PublishError::RollbackFailed(format!(
            "incremental publish recovery marker {} contains invalid temp name {}: {err}",
            marker_path.display(),
            marker.temp_dir_name
        ))
    })?;
    if temp_name.components().count() != 1 {
        return Err(PublishError::RollbackFailed(format!(
            "incremental publish recovery marker {} contains non-leaf temp name {}",
            marker_path.display(),
            marker.temp_dir_name
        )));
    }

    let expected_prefix = format!(".{expected_album}.tmp-");
    if !marker.temp_dir_name.starts_with(&expected_prefix) {
        return Err(PublishError::RollbackFailed(format!(
            "incremental publish recovery marker {} points at non-matching temp directory {}",
            marker_path.display(),
            marker.temp_dir_name
        )));
    }

    Ok(parent_dir_or_current(album_dir).join(temp_name))
}

fn backup_dir_from_marker(
    album_dir: &Path,
    marker_path: &Path,
    marker_text: &str,
) -> Result<PathBuf, PublishError> {
    if let Ok(marker) = serde_json::from_str::<PublishRecoveryMarker>(marker_text) {
        return validate_structured_marker(album_dir, marker_path, marker);
    }

    // v9 wrote the backup path as a newline-terminated string. Accept that legacy
    // marker only if it validates as a backup directory for this exact album.
    let legacy = PathBuf::from(marker_text.trim());
    validate_backup_dir(album_dir, marker_path, legacy)
}

fn validate_structured_marker(
    album_dir: &Path,
    marker_path: &Path,
    marker: PublishRecoveryMarker,
) -> Result<PathBuf, PublishError> {
    if marker.version != 1 {
        return Err(PublishError::RollbackFailed(format!(
            "unsupported publish recovery marker version {} in {}",
            marker.version,
            marker_path.display()
        )));
    }

    let expected_album = album_dir_marker_name(album_dir)?;
    if marker.album_dir_name != expected_album {
        return Err(PublishError::RollbackFailed(format!(
            "publish recovery marker {} targets album {}, not {}",
            marker_path.display(),
            marker.album_dir_name,
            expected_album
        )));
    }

    let backup_name = PathBuf::from(&marker.backup_dir_name);
    reject_escaping_path(&backup_name).map_err(PublishError::PathOutsideOutputRoot)?;
    if backup_name.components().count() != 1 {
        return Err(PublishError::RollbackFailed(format!(
            "publish recovery marker {} contains non-leaf backup name {}",
            marker_path.display(),
            marker.backup_dir_name
        )));
    }

    let parent = parent_dir_or_current(album_dir);
    validate_backup_dir(album_dir, marker_path, parent.join(backup_name))
}

fn validate_backup_dir(
    album_dir: &Path,
    marker_path: &Path,
    backup_dir: PathBuf,
) -> Result<PathBuf, PublishError> {
    let parent = normalize_path(parent_dir_or_current(album_dir));
    let backup_parent = normalize_path(parent_dir_or_current(&backup_dir));
    if backup_parent != parent {
        return Err(PublishError::RollbackFailed(format!(
            "publish recovery marker {} points outside album parent: {}",
            marker_path.display(),
            backup_dir.display()
        )));
    }

    let backup_name = backup_dir
        .file_name()
        .and_then(|name| name.to_str())
        .ok_or_else(|| {
            PublishError::RollbackFailed(format!(
                "publish recovery marker {} contains invalid backup path {}",
                marker_path.display(),
                backup_dir.display()
            ))
        })?;
    let expected_prefix = backup_dir_prefix(album_dir)?;
    if !backup_name.starts_with(&expected_prefix) {
        return Err(PublishError::RollbackFailed(format!(
            "publish recovery marker {} points at non-matching backup {}",
            marker_path.display(),
            backup_dir.display()
        )));
    }

    Ok(backup_dir)
}

fn album_dir_marker_name(album_dir: &Path) -> Result<String, PublishError> {
    album_dir
        .file_name()
        .and_then(|name| name.to_str())
        .map(sanitize_component)
        .ok_or_else(|| {
            PublishError::BackupFailed(format!(
                "album directory has no valid file name: {}",
                album_dir.display()
            ))
        })
}

fn backup_dir_prefix(album_dir: &Path) -> Result<String, PublishError> {
    Ok(format!(".{}.backup-", album_dir_marker_name(album_dir)?))
}

fn cleanup_orphan_publish_temps(parent: &Path, album_name: &str) -> Result<(), PublishError> {
    let prefix = format!(".{album_name}.tmp-");
    let entries = match fs::read_dir(parent) {
        Ok(entries) => entries,
        Err(err) if err.kind() == io::ErrorKind::NotFound => return Ok(()),
        Err(err) => return Err(PublishError::Io(err)),
    };

    for entry in entries {
        let entry = entry.map_err(PublishError::io_at("listing publish parent dir", parent))?;
        let name = entry.file_name();
        let Some(name) = name.to_str() else {
            continue;
        };
        if !name.starts_with(&prefix) {
            continue;
        }
        let path = entry.path();
        if path.is_dir() {
            fs::remove_dir_all(&path).map_err(PublishError::io_at("removing stale publish artifact dir", &path))?;
        } else {
            fs::remove_file(&path).map_err(PublishError::io_at("removing stale publish artifact", &path))?;
        }
    }
    Ok(())
}

fn cleanup_publish_temp<T>(temp_dir: &Path, err: PublishError) -> Result<T, PublishError> {
    let _ = fs::remove_dir_all(temp_dir);
    Err(err)
}

fn copy_or_rename_into_publish_temp(
    src: &Path,
    dst: &Path,
    same_filesystem_required: bool,
) -> Result<(), PublishError> {
    copy_or_rename_into_publish_temp_with(src, dst, same_filesystem_required, |from, to| fs::rename(from, to))
}

fn copy_or_rename_into_publish_temp_with<F>(
    src: &Path,
    dst: &Path,
    same_filesystem_required: bool,
    rename: F,
) -> Result<(), PublishError>
where
    F: FnOnce(&Path, &Path) -> io::Result<()>,
{
    match rename(src, dst) {
        Ok(()) => Ok(()),
        Err(err) if is_cross_device_error(&err) => {
            if same_filesystem_required {
                return Err(PublishError::CrossDeviceCopy(format!(
                    "{} -> {}: {err}",
                    src.display(),
                    dst.display()
                )));
            }
            copy_across_devices(src, dst).map_err(|copy_err| {
                PublishError::CrossDeviceCopy(format!(
                    "{} -> {}: {copy_err}",
                    src.display(),
                    dst.display()
                ))
            })
        }
        Err(err) => Err(PublishError::Io(err)),
    }
}

fn copy_across_devices(src: &Path, dst: &Path) -> Result<(), io::Error> {
    fs::copy(src, dst)?;
    let file = fs::OpenOptions::new().read(true).write(true).open(dst)?;
    file.sync_all()?;
    sync_parent_dir_best_effort(dst);
    Ok(())
}

fn write_bytes_atomically(path: &Path, bytes: &[u8]) -> io::Result<()> {
    use std::io::Write;

    let parent = parent_dir_or_current(path);
    fs::create_dir_all(parent)?;
    let mut temp = tempfile::NamedTempFile::new_in(parent)?;
    temp.write_all(bytes)?;
    temp.as_file().sync_all()?;
    temp.persist(path).map_err(|err| err.error)?;
    sync_parent_dir_best_effort(path);
    Ok(())
}

/// Remove internal staging artifacts after a durable successful publish.
///
/// This is intentionally success-only. Failed or cancelled jobs keep their
/// staging roots for diagnostics/retry unless a higher-level processor cleanup
/// policy explicitly decides otherwise. We still remove unheld lock files from
/// the staging parent so successful runs do not leave `.tonepoet-staging/`
/// visible solely because of a stale lock from an older crashed run.
fn cleanup_successful_staging(staging: StagingDir) {
    let root = staging.root.clone();
    let parent = root.parent().map(|path| path.to_path_buf());
    drop(staging);

    if let Err(err) = fs::remove_dir_all(&root) {
        if err.kind() != io::ErrorKind::NotFound {
            log::warn!("could not remove successful staging directory {}: {err}", root.display());
        }
    }

    if let Some(parent) = parent {
        cleanup_empty_staging_parent_best_effort(&parent);
    }
}

fn cleanup_empty_staging_parent_best_effort(parent: &Path) {
    if parent.file_name().and_then(|name| name.to_str()) != Some(STAGING_PARENT_NAME) {
        return;
    }
    cleanup_unheld_staging_parent_locks(parent);
    match fs::remove_dir(parent) {
        Ok(()) => sync_parent_dir_best_effort(parent),
        Err(err) if err.kind() == io::ErrorKind::NotFound => {}
        Err(err) => {
            let has_entries = parent
                .read_dir()
                .map(|mut entries| entries.next().is_some())
                .unwrap_or(false);
            if !has_entries {
                log::warn!(
                    "could not remove empty staging parent {}: {err}",
                    parent.display()
                );
            }
        }
    }
}


fn cleanup_unheld_staging_parent_locks(parent: &Path) {
    let Ok(entries) = fs::read_dir(parent) else {
        return;
    };
    for entry in entries.flatten() {
        let name = entry.file_name();
        let Some(name) = name.to_str() else {
            continue;
        };
        if name.ends_with(".run.lock") {
            remove_unheld_lock_file_best_effort(&entry.path());
        }
    }
}

fn cleanup_stale_publish_lock_artifacts(parent: &Path, album_name: &str) {
    let Ok(entries) = fs::read_dir(parent) else {
        return;
    };
    let hidden_current = format!(".{album_name}.lock");
    let legacy_current = format!("{album_name}.lock");

    for entry in entries.flatten() {
        let name = entry.file_name();
        let Some(name) = name.to_str() else {
            continue;
        };
        if is_stale_publish_lock_candidate(name, &hidden_current, &legacy_current) {
            remove_unheld_lock_file_best_effort(&entry.path());
        }
    }
}

fn is_stale_publish_lock_candidate(name: &str, hidden_current: &str, legacy_current: &str) -> bool {
    if name == hidden_current || name == legacy_current {
        return true;
    }

    // Previous broken conditional-template renders could leave orphan album
    // locks such as `.Album [FLAC] {}.lock`. Remove only if the file is not
    // currently locked, and only for the known broken conditional artifact.
    name.ends_with(".lock") && name.contains("{}")
}

fn remove_unheld_lock_file_best_effort(path: &Path) {
    let Ok(metadata) = fs::metadata(path) else {
        return;
    };
    if !metadata.is_file() {
        return;
    }

    let Ok(file) = fs::OpenOptions::new().read(true).write(true).open(path) else {
        return;
    };
    match file.try_lock_exclusive() {
        Ok(()) => {
            let _ = file.unlock();
            drop(file);
            remove_lock_path_best_effort(path);
        }
        Err(err) if is_lock_contention(&err) => {}
        Err(err) => {
            log::debug!("could not check stale lock {}: {err}", path.display());
        }
    }
}

fn acquire_publish_lock(album_dir: &Path) -> Result<AlbumPublishLock, PublishError> {
    let hidden_lock_path = album_lock_path(album_dir);
    let legacy_lock_path = legacy_album_lock_path(album_dir);

    // The album publish lock uses a stable hidden path only while publish is
    // active. The path is removed when the guard drops so successful conversions
    // do not leave user-visible internal artifacts behind.
    let hidden = acquire_blocking_file_lock(&hidden_lock_path, true).map_err(PublishError::Io)?;
    remove_lock_path_best_effort(&legacy_lock_path);

    Ok(AlbumPublishLock { hidden: Some(hidden) })
}

fn acquire_run_lock(
    staging_parent: &Path,
    job_id: &str,
    item_id: &str,
) -> Result<FileLock, MaterializeError> {
    let lock_path = staging_parent.join(run_lock_file_name(job_id, item_id));
    acquire_file_lock(&lock_path, "pipeline item is already running").map_err(|err| match err {
        LockAcquireError::Busy(message) => MaterializeError::Parse(message),
        LockAcquireError::Io(err) => MaterializeError::Io(err),
    })
}

fn run_lock_file_name(job_id: &str, item_id: &str) -> String {
    format!(
        ".{}-{}.run.lock",
        sanitize_component(job_id),
        sanitize_component(item_id)
    )
}

fn mark_staging_root_best_effort(staging_root: &Path, req: &PipelineRequest) {
    let lock_file_name = run_lock_file_name(&req.job_id, &req.item_id);
    if let Err(err) = write_staging_owner_marker(staging_root, &lock_file_name) {
        log::warn!(
            "could not write scratch staging owner marker for {} at {}: {err}",
            req.item_id,
            staging_root.display()
        );
    }
}

/// True when `held` (the fstat of a locked file handle) is the same filesystem
/// object as whatever currently sits at the lock path.
///
/// Lock files here are removed on drop to avoid leaving artifacts, which makes
/// the classic unlink race possible: a waiter blocked on an inode whose path
/// was unlinked acquires a lock nobody else can see, while a newcomer creates
/// and locks a fresh file at the same path — two "holders" at once. Album
/// publishes then delete each other's live `.tmp-` directories. A lock is only
/// authoritative if, after acquisition, the handle still is the file at the
/// path.
#[cfg(unix)]
fn lock_handle_is_current(held: &fs::Metadata, lock_path: &Path) -> bool {
    use std::os::unix::fs::MetadataExt;
    match fs::symlink_metadata(lock_path) {
        Ok(current) => current.dev() == held.dev() && current.ino() == held.ino(),
        Err(_) => false,
    }
}

#[cfg(not(unix))]
fn lock_handle_is_current(_held: &fs::Metadata, lock_path: &Path) -> bool {
    // Without stable file identity, fall back to path existence. The unlink
    // race window is then only narrowed, not closed; supported targets are
    // unix.
    lock_path.exists()
}

fn acquire_file_lock(lock_path: &Path, busy_message: &str) -> Result<FileLock, LockAcquireError> {
    let parent = parent_dir_or_current(lock_path);
    fs::create_dir_all(parent).map_err(LockAcquireError::Io)?;
    loop {
        let file = fs::OpenOptions::new()
            .read(true)
            .write(true)
            .create(true)
            .open(lock_path)
            .map_err(LockAcquireError::Io)?;

        match file.try_lock_exclusive() {
            Ok(()) => {
                let held = file.metadata().map_err(LockAcquireError::Io)?;
                if !lock_handle_is_current(&held, lock_path) {
                    // The path was unlinked or replaced while this handle was
                    // opened; a lock on an orphaned inode is not a lock.
                    drop(file);
                    continue;
                }
                return Ok(FileLock {
                    file: Some(file),
                    path: lock_path.to_path_buf(),
                    remove_on_drop: true,
                });
            }
            Err(err) if is_lock_contention(&err) => {
                return Err(LockAcquireError::Busy(busy_message.to_string()))
            }
            Err(err) => return Err(LockAcquireError::Io(err)),
        }
    }
}

fn acquire_blocking_file_lock(lock_path: &Path, remove_on_drop: bool) -> io::Result<FileLock> {
    let parent = parent_dir_or_current(lock_path);
    fs::create_dir_all(parent)?;
    loop {
        let file = fs::OpenOptions::new()
            .read(true)
            .write(true)
            .create(true)
            .open(lock_path)?;

        file.lock_exclusive()?;
        let held = file.metadata()?;
        if !lock_handle_is_current(&held, lock_path) {
            // The previous holder removed the lock file on drop while this
            // waiter was blocked on the now-orphaned inode, or a stale-lock
            // sweep unlinked the path between open and flock. Only a lock on
            // the file currently at lock_path grants exclusion; retry on it.
            drop(file);
            continue;
        }
        return Ok(FileLock {
            file: Some(file),
            path: lock_path.to_path_buf(),
            remove_on_drop,
        });
    }
}

fn album_lock_path(album_dir: &Path) -> PathBuf {
    match album_dir.file_name().and_then(|name| name.to_str()) {
        Some(name) => album_dir.with_file_name(format!(".{name}.lock")),
        None => PathBuf::from(format!(".{}.lock", album_dir.display())),
    }
}

fn legacy_album_lock_path(album_dir: &Path) -> PathBuf {
    match album_dir.file_name().and_then(|name| name.to_str()) {
        Some(name) => album_dir.with_file_name(format!("{name}.lock")),
        None => PathBuf::from(format!("{}.lock", album_dir.display())),
    }
}

fn is_lock_contention(err: &io::Error) -> bool {
    if err.kind() == io::ErrorKind::WouldBlock {
        return true;
    }

    #[cfg(unix)]
    {
        return matches!(err.raw_os_error(), Some(11) | Some(35));
    }

    #[cfg(windows)]
    {
        return err.raw_os_error() == Some(33);
    }

    #[cfg(not(any(unix, windows)))]
    {
        let _ = err;
        false
    }
}

enum LockAcquireError {
    Busy(String),
    Io(io::Error),
}

struct FileLock {
    file: Option<fs::File>,
    path: PathBuf,
    remove_on_drop: bool,
}

struct AlbumPublishLock {
    hidden: Option<FileLock>,
}

impl Drop for AlbumPublishLock {
    fn drop(&mut self) {
        if let Some(hidden) = self.hidden.take() {
            drop(hidden);
        }
    }
}

impl Drop for FileLock {
    fn drop(&mut self) {
        let cleanup_parent = self
            .remove_on_drop
            .then(|| self.path.parent().map(|path| path.to_path_buf()))
            .flatten();
        // Unlink while the exclusive flock is still held. Releasing first
        // opens a window where a waiter blocked on this inode acquires the
        // lock and passes the path-identity check — and then loses its lock
        // path when this (former) holder unlinks it, letting a third party
        // create and lock a fresh file at the same path. Unlink-then-release
        // guarantees late waiters wake on an orphaned inode, fail the
        // identity re-check, and retry on the current file.
        if self.remove_on_drop {
            remove_lock_path_best_effort(&self.path);
        }
        if let Some(file) = self.file.take() {
            let _ = file.unlock();
            drop(file);
        }
        if let Some(parent) = cleanup_parent {
            cleanup_empty_staging_parent_best_effort(&parent);
        }
    }
}

fn remove_lock_path_best_effort(path: &Path) {
    match fs::remove_file(path) {
        Ok(()) => sync_parent_dir_best_effort(path),
        Err(err) if err.kind() == io::ErrorKind::NotFound => {}
        Err(_) => {}
    }
}

fn sync_parent_dir_best_effort(path: &Path) {
    let parent = parent_dir_or_current(path);
    let Ok(dir) = fs::File::open(parent) else {
        return;
    };
    let _ = dir.sync_all();
}

fn is_cross_device_error(err: &io::Error) -> bool {
    #[cfg(unix)]
    {
        err.raw_os_error() == Some(18)
    }
    #[cfg(windows)]
    {
        err.raw_os_error() == Some(17)
    }
    #[cfg(not(any(unix, windows)))]
    {
        let _ = err;
        false
    }
}

fn unique_path(parent: &Path, prefix: &str) -> PathBuf {
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos();
    for attempt in 0_u32..1000 {
        let candidate = parent.join(format!("{prefix}-{nanos}-{attempt}"));
        if !candidate.exists() {
            return candidate;
        }
    }
    parent.join(format!("{prefix}-{nanos}-fallback"))
}

#[derive(Debug)]
struct StagingParentSelection {
    parent: PathBuf,
    scratch_reservation: Option<ScratchReservation>,
}

impl StagingParentSelection {
    fn disk(parent: PathBuf) -> Self {
        Self {
            parent,
            scratch_reservation: None,
        }
    }

    fn scratch(parent: PathBuf, scratch_reservation: ScratchReservation) -> Self {
        Self {
            parent,
            scratch_reservation: Some(scratch_reservation),
        }
    }

    fn is_scratch(&self) -> bool {
        self.scratch_reservation.is_some()
    }

    fn into_staging_dir(self, staging_root: PathBuf, job_id: String) -> StagingDir {
        match self.scratch_reservation {
            Some(reservation) => {
                StagingDir::new_with_scratch_reservation(staging_root, job_id, reservation)
            }
            None => StagingDir::new(staging_root, job_id),
        }
    }
}

struct MaterializationAttempt {
    staging: StagingDir,
    _run_lock: FileLock,
    used_scratch: bool,
}

impl MaterializationAttempt {
    fn into_parts(self) -> (FileLock, StagingDir) {
        (self._run_lock, self.staging)
    }
}

enum MaterializationRun {
    Attempted {
        attempt: MaterializationAttempt,
        result: Result<PreparedSource, MaterializeError>,
    },
    FailedBeforeAttempt {
        error: MaterializeError,
        context: &'static str,
    },
}

async fn materialize_with_optional_disk_retry(
    req: &PipelineRequest,
    initial_selection: StagingParentSelection,
    runner: &dyn ToolRunner,
    reporter: Option<&dyn PipelineReporter>,
    tool_paths: &HashMap<String, PathBuf>,
    cancel: &CancellationToken,
) -> MaterializationRun {
    let initial_was_scratch = initial_selection.is_scratch();
    let mut attempt = match prepare_materialization_attempt(req, initial_selection) {
        Ok(attempt) => attempt,
        Err(err) if initial_was_scratch
            && !cancel.is_cancelled()
            && materialize_error_is_storage_exhaustion(&err) => {
            let disk_parent = disk_staging_parent_for(req);
            log::warn!(
                "scratch retrying on disk: job_id={}, item_id={}, disk_staging_path={}, original_error={}",
                req.job_id,
                req.item_id,
                disk_parent.display(),
                err,
            );
            match prepare_disk_materialization_attempt(req) {
                Ok(attempt) => attempt,
                Err(disk_err) => {
                    return MaterializationRun::FailedBeforeAttempt {
                        error: MaterializeError::Parse(format!(
                            "scratch staging setup exhausted storage ({err}); disk fallback setup also failed: {disk_err}"
                        )),
                        context: "scratch staging setup exhausted storage and disk fallback setup failed",
                    };
                }
            }
        }
        Err(err) => {
            return MaterializationRun::FailedBeforeAttempt {
                error: err,
                context: "staging preparation failed",
            };
        }
    };

    let mut result = materialize_source_once(
        req,
        &attempt.staging,
        runner,
        reporter,
        tool_paths,
        cancel,
    )
    .await;

    if attempt.used_scratch {
        let should_retry = !cancel.is_cancelled()
            && result
                .as_ref()
                .err()
                .map(materialize_error_is_storage_exhaustion)
                .unwrap_or(false);

        if should_retry {
            let scratch_error = result
                .as_ref()
                .err()
                .map(ToString::to_string)
                .unwrap_or_else(|| "unknown scratch storage exhaustion".to_string());
            let disk_parent = disk_staging_parent_for(req);
            log::warn!(
                "scratch retrying on disk: job_id={}, item_id={}, disk_staging_path={}, original_error={}",
                req.job_id,
                req.item_id,
                disk_parent.display(),
                scratch_error,
            );

            drop(attempt);
            attempt = match prepare_disk_materialization_attempt(req) {
                Ok(disk_attempt) => disk_attempt,
                Err(disk_err) => {
                    return MaterializationRun::FailedBeforeAttempt {
                        error: MaterializeError::Parse(format!(
                            "scratch materialization exhausted storage ({scratch_error}); disk fallback setup failed: {disk_err}"
                        )),
                        context: "scratch materialization exhausted storage and disk fallback setup failed",
                    };
                }
            };

            result = materialize_source_once(
                req,
                &attempt.staging,
                runner,
                reporter,
                tool_paths,
                cancel,
            )
            .await;

            match &result {
                Ok(_) => log::info!(
                    "disk fallback materialization succeeded for item {} after scratch storage exhaustion",
                    req.item_id
                ),
                Err(err) => log::warn!(
                    "disk fallback materialization also failed for item {} after scratch storage exhaustion: {}",
                    req.item_id,
                    err
                ),
            }
        } else if let Err(err) = &result {
            log::debug!(
                "scratch materialization for item {} failed without storage-exhaustion classification; not retrying on disk: {}",
                req.item_id,
                err
            );
        }
    }

    MaterializationRun::Attempted { attempt, result }
}

#[cfg(test)]
fn materialize_with_optional_disk_retry_for_test<F>(
    req: &PipelineRequest,
    initial_selection: StagingParentSelection,
    cancel: &CancellationToken,
    mut materialize_once: F,
) -> MaterializationRun
where
    F: FnMut(&StagingDir) -> Result<PreparedSource, MaterializeError>,
{
    let initial_was_scratch = initial_selection.is_scratch();
    let mut attempt = match prepare_materialization_attempt(req, initial_selection) {
        Ok(attempt) => attempt,
        Err(err) if initial_was_scratch
            && !cancel.is_cancelled()
            && materialize_error_is_storage_exhaustion(&err) => {
            let disk_parent = disk_staging_parent_for(req);
            log::warn!(
                "scratch retrying on disk: job_id={}, item_id={}, disk_staging_path={}, original_error={}",
                req.job_id,
                req.item_id,
                disk_parent.display(),
                err,
            );
            match prepare_disk_materialization_attempt(req) {
                Ok(attempt) => attempt,
                Err(disk_err) => {
                    return MaterializationRun::FailedBeforeAttempt {
                        error: MaterializeError::Parse(format!(
                            "scratch staging setup exhausted storage ({err}); disk fallback setup also failed: {disk_err}"
                        )),
                        context: "scratch staging setup exhausted storage and disk fallback setup failed",
                    };
                }
            }
        }
        Err(err) => {
            return MaterializationRun::FailedBeforeAttempt {
                error: err,
                context: "staging preparation failed",
            };
        }
    };

    let mut result = materialize_once(&attempt.staging);

    if attempt.used_scratch {
        let should_retry = !cancel.is_cancelled()
            && result
                .as_ref()
                .err()
                .map(materialize_error_is_storage_exhaustion)
                .unwrap_or(false);

        if should_retry {
            let scratch_error = result
                .as_ref()
                .err()
                .map(ToString::to_string)
                .unwrap_or_else(|| "unknown scratch storage exhaustion".to_string());
            let disk_parent = disk_staging_parent_for(req);
            log::warn!(
                "scratch retrying on disk: job_id={}, item_id={}, disk_staging_path={}, original_error={}",
                req.job_id,
                req.item_id,
                disk_parent.display(),
                scratch_error,
            );

            drop(attempt);
            attempt = match prepare_disk_materialization_attempt(req) {
                Ok(disk_attempt) => disk_attempt,
                Err(disk_err) => {
                    return MaterializationRun::FailedBeforeAttempt {
                        error: MaterializeError::Parse(format!(
                            "scratch materialization exhausted storage ({scratch_error}); disk fallback setup failed: {disk_err}"
                        )),
                        context: "scratch materialization exhausted storage and disk fallback setup failed",
                    };
                }
            };

            result = materialize_once(&attempt.staging);
        }
    }

    MaterializationRun::Attempted { attempt, result }
}

async fn materialize_source_once(
    req: &PipelineRequest,
    staging: &StagingDir,
    runner: &dyn ToolRunner,
    reporter: Option<&dyn PipelineReporter>,
    tool_paths: &HashMap<String, PathBuf>,
    cancel: &CancellationToken,
) -> Result<PreparedSource, MaterializeError> {
    match detect_source_kind(req) {
        Ok(kind) => match materializer_for(kind) {
            Ok(materializer) => {
                materializer
                    .materialize(req, staging, runner, reporter, tool_paths, cancel)
                    .await
            }
            Err(err) => Err(MaterializeError::Parse(err.to_string())),
        },
        Err(err) => Err(MaterializeError::Parse(err.to_string())),
    }
}

fn prepare_disk_materialization_attempt(req: &PipelineRequest) -> Result<MaterializationAttempt, MaterializeError> {
    prepare_materialization_attempt(req, StagingParentSelection::disk(disk_staging_parent_for(req)))
}

fn prepare_materialization_attempt(
    req: &PipelineRequest,
    selection: StagingParentSelection,
) -> Result<MaterializationAttempt, MaterializeError> {
    let staging_parent = selection.parent.clone();
    fs::create_dir_all(&staging_parent).map_err(MaterializeError::Io)?;
    let run_lock = acquire_run_lock(&staging_parent, &req.job_id, &req.item_id)?;
    let staging_root = staging_parent.join(format!(
        "{}-{}",
        sanitize_component(&req.job_id),
        sanitize_component(&req.item_id)
    ));
    let _ = delete_stale_staging_dir(&staging_root);
    let used_scratch = selection.is_scratch();
    let staging = selection.into_staging_dir(staging_root, req.job_id.clone());
    fs::create_dir_all(&staging.root).map_err(MaterializeError::Io)?;
    if used_scratch {
        mark_staging_root_best_effort(&staging.root, req);
    }

    Ok(MaterializationAttempt {
        staging,
        _run_lock: run_lock,
        used_scratch,
    })
}

const OUTPUT_CAPACITY_PREFLIGHT_EXTREME_FREE_BYTES: u64 = 100 * 1024 * 1024;
const OUTPUT_CAPACITY_PREFLIGHT_MIN_HEADROOM_BYTES: u64 = 100 * 1024 * 1024;

fn nearest_existing_ancestor(path: &Path) -> Option<PathBuf> {
    path.ancestors()
        .find(|ancestor| ancestor.exists())
        .map(Path::to_path_buf)
}

fn conservative_output_capacity_preflight(req: &PipelineRequest) {
    let probe = nearest_existing_ancestor(&req.output_root)
        .unwrap_or_else(|| PathBuf::from("."));
    let Ok(free_bytes) = fs2::available_space(&probe) else {
        return;
    };
    let estimated_bytes = estimate_job_peak_bytes(&req.container, detect_source_kind(req).ok());
    let headroom_bytes = OUTPUT_CAPACITY_PREFLIGHT_MIN_HEADROOM_BYTES.max(estimated_bytes / 5);
    let advised_bytes = estimated_bytes.saturating_add(headroom_bytes);

    if free_bytes < OUTPUT_CAPACITY_PREFLIGHT_EXTREME_FREE_BYTES {
        log::warn!(
            "output capacity preflight: job_id={}, item_id={}, output_root={}, estimated_bytes={}, headroom_bytes={}, available_bytes={}, extreme_shortfall_threshold_bytes={}",
            req.job_id,
            req.item_id,
            req.output_root.display(),
            estimated_bytes,
            headroom_bytes,
            free_bytes,
            OUTPUT_CAPACITY_PREFLIGHT_EXTREME_FREE_BYTES,
        );
    } else if advised_bytes > free_bytes {
        log::warn!(
            "output capacity preflight warning: job_id={}, item_id={}, output_root={}, estimated_bytes={}, headroom_bytes={}, advised_bytes={}, available_bytes={}",
            req.job_id,
            req.item_id,
            req.output_root.display(),
            estimated_bytes,
            headroom_bytes,
            advised_bytes,
            free_bytes,
        );
    }
}

fn request_without_scratch_staging(req: &PipelineRequest) -> PipelineRequest {
    let mut disk_req = req.clone();
    disk_req.scratch_staging = None;
    disk_req
}

pub(crate) fn pipeline_report_requests_scratch_disk_retry(report: &PipelineReport) -> bool {
    report.published.is_none() && report.scratch_retry_intent.is_some()
}

pub fn scheduled_track_outputs_have_storage_exhaustion_for_scratch_retry(
    outputs: &[ScheduledTrackOutput],
) -> bool {
    outputs
        .iter()
        .any(|output| track_record_has_storage_exhaustion_for_scratch_retry(&output.record))
}

pub(crate) fn scheduled_track_outputs_have_scratch_scoped_storage_exhaustion_for_retry(
    outputs: &[ScheduledTrackOutput],
    staging_root: &Path,
    output_root: &Path,
) -> bool {
    outputs.iter().any(|output| {
        track_record_has_scratch_scoped_storage_exhaustion_for_retry(
            &output.record,
            staging_root,
            output_root,
        )
    })
}

pub fn pipeline_report_has_storage_exhaustion_for_scratch_retry(report: &PipelineReport) -> bool {
    album_outcome_has_storage_exhaustion_for_scratch_retry(&report.outcome)
}

#[allow(dead_code)] // pub(crate) API for processor postprocess retry path
pub(crate) fn pipeline_report_has_scratch_scoped_storage_exhaustion_for_retry(
    report: &PipelineReport,
    scratch_root: Option<&Path>,
    output_root: &Path,
) -> bool {
    let Some(scratch_root) = scratch_root else {
        return false;
    };
    album_outcome_has_scratch_scoped_storage_exhaustion_for_retry(
        &report.outcome,
        scratch_root,
        output_root,
    )
}

fn album_outcome_has_storage_exhaustion_for_scratch_retry(outcome: &AlbumOutcome) -> bool {
    let empty_tracks: &[TrackRecord] = &[];
    let (successful, failed, stages) = match outcome {
        AlbumOutcome::Complete { tracks, stages } => (tracks.as_slice(), empty_tracks, stages.as_slice()),
        AlbumOutcome::Partial {
            successful,
            failed,
            stages,
        } => (successful.as_slice(), failed.as_slice(), stages.as_slice()),
        AlbumOutcome::Blocked {
            successful,
            failed,
            stages,
            ..
        } => (successful.as_slice(), failed.as_slice(), stages.as_slice()),
    };

    successful
        .iter()
        .chain(failed.iter())
        .any(track_record_has_storage_exhaustion_for_scratch_retry)
        || stages.iter().any(stage_record_has_storage_exhaustion_for_scratch_retry)
}

fn track_record_has_storage_exhaustion_for_scratch_retry(record: &TrackRecord) -> bool {
    match &record.outcome {
        TrackOutcome::Ok => false,
        TrackOutcome::Err(message) | TrackOutcome::Blocked(message) => {
            storage_exhaustion_message_looks_like(message)
        }
    }
}

fn stage_record_has_storage_exhaustion_for_scratch_retry(record: &StageRecord) -> bool {
    match &record.outcome {
        StageOutcome::Failed(message) => storage_exhaustion_message_looks_like(message),
        StageOutcome::Ok | StageOutcome::Skipped => false,
    }
}

fn album_outcome_has_scratch_scoped_storage_exhaustion_for_retry(
    outcome: &AlbumOutcome,
    staging_root: &Path,
    output_root: &Path,
) -> bool {
    let empty_tracks: &[TrackRecord] = &[];
    let (successful, failed, stages) = match outcome {
        AlbumOutcome::Complete { tracks, stages } => (tracks.as_slice(), empty_tracks, stages.as_slice()),
        AlbumOutcome::Partial {
            successful,
            failed,
            stages,
        } => (successful.as_slice(), failed.as_slice(), stages.as_slice()),
        AlbumOutcome::Blocked {
            successful,
            failed,
            stages,
            ..
        } => (successful.as_slice(), failed.as_slice(), stages.as_slice()),
    };

    successful.iter().chain(failed.iter()).any(|record| {
        track_record_has_scratch_scoped_storage_exhaustion_for_retry(
            record,
            staging_root,
            output_root,
        )
    }) || stages.iter().any(|record| {
        stage_record_has_scratch_scoped_storage_exhaustion_for_retry(
            record,
            staging_root,
            output_root,
        )
    })
}

fn track_record_has_scratch_scoped_storage_exhaustion_for_retry(
    record: &TrackRecord,
    staging_root: &Path,
    output_root: &Path,
) -> bool {
    let message = match &record.outcome {
        TrackOutcome::Ok => return false,
        TrackOutcome::Err(message) | TrackOutcome::Blocked(message) => message,
    };
    if !storage_exhaustion_message_looks_like(message) {
        return false;
    }

    let output_path_is_scratch = record
        .output_file
        .as_ref()
        .map(|path| path_is_under(path, staging_root))
        .unwrap_or(false);
    let realized_path_is_scratch = record
        .realized_input
        .as_ref()
        .map(|path| path_is_under(path, staging_root))
        .unwrap_or(false);
    if output_path_is_scratch || realized_path_is_scratch || message_mentions_path(message, staging_root) {
        return true;
    }

    let output_path_is_final = record
        .output_file
        .as_ref()
        .map(|path| path_is_under(path, output_root))
        .unwrap_or(false);
    if output_path_is_final || message_mentions_path(message, output_root) {
        return false;
    }

    // Track realization and encode workers write their intermediates and outputs
    // under staging.root. When a CLI reports ENOSPC without echoing a path, a
    // scratch-backed first attempt should be retried on disk before publishing
    // a terminal failure fragment.
    true
}

fn stage_record_has_scratch_scoped_storage_exhaustion_for_retry(
    record: &StageRecord,
    staging_root: &Path,
    output_root: &Path,
) -> bool {
    let message = match &record.outcome {
        StageOutcome::Failed(message) => message,
        StageOutcome::Ok | StageOutcome::Skipped => return false,
    };
    if !storage_exhaustion_message_looks_like(message) {
        return false;
    }
    if message_mentions_path(message, staging_root) {
        return true;
    }
    if message_mentions_path(message, output_root) {
        return false;
    }

    match record.stage {
        PipelineStage::Materialize
        | PipelineStage::Convert
        | PipelineStage::Merge
        | PipelineStage::Metadata
        | PipelineStage::ReplayGain
        | PipelineStage::Features => true,
        // Publish writes to output_root. A generic publish ENOSPC is therefore
        // much more likely to be the final output filesystem, not scratch. Only
        // retry publish failures when the message explicitly names staging.root
        // above. Durable-log and output-planning failures are outside scratch.
        PipelineStage::Publish | PipelineStage::DurableLog | PipelineStage::PlanOutputs => false,
    }
}

fn path_is_under(path: &Path, root: &Path) -> bool {
    let Ok(path) = path.canonicalize() else {
        return path.starts_with(root);
    };
    let Ok(root) = root.canonicalize() else {
        return path.starts_with(root);
    };
    path.starts_with(root)
}

fn message_mentions_path(message: &str, path: &Path) -> bool {
    let rendered = path.to_string_lossy();
    !rendered.is_empty() && message.contains(rendered.as_ref())
}


fn should_defer_terminal_failure_publication_for_scratch_retry_with_root(
    req: &PipelineRequest,
    staging_is_scratch: bool,
    staging_root: &Path,
    outcome: &AlbumOutcome,
) -> bool {
    staging_is_scratch
        && album_outcome_has_scratch_scoped_storage_exhaustion_for_retry(
            outcome,
            staging_root,
            &req.output_root,
        )
}


fn scratch_retry_original_error_from_outcome(outcome: &AlbumOutcome) -> String {
    fn stage_error(stages: &[StageRecord]) -> Option<String> {
        stages.iter().rev().find_map(|stage| match &stage.outcome {
            StageOutcome::Failed(error) => Some(format!("{:?}: {}", stage.stage, error)),
            StageOutcome::Ok | StageOutcome::Skipped => None,
        })
    }

    fn track_error(records: &[TrackRecord]) -> Option<String> {
        records.iter().rev().find_map(|record| match &record.outcome {
            TrackOutcome::Err(error) | TrackOutcome::Blocked(error) => Some(error.clone()),
            TrackOutcome::Ok => None,
        })
    }

    match outcome {
        AlbumOutcome::Complete { stages, .. } => stage_error(stages),
        AlbumOutcome::Partial { failed, stages, .. }
        | AlbumOutcome::Blocked { failed, stages, .. } => {
            stage_error(stages).or_else(|| track_error(failed))
        }
    }
    .unwrap_or_else(|| "scratch-scoped storage exhaustion".to_string())
}

fn retryable_scratch_failure_report_without_publication(
    req: &PipelineRequest,
    source: Option<PreparedSource>,
    plan: Option<AlbumPlan>,
    artifacts: Option<ArtifactSet>,
    outcome: AlbumOutcome,
) -> PipelineReport {
    let original_error = scratch_retry_original_error_from_outcome(&outcome);
    PipelineReport {
        request: RedactedPipelineRequest::from(req),
        source,
        plan,
        artifacts,
        published: None,
        outcome,
        durable_log: None,
        scratch_retry_intent: Some(ScratchRetryIntent { original_error }),
        settings_fingerprint: Some(tonepoet_pipeline::fingerprint::settings_fingerprint(&req.settings)),
        manifest_path: None,
    }
}

fn materialize_error_is_storage_exhaustion(err: &MaterializeError) -> bool {
    match err {
        MaterializeError::Io(io_err) => is_storage_exhaustion_io_error(io_err),
        MaterializeError::Cancelled | MaterializeError::BlockedSource { .. } => false,
        _ => storage_exhaustion_message_looks_like(&err.to_string()),
    }
}

#[cfg(test)]
fn publish_error_is_storage_exhaustion(err: &PublishError) -> bool {
    match err {
        PublishError::Io(io_err) => is_storage_exhaustion_io_error(io_err),
        _ => storage_exhaustion_message_looks_like(&err.to_string()),
    }
}

fn is_storage_exhaustion_io_error(err: &io::Error) -> bool {
    if err.kind() == io::ErrorKind::WriteZero {
        return true;
    }

    #[cfg(unix)]
    {
        // Linux/macOS: ENOSPC, EDQUOT, EFBIG. Treat these as scratch-capacity
        // failures eligible for one disk retry when the first attempt used
        // scratch staging.
        if matches!(err.raw_os_error(), Some(28) | Some(122) | Some(27)) {
            return true;
        }
    }

    #[cfg(windows)]
    {
        // ERROR_DISK_FULL, ERROR_HANDLE_DISK_FULL.
        if matches!(err.raw_os_error(), Some(112) | Some(39)) {
            return true;
        }
    }

    storage_exhaustion_message_looks_like(&err.to_string())
}

fn storage_exhaustion_message_looks_like(message: &str) -> bool {
    let lower = message.to_ascii_lowercase();
    [
        "no space left on device",
        "enospc",
        "disk full",
        "not enough space",
        "quota exceeded",
        "edquot",
        "file too large",
        "efbig",
    ]
    .iter()
    .any(|needle| lower.contains(needle))
}

fn select_staging_parent_for(req: &PipelineRequest) -> StagingParentSelection {
    let disk_parent = disk_staging_parent_for(req);
    let Some(scratch) = req.scratch_staging.as_ref() else {
        return StagingParentSelection::disk(disk_parent);
    };

    let scratch_parent = scratch.root().join(STAGING_PARENT_NAME);
    if let Err(err) = scratch.ensure_usable(&scratch_parent) {
        log::warn!(
            "scratch staging unavailable for item {} at {}; falling back to disk staging at {}: {err}",
            req.item_id,
            scratch_parent.display(),
            disk_parent.display(),
        );
        return StagingParentSelection::disk(disk_parent);
    }

    let source_kind = detect_source_kind(req).ok();
    let estimated_bytes = estimate_job_peak_bytes(&req.container, source_kind);
    match scratch.try_reserve(estimated_bytes) {
        Ok(reservation) => {
            let reservation = reservation.with_log_context(
                req.job_id.clone(),
                req.item_id.clone(),
                scratch_parent.clone(),
            );
            log::info!(
                "scratch admitted: job_id={}, item_id={}, estimated_bytes={}, budget_remaining_after_admission={}, scratch_path={}, {}",
                req.job_id,
                req.item_id,
                format_bytes(reservation.bytes()),
                format_bytes(reservation.remaining_after_reservation_bytes()),
                scratch_parent.display(),
                reservation.admission_summary(),
            );
            StagingParentSelection::scratch(scratch_parent, reservation)
        }
        Err(err) => {
            match err.kind() {
                ScratchAdmissionFailureKind::MemoryBudget => log::info!(
                    "scratch rejected: memory budget: job_id={}, item_id={}, estimated_bytes={}, scratch_path={}, disk_staging_path={}, reason={}",
                    req.job_id,
                    req.item_id,
                    format_bytes(estimated_bytes),
                    scratch_parent.display(),
                    disk_parent.display(),
                    err.reason(),
                ),
                ScratchAdmissionFailureKind::FilesystemCapacity => log::info!(
                    "scratch rejected: filesystem capacity: job_id={}, item_id={}, estimated_bytes={}, scratch_path={}, disk_staging_path={}, reason={}",
                    req.job_id,
                    req.item_id,
                    format_bytes(estimated_bytes),
                    scratch_parent.display(),
                    disk_parent.display(),
                    err.reason(),
                ),
                ScratchAdmissionFailureKind::AvailableMemory => log::info!(
                    "scratch rejected: available memory: job_id={}, item_id={}, estimated_bytes={}, scratch_path={}, disk_staging_path={}, reason={}",
                    req.job_id,
                    req.item_id,
                    format_bytes(estimated_bytes),
                    scratch_parent.display(),
                    disk_parent.display(),
                    err.reason(),
                ),
                ScratchAdmissionFailureKind::Disabled => log::info!(
                    "scratch rejected: disabled: job_id={}, item_id={}, estimated_bytes={}, scratch_path={}, disk_staging_path={}, reason={}",
                    req.job_id,
                    req.item_id,
                    format_bytes(estimated_bytes),
                    scratch_parent.display(),
                    disk_parent.display(),
                    err.reason(),
                ),
            }
            StagingParentSelection::disk(disk_parent)
        }
    }
}

#[cfg(test)]
fn staging_parent_for(req: &PipelineRequest) -> PathBuf {
    // Legacy/test helper: returns the deterministic disk-backed staging parent.
    // Production scratch decisions must flow through `select_staging_parent_for`,
    // because scratch requires validation, admission, and reservation ownership.
    disk_staging_parent_for(req)
}

pub(crate) fn disk_staging_parent_for(req: &PipelineRequest) -> PathBuf {
    if req.naming.per_album_subdir {
        return req.output_root.join(STAGING_PARENT_NAME);
    }

    let parent = req
        .output_root
        .parent()
        .filter(|path| !path.as_os_str().is_empty())
        .unwrap_or_else(|| Path::new("."));
    parent.join(STAGING_PARENT_NAME)
}

#[cfg(test)]
mod scratch_staging_parent_tests {
    use super::*;
    use super::super::memory_budget::ScratchStagingConfig;

    #[test]
    fn select_staging_parent_prefers_admitted_configured_scratch_root() {
        let temp = tempfile::tempdir().expect("temp dir");
        let input = temp.path().join("input.flac");
        std::fs::write(&input, b"fake flac").expect("input");

        let mut req = pipeline_test_helpers::log_test_request();
        req.container = input;
        req.output_root = temp.path().join("out");
        req.scratch_staging = Some(ScratchStagingConfig::with_fixed_memory_and_filesystem_for_test(
            temp.path().join("scratch"),
            50,
            10 * 1024 * 1024 * 1024,
            10 * 1024 * 1024 * 1024,
            10 * 1024 * 1024 * 1024,
            10 * 1024 * 1024 * 1024,
        ));

        let selection = select_staging_parent_for(&req);
        assert_eq!(
            selection.parent,
            temp.path().join("scratch").join(STAGING_PARENT_NAME),
        );
        assert!(selection.is_scratch());
    }

    #[test]
    fn zero_percent_scratch_budget_falls_back_to_disk_parent() {
        let temp = tempfile::tempdir().expect("temp dir");
        let input = temp.path().join("input.flac");
        std::fs::write(&input, b"fake flac").expect("input");

        let mut req = pipeline_test_helpers::log_test_request();
        req.container = input;
        req.output_root = temp.path().join("out");
        req.scratch_staging = Some(ScratchStagingConfig::new(temp.path().join("scratch"), 0));

        let selection = select_staging_parent_for(&req);
        assert_eq!(selection.parent, disk_staging_parent_for(&req));
        assert!(selection.scratch_reservation.is_none());
    }

    #[test]
    fn scratch_space_shortfall_falls_back_to_disk_before_materialization() {
        let temp = tempfile::tempdir().expect("temp dir");
        let input = temp.path().join("input.flac");
        std::fs::write(&input, b"fake flac").expect("input");

        let mut req = pipeline_test_helpers::log_test_request();
        req.container = input;
        req.output_root = temp.path().join("out");
        req.scratch_staging = Some(ScratchStagingConfig::with_fixed_memory_and_filesystem_for_test(
            temp.path().join("scratch"),
            90,
            10 * 1024 * 1024 * 1024,
            10 * 1024 * 1024 * 1024,
            10 * 1024 * 1024 * 1024,
            64 * 1024 * 1024,
        ));

        let selection = select_staging_parent_for(&req);

        assert_eq!(selection.parent, disk_staging_parent_for(&req));
        assert!(selection.scratch_reservation.is_none());
    }

    #[test]
    fn scratch_materialization_attempt_creates_intermediate_root_under_scratch_and_drop_cleans_it() {
        let temp = tempfile::tempdir().expect("temp dir");
        let input = temp.path().join("input.flac");
        std::fs::write(&input, b"fake flac").expect("input");

        let scratch = ScratchStagingConfig::with_fixed_memory_and_filesystem_for_test(
            temp.path().join("scratch"),
            90,
            10 * 1024 * 1024 * 1024,
            10 * 1024 * 1024 * 1024,
            10 * 1024 * 1024 * 1024,
            10 * 1024 * 1024 * 1024,
        );
        let mut req = pipeline_test_helpers::log_test_request();
        req.container = input;
        req.output_root = temp.path().join("out");
        req.scratch_staging = Some(scratch.clone());

        let selection = select_staging_parent_for(&req);
        assert!(selection.is_scratch(), "ample memory and scratch filesystem space should admit scratch staging");
        let scratch_parent = selection.parent.clone();
        let attempt = prepare_materialization_attempt(&req, selection).expect("scratch materialization attempt");
        let staging_root = attempt.staging.root.clone();

        assert!(staging_root.starts_with(&scratch_parent));
        assert!(staging_root.exists(), "scratch staging root should exist during materialization");
        assert!(
            staging_root.join(".tonepoet-staging-owner").exists(),
            "scratch staging roots should carry an ownership marker for precise stale cleanup"
        );
        assert!(scratch.active_reserved_bytes_for_test() > 0);

        drop(attempt);

        assert!(!staging_root.exists(), "dropping the owning staging dir should clean scratch intermediates");
        assert_eq!(scratch.active_reserved_bytes_for_test(), 0);
    }

    #[test]
    fn zero_percent_disk_fallback_materialization_creates_output_relative_staging() {
        let temp = tempfile::tempdir().expect("temp dir");
        let input = temp.path().join("input.flac");
        std::fs::write(&input, b"fake flac").expect("input");

        let mut req = pipeline_test_helpers::log_test_request();
        req.container = input;
        req.output_root = temp.path().join("out");
        req.scratch_staging = Some(ScratchStagingConfig::new(temp.path().join("scratch"), 0));

        let selection = select_staging_parent_for(&req);
        assert!(!selection.is_scratch());
        let disk_parent = disk_staging_parent_for(&req);
        assert_eq!(selection.parent, disk_parent);

        let attempt = prepare_materialization_attempt(&req, selection).expect("disk materialization attempt");
        let staging_root = attempt.staging.root.clone();
        assert!(staging_root.starts_with(&disk_parent));
        assert!(staging_root.exists());
        assert!(
            !staging_root.starts_with(temp.path().join("scratch")),
            "0% scratch budget must not create a scratch-backed materialization attempt"
        );
        drop(attempt);
        assert!(!staging_root.exists());
    }

    #[test]
    fn scratch_materialization_storage_exhaustion_retries_on_disk_and_releases_reservation() {
        let temp = tempfile::tempdir().expect("temp dir");
        let input = temp.path().join("input.flac");
        std::fs::write(&input, b"fake flac").expect("input");

        let scratch = ScratchStagingConfig::with_fixed_memory_and_filesystem_for_test(
            temp.path().join("scratch"),
            90,
            10 * 1024 * 1024 * 1024,
            10 * 1024 * 1024 * 1024,
            10 * 1024 * 1024 * 1024,
            10 * 1024 * 1024 * 1024,
        );
        let mut req = pipeline_test_helpers::log_test_request();
        req.container = input;
        req.output_root = temp.path().join("out");
        req.scratch_staging = Some(scratch.clone());

        let selection = select_staging_parent_for(&req);
        assert!(selection.is_scratch());
        let scratch_parent = selection.parent.clone();
        let disk_parent = disk_staging_parent_for(&req);
        let mut attempts: Vec<(PathBuf, bool)> = Vec::new();

        let run = materialize_with_optional_disk_retry_for_test(
            &req,
            selection,
            &CancellationToken::new(),
            |staging| {
                attempts.push((staging.root.clone(), staging.is_scratch_staging()));
                if staging.is_scratch_staging() {
                    Err(MaterializeError::Io(io::Error::new(
                        io::ErrorKind::WriteZero,
                        "scratch write returned zero bytes",
                    )))
                } else {
                    Ok(pipeline_test_helpers::log_test_source())
                }
            },
        );

        match run {
            MaterializationRun::Attempted { attempt, result } => {
                assert!(result.is_ok(), "disk fallback materialization should succeed");
                assert!(!attempt.used_scratch, "the retained attempt should be disk-backed");
                assert!(attempt.staging.root.starts_with(&disk_parent));
                drop(attempt);
            }
            MaterializationRun::FailedBeforeAttempt { error, context } => {
                panic!("materialization retry should not fail before attempt ({context}): {error}");
            }
        }

        assert_eq!(attempts.len(), 2, "scratch attempt plus one disk retry");
        assert!(attempts[0].0.starts_with(&scratch_parent));
        assert!(attempts[0].1, "first attempt is scratch-backed");
        assert!(attempts[1].0.starts_with(&disk_parent));
        assert!(!attempts[1].1, "second attempt is disk-backed");
        assert_eq!(
            scratch.active_reserved_bytes_for_test(),
            0,
            "scratch reservation is released before/after disk fallback"
        );
    }

    #[test]
    #[cfg(any(unix, windows))]
    fn cross_device_publish_copy_fallback_copies_payload_when_rename_reports_exdev() {
        let temp = tempfile::tempdir().expect("temp dir");
        let scratch_parent = temp.path().join("scratch");
        let output_parent = temp.path().join("out");
        std::fs::create_dir_all(&scratch_parent).expect("scratch parent");
        std::fs::create_dir_all(&output_parent).expect("output parent");

        let src = scratch_parent.join("01.flac");
        let dst = output_parent.join("01.flac");
        std::fs::write(&src, b"published audio bytes").expect("source payload");

        copy_or_rename_into_publish_temp_with(&src, &dst, false, |_src, _dst| {
            #[cfg(unix)]
            {
                Err(io::Error::from_raw_os_error(18))
            }
            #[cfg(windows)]
            {
                Err(io::Error::from_raw_os_error(17))
            }
        })
        .expect("EXDEV should fall back to copy when same_filesystem_required=false");

        assert_eq!(std::fs::read(&dst).expect("copied output"), b"published audio bytes");
        assert!(src.exists(), "cross-device copy leaves cleanup to staging drop");
    }

    #[test]
    #[cfg(any(unix, windows))]
    fn cross_device_publish_respects_same_filesystem_required_guardrail() {
        let temp = tempfile::tempdir().expect("temp dir");
        let src = temp.path().join("scratch.flac");
        let dst = temp.path().join("out.flac");
        std::fs::write(&src, b"audio").expect("source payload");

        let err = copy_or_rename_into_publish_temp_with(&src, &dst, true, |_src, _dst| {
            #[cfg(unix)]
            {
                Err(io::Error::from_raw_os_error(18))
            }
            #[cfg(windows)]
            {
                Err(io::Error::from_raw_os_error(17))
            }
        })
        .expect_err("same_filesystem_required=true must reject cross-device publish");

        assert!(matches!(err, PublishError::CrossDeviceCopy(_)));
        assert!(!dst.exists());
    }

    #[test]
    fn scratch_retry_classifiers_cover_post_materialization_stage_and_track_failures() {
        for retryable_stage in [
            PipelineStage::Merge,
            PipelineStage::Metadata,
            PipelineStage::ReplayGain,
            PipelineStage::Features,
        ] {
            let stage = StageRecord {
                stage: retryable_stage,
                outcome: StageOutcome::Failed("stage failed: No space left on device".to_string()),
                dsd_dst_stats: None,
            };
            assert!(stage_record_has_storage_exhaustion_for_scratch_retry(&stage));

            let outcome = AlbumOutcome::Blocked {
                successful: Vec::new(),
                failed: Vec::new(),
                stages: vec![stage],
                reason: BlockReason::RequiredStageFailure(retryable_stage),
            };
            assert!(album_outcome_has_storage_exhaustion_for_scratch_retry(&outcome));
        }

        let track = pipeline_test_helpers::log_test_source()
            .tracks
            .into_iter()
            .next()
            .expect("test track");
        let output = scheduled_worker_failure_output(
            0,
            &track,
            None,
            None,
            "encoder failed: quota exceeded".to_string(),
        );
        assert!(scheduled_track_outputs_have_storage_exhaustion_for_scratch_retry(&[output]));
    }


    #[test]
    fn scratch_scoped_retry_classifier_does_not_misclassify_output_publish_enospc() {
        let scratch_root = PathBuf::from("/dev/shm/tonepoet/.tonepoet-staging/job-1-item-1");
        let output_root = PathBuf::from("/music/output");

        let merge = StageRecord {
            stage: PipelineStage::Merge,
            outcome: StageOutcome::Failed("merge failed: No space left on device".to_string()),
            dsd_dst_stats: None,
        };
        assert!(stage_record_has_scratch_scoped_storage_exhaustion_for_retry(
            &merge,
            &scratch_root,
            &output_root,
        ));

        let generic_publish = StageRecord {
            stage: PipelineStage::Publish,
            outcome: StageOutcome::Failed("publish failed: No space left on device".to_string()),
            dsd_dst_stats: None,
        };
        assert!(
            !stage_record_has_scratch_scoped_storage_exhaustion_for_retry(
                &generic_publish,
                &scratch_root,
                &output_root,
            ),
            "generic publish ENOSPC should be treated as output filesystem exhaustion, not scratch"
        );

        let output_publish = StageRecord {
            stage: PipelineStage::Publish,
            outcome: StageOutcome::Failed(format!(
                "copy to {} failed: No space left on device",
                output_root.join("Album/.Album.tmp/01.flac").display(),
            )),
            dsd_dst_stats: None,
        };
        assert!(!stage_record_has_scratch_scoped_storage_exhaustion_for_retry(
            &output_publish,
            &scratch_root,
            &output_root,
        ));

        let scratch_publish = StageRecord {
            stage: PipelineStage::Publish,
            outcome: StageOutcome::Failed(format!(
                "read from {} failed: No space left on device",
                scratch_root.join("converted/01.flac").display(),
            )),
            dsd_dst_stats: None,
        };
        assert!(stage_record_has_scratch_scoped_storage_exhaustion_for_retry(
            &scratch_publish,
            &scratch_root,
            &output_root,
        ));
    }

    #[test]
    fn queued_track_scratch_exhaustion_is_detected_before_album_finalization() {
        let scratch_root = PathBuf::from("/dev/shm/tonepoet/.tonepoet-staging/job-1-item-1");
        let output_root = PathBuf::from("/music/output");
        let track = pipeline_test_helpers::log_test_source()
            .tracks
            .into_iter()
            .next()
            .expect("test track");

        let scratch_output = scheduled_worker_failure_output(
            0,
            &track,
            Some(scratch_root.join("converted/.track-0000.work/input.wav")),
            Some(scratch_root.join("converted/01.flac")),
            "encoder failed: No space left on device".to_string(),
        );
        assert!(scheduled_track_outputs_have_scratch_scoped_storage_exhaustion_for_retry(
            &[scratch_output],
            &scratch_root,
            &output_root,
        ));

        let output_failure = scheduled_worker_failure_output(
            0,
            &track,
            None,
            Some(output_root.join("Album/01.flac")),
            "encoder failed: No space left on device".to_string(),
        );
        assert!(!scheduled_track_outputs_have_scratch_scoped_storage_exhaustion_for_retry(
            &[output_failure],
            &scratch_root,
            &output_root,
        ));
    }

    #[test]
    fn storage_exhaustion_classifier_recognizes_capacity_failures_only() {
        #[cfg(unix)]
        assert!(materialize_error_is_storage_exhaustion(&MaterializeError::Io(
            io::Error::from_raw_os_error(28),
        )));
        assert!(materialize_error_is_storage_exhaustion(&MaterializeError::Parse(
            "ffmpeg failed: No space left on device".to_string(),
        )));
        assert!(publish_error_is_storage_exhaustion(&PublishError::Io(
            io::Error::new(io::ErrorKind::WriteZero, "short write")
        )));
        assert!(!materialize_error_is_storage_exhaustion(&MaterializeError::Parse(
            "ffmpeg failed: invalid data found when processing input".to_string(),
        )));
        assert!(!materialize_error_is_storage_exhaustion(&MaterializeError::Cancelled));
    }
}

/// Build a conversion manifest from audio artifacts and source metadata.
/// Handles both per-track and merged artifact sets.
fn build_manifest_for_album(
    req: &PipelineRequest,
    source: &PreparedSource,
    artifacts: &Option<ArtifactSet>,
    album_plan: &AlbumPlan,
) -> Result<super::manifest::ConversionManifest, String> {
    use super::manifest::{TrackIdentity, ValidationStatus};
    use super::manifest_builder::{build_conversion_manifest, ManifestBuildInput, ManifestTrackBuildInput};

    let artifact_set = artifacts.as_ref().ok_or("no artifacts available for manifest")?;
    let album_relative = |final_path: &std::path::Path| -> Result<std::path::PathBuf, String> {
        super::manifest::album_relative_output_path(&album_plan.album_dir, final_path).map_err(|err| {
            format!(
                "manifest output path must be inside album dir {}: {} ({err})",
                album_plan.album_dir.display(),
                final_path.display(),
            )
        })
    };

    let track_inputs = match &artifact_set.audio {
        AudioArtifacts::Tracks(track_artifacts) => {
            let mut inputs = Vec::with_capacity(track_artifacts.len());
            for artifact in track_artifacts {
                let source_path = source
                    .tracks
                    .iter()
                    .find(|t| t.id == artifact.track_id)
                    .map(|t| match &t.source_ref {
                        TrackSourceRef::StagedFile(p) => p.clone(),
                        TrackSourceRef::CueSegmentCarrier { source_image, .. } => source_image.clone(),
                        TrackSourceRef::ImageSegment { image, .. } => image.clone(),
                        TrackSourceRef::SacdTrack { iso, .. } => iso.clone(),
                        TrackSourceRef::DvdaTrack { volume_source, .. } => {
                            volume_source.original_container().clone()
                        }
                        TrackSourceRef::DvdVideoTrack { source, .. } => source.clone(),
                        TrackSourceRef::BluRayTrack { source, .. } => source.clone(),
                    })
                    .unwrap_or_else(|| req.container.clone());

                inputs.push(ManifestTrackBuildInput {
                    source_path,
                    source_audio_md5: None,
                    track_identity: TrackIdentity {
                        source_ordinal: artifact.track_id.source_ordinal as usize,
                        disc_number: artifact.track_id.disc_number,
                        track_number: Some(artifact.track_id.track_number),
                    },
                    planned_command_hash: artifact.planned_command_hash.clone().unwrap_or_default(),
                    album_relative_output_path: album_relative(&artifact.final_path)?,
                    staged_output_path: artifact.staged_path.clone(),
                    validation_status: ValidationStatus::Passed,
                    record_output_hash: req.settings.verification.verify_after_encode,
                });
            }
            inputs
        }
        AudioArtifacts::Merged(merged) => {
            let planned_command_hash = merged
                .planned_command_hash
                .clone()
                .ok_or_else(|| "merged artifact missing planned_command_hash".to_string())?;

            vec![ManifestTrackBuildInput::merged_output(
                req.container.clone(),
                planned_command_hash,
                album_relative(&merged.final_path)?,
                merged.staged_path.clone(),
                ValidationStatus::Passed,
                req.settings.verification.verify_after_encode,
            )]
        }
    };

    build_conversion_manifest(ManifestBuildInput {
        album_dir: album_plan.album_dir.clone(),
        settings: req.settings.clone(),
        tracks: track_inputs,
    })
    .map_err(|err| format!("manifest build: {err}"))
}

fn audio_artifact_count(artifacts: &ArtifactSet) -> usize {
    match &artifacts.audio {
        AudioArtifacts::Tracks(tracks) => tracks.len(),
        AudioArtifacts::Merged(_) => 1,
    }
}

fn delete_stale_staging_dir(path: &Path) -> io::Result<()> {
    if path.exists() {
        fs::remove_dir_all(path)?;
    }
    Ok(())
}

fn cancelled_outcome_from(outcome: AlbumOutcome) -> AlbumOutcome {
    AlbumOutcome::Blocked {
        successful: successful_tracks_from(&outcome),
        failed: failed_tracks_from(&outcome),
        stages: stages_from(&outcome),
        reason: BlockReason::Cancelled,
    }
}

fn push_stage(outcome: &mut AlbumOutcome, record: StageRecord) {
    match outcome {
        AlbumOutcome::Complete { stages, .. }
        | AlbumOutcome::Partial { stages, .. }
        | AlbumOutcome::Blocked { stages, .. } => stages.push(record),
    }
}

fn stages_from(outcome: &AlbumOutcome) -> Vec<StageRecord> {
    match outcome {
        AlbumOutcome::Complete { stages, .. }
        | AlbumOutcome::Partial { stages, .. }
        | AlbumOutcome::Blocked { stages, .. } => stages.clone(),
    }
}

fn successful_tracks_from(outcome: &AlbumOutcome) -> Vec<TrackRecord> {
    match outcome {
        AlbumOutcome::Complete { tracks, .. } => tracks.clone(),
        AlbumOutcome::Partial { successful, .. } | AlbumOutcome::Blocked { successful, .. } => {
            successful.clone()
        }
    }
}

fn failed_tracks_from(outcome: &AlbumOutcome) -> Vec<TrackRecord> {
    match outcome {
        AlbumOutcome::Complete { .. } => Vec::new(),
        AlbumOutcome::Partial { failed, .. } | AlbumOutcome::Blocked { failed, .. } => {
            failed.clone()
        }
    }
}

