    fn conversion_related_file_names(album_dir: &Path) -> Vec<String> {
        let mut names = std::fs::read_dir(album_dir)
            .expect("album dir")
            .map(|entry| entry.expect("album entry").file_name().to_string_lossy().to_string())
            .filter(|name| name.contains("conversion"))
            .collect::<Vec<_>>();
        names.sort();
        names
    }

    pub(super) fn fragment_test_time(offset_seconds: i64) -> chrono::DateTime<chrono::Utc> {
        chrono::DateTime::parse_from_rfc3339("2026-06-16T00:00:00Z")
            .expect("base fragment timestamp")
            .with_timezone(&chrono::Utc)
            + chrono::Duration::seconds(offset_seconds)
    }

