    #[tokio::test]
    async fn real_multitrack_source_stays_on_canonical_single_log_path() {
        // CUE sources dispatched in an album batch now participate in
        // fragment assembly (see
        // cue_album_batch_stages_one_hidden_fragment_per_decomposed_track).
        // The surviving contract pinned here: a STANDALONE one-job
        // multi-track conversion, with no dispatcher batch attached, keeps
        // the canonical single conversion.log and never enters fragment mode.
        let temp = tempfile::tempdir().expect("temp dir");
        let mut req = log_test_request();
        req.output_root = temp.path().join("out");
        req.album_batch = None;
        req.album_batch_track = None;
        let album_dir = real_fragment_album_dir(temp.path());
        let mut source = log_test_source();
        source.kind = SourceKind::CueImage;
        source.container = real_fragment_source_root(temp.path()).join("album.cue");
        source.provenance.source_kind = SourceKind::CueImage;
        let artifacts = ArtifactSet {
            audio: AudioArtifacts::Tracks(vec![
                TrackArtifact {
                    track_id: source.tracks[0].id.clone(),
                    staged_path: temp.path().join("cue-stage/01.flac"),
                    final_path: album_dir.join("01.flac"),
                    samples: Some(44_100),
                    metadata_satisfaction: PlannedMetadataSatisfaction::none(),
                    metadata_required: PlannedMetadataSatisfaction::none(),
                    planned_command_hash: None,
                },
                TrackArtifact {
                    track_id: source.tracks[1].id.clone(),
                    staged_path: temp.path().join("cue-stage/02.flac"),
                    final_path: album_dir.join("02.flac"),
                    samples: Some(44_100),
                    metadata_satisfaction: PlannedMetadataSatisfaction::none(),
                    metadata_required: PlannedMetadataSatisfaction::none(),
                    planned_command_hash: None,
                },
            ]),
            sidecars: Vec::new(),
        };
        let outcome = AlbumOutcome::Complete {
            tracks: vec![ok_record(), failed_record()],
            stages: stage_records(),
        };
        // Standalone conversions publish through build_publish_plan with the
        // planner-chosen album dir; the fragment-or-fallback builder is the
        // batch dispatcher's path and now requires a fragment sidecar.
        let staging = StagingDir::new(
            temp.path().join("real-cue-existing-log-path"),
            "real-cue-existing-log-path".to_string(),
        );
        std::fs::create_dir_all(&staging.root).expect("staging root");
        let runner = crate::convert::pipeline::tool::StubToolRunner::new();
        let cancel = CancellationToken::new();
        let (staged, _features) = run_features(
            artifacts,
            &outcome,
            &source,
            &req,
            &staging,
            &runner,
            &cancel,
        )
        .await
        .expect("real feature path stages conversion-log sidecars");
        let plan = build_publish_plan(&staged, &req, &album_dir)
            .expect("standalone publish plan builds against the planner album dir");
        drop(staging);

        assert!(
            plan.entries.iter().any(|entry| matches!(&entry.role, PublishRole::Sidecar(SidecarKind::ConversionLog))),
            "one-job multi-track sources keep the canonical standalone conversion.log sidecar"
        );
        assert!(
            plan.entries.iter().all(|entry| !is_conversion_log_fragment_role(&entry.role)),
            "one-job multi-track sources must not enter fragment mode"
        );
    }

    #[test]
    fn sequential_single_file_publishes_share_album_folder_and_append_conversion_log() {
        let temp = tempfile::tempdir().expect("temp dir");
        let out = temp.path().join("out");
        let album_dir = out.join("Album");
        std::fs::create_dir_all(&out).expect("output root");
        let publish = incremental_test_publish_policy();

        let (first_staging, first_audio, first_log) = incremental_test_staging(
            temp.path(),
            "stage-first",
            "01.flac",
            b"audio-one",
            b"first log without trailing newline",
        );
        let first_plan = incremental_single_track_plan(&album_dir, first_audio, "01.flac", first_log);
        let first = publish_album_output(first_staging, &first_plan, publish.clone(), None)
            .expect("first publish creates the album folder");
        assert_eq!(first.entries.len(), 2);
        assert_eq!(std::fs::read(album_dir.join("01.flac")).unwrap(), b"audio-one");

        let (second_staging, second_audio, second_log) = incremental_test_staging(
            temp.path(),
            "stage-second",
            "02.flac",
            b"audio-two",
            b"second log\n",
        );
        let second_plan = incremental_single_track_plan(&album_dir, second_audio, "02.flac", second_log);
        let second = publish_album_output(second_staging, &second_plan, publish, None)
            .expect("second independent track appends to the existing album folder");

        assert_eq!(second.entries.len(), 2);
        assert_eq!(std::fs::read(album_dir.join("01.flac")).unwrap(), b"audio-one");
        assert_eq!(std::fs::read(album_dir.join("02.flac")).unwrap(), b"audio-two");
        let log = std::fs::read_to_string(album_dir.join("conversion.log")).expect("conversion log");
        assert!(log.contains("first log without trailing newline\nsecond log"));
        assert_eq!(conversion_related_file_names(&album_dir), vec!["conversion.log".to_string()]);
    }

    #[test]
    fn concurrent_single_file_publishes_share_album_folder_and_append_one_conversion_log() {
        let temp = tempfile::tempdir().expect("temp dir");
        let out = temp.path().join("out");
        let album_dir = out.join("Album");
        std::fs::create_dir_all(&out).expect("output root");
        let publish = incremental_test_publish_policy();

        let (first_staging, first_audio, first_log) = incremental_test_staging(
            temp.path(),
            "stage-concurrent-first",
            "01.flac",
            b"concurrent-audio-one",
            b"first concurrent log\n",
        );
        let first_plan = incremental_single_track_plan(&album_dir, first_audio, "01.flac", first_log);

        let (second_staging, second_audio, second_log) = incremental_test_staging(
            temp.path(),
            "stage-concurrent-second",
            "02.flac",
            b"concurrent-audio-two",
            b"second concurrent log\n",
        );
        let second_plan = incremental_single_track_plan(&album_dir, second_audio, "02.flac", second_log);

        let start = std::sync::Arc::new(std::sync::Barrier::new(3));
        let first_start = start.clone();
        let first_publish = publish.clone();
        let first_handle = std::thread::spawn(move || {
            first_start.wait();
            publish_album_output(first_staging, &first_plan, first_publish, None)
        });

        let second_start = start.clone();
        let second_handle = std::thread::spawn(move || {
            second_start.wait();
            publish_album_output(second_staging, &second_plan, publish, None)
        });

        start.wait();
        let first = first_handle
            .join()
            .expect("first publish thread joins")
            .expect("first concurrent publish succeeds");
        let second = second_handle
            .join()
            .expect("second publish thread joins")
            .expect("second concurrent publish succeeds");

        assert_eq!(first.entries.len(), 2);
        assert_eq!(second.entries.len(), 2);
        assert_eq!(std::fs::read(album_dir.join("01.flac")).unwrap(), b"concurrent-audio-one");
        assert_eq!(std::fs::read(album_dir.join("02.flac")).unwrap(), b"concurrent-audio-two");
        let log = std::fs::read_to_string(album_dir.join("conversion.log")).expect("conversion log");
        assert_eq!(log.matches("first concurrent log\n").count(), 1);
        assert_eq!(log.matches("second concurrent log\n").count(), 1);
        assert_eq!(conversion_related_file_names(&album_dir), vec!["conversion.log".to_string()]);
        assert!(
            !album_lock_path(&album_dir).exists(),
            "publish must remove the hidden album lock after successful publish"
        );
        assert!(
            !legacy_album_lock_path(&album_dir).exists(),
            "publish must not leave a visible Album.lock file"
        );
    }

